pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps in (0,10) are unusable for any item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the average residual
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // Lookahead coupling: if next item fits into the post residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post residual is small but nonzero and cannot fit the next item, penalize
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        score += 45.0 - (fitting_bins_count as f64) * 12.0;
    }

    // Mild late-stream consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits (item dominates the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: penalize using a bin when many bins are open,
    // unless this is the last chance to fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (1.0 + progress);
    if fitting_bins_count > 1 {
        score += 0.5 * pressure;
    } else {
        // Last fitting bin: strong discount to avoid opening a new bin.
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when
    // existing bins would create bad dead space or are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score = 45.0 + 0.3 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Slight preference for bins below mean residual (consolidating waste).
    score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 25.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress);

    // Last-chance bonus: this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0;
        }
    }
    // If next item would be stranded by a small gap, penalize.
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Mean residual coupling: penalize placing into bins far from the mean residual
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: mildly discourage opening a new bin unless the item is large
    // and few bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -1.0;
        if item_size >= 50 && open_bins_count < 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
