    if post_residual > 0 && post_residual <= 9 {
        score += 60.0;
    } else if post_residual > 9 && post_residual <= 15 {
        score += 25.0;
    }

    // Reward tight fits (post_residual as small as possible, but usable).
    score += post_residual as f64 * 0.4;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Pressure: with many open bins, prefer filling existing ones (penalize new bin).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: penalize by default so we only open when fits are bad.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.3;
        // If item is large relative to mean residual, opening a new bin is more acceptable.
        if (item_size as f64) > mean_residual {
            score -= 25.0;
        }
    }

    // Lookahead: if next item could use the remaining space, reward keeping it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        score += 8.0; // dead space for the known next item
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible.
            score -= 40.0 + (post_residual - next_item_size) as f64 * -0.5;
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 1.5;
        }
    }

    // Compare residual against mean residual of open bins.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for filling fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (1.0 - progress) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "clean" classes
    // (0, and small divisible chunks) are more reusable by future items.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: ideal outcome, strongly favored.
        score -= 1000.0;
    } else if pr <= 5 {
        // Near-perfect fit: tiny dead space, still excellent.
        score -= 700.0 + (5 - pr) as f64 * 50.0;
    } else {
        // Classify residual by harmonic bucket: residuals that are multiples of
        // common item sizes (10/20/25/50) pair well with typical items.
        let harmonic = (pr % 10 == 0) as f64 * 120.0
            + (pr % 20 == 0) as f64 * 80.0
            + (pr % 25 == 0) as f64 * 60.0
            + (pr % 50 == 0) as f64 * 60.0;
        score -= harmonic;

        // Integer-division threshold: mid-range residuals (30..70) are the
        // most usable "sweet spot" for typical item sizes.
        if pr >= 30 && pr <= 70 {
            score -= 90.0;
        }
        // Very large post-residuals are fine too (bin stays flexible).
        if pr > 70 {
            score -= 40.0;
        }
        // Awkward narrow band 6..15: likely dead space.
        if pr < 15 {
            score += 60.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post-residual, this is
    // a chain placement — heavily reward it.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 800.0;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 200.0 - slack as f64 * 4.0;
        }
        // If next item would NOT fit, we may need another bin anyway;
        // mild penalty so we don't strand the lookahead.
        if next_item_size > pr && next_item_size <= bin_capacity {
            score += 30.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && pr < bin_capacity as u32 {
        score -= 150.0;
    }

    // Prefer fuller bins when many bins are open (reduce fragmentation).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 80.0;

    // Early in the stream, keep bins flexible (favor balanced residuals);
    // later, pack aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (100.0 - post_residual as f64) * 0.5;

    // Nudge toward bins whose residual is near the mean (avoid outliers).
    score -= 20.0 - ((bin_residual as f64 - mean_residual).abs() * 0.2).min(20.0);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 250.0;
        if fitting_bins_count == 0 {
            score -= 500.0;
        }
        if next_item_size > 0 && next_item_size >= 50 && pr >= 50 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain placement possible: reward proportional to tightness of chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.3 * slack;
        } else {
            // Dead space that the next item cannot use: penalize dead space hard,
            // scaled by how much of the bin is wasted.
            let waste = post_residual as f64;
            score += 1.5 * waste;
        }
    }

    // Compare post_residual against the mean residual: leaving less than the mean
    // means this bin becomes the "worst" bin, mildly penalize.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.4 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (big items deserve fresh bins).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 50.0 - 70.0 * frac;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured by post_residual.

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward scaled by how well the next item fills the leftover space.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 + 25.0 * fill_ratio;
        } else {
            // Penalize dead space the next item cannot use.
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Coupling with mean residual: bins with residual far below the mean are "tighter"
    // candidates; filling them first keeps larger residuals open for future items.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.1 * residual_gap;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist, unless the item
    // is large and no bin gives a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual >= item_size as f64 * 1.05;
        if good_fit_exists && open_bins_count > 0 {
            score += 35.0;
        }
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Mild preference for using fewer bins overall: favor bins that are already
