    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Excellent: chain placement possible.
            score -= 40.0 + (post_residual - next_item_size) as f64 * -0.5;
        } else {
            // Dead space relative to next item: penalize proportionally.
            let waste = next_item_size - post_residual;
            score += waste as f64 * 1.5;
        }
    }

    // Compare residual against mean residual of open bins.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Slight preference for filling fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * (1.0 - progress) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits. Penalize large post residual non-linearly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Dead-space penalty: residuals too small to fit typical future items are wasteful.
    let dead_threshold = 25.0;
    if pr < dead_threshold {
        score += (dead_threshold - pr) * 1.8;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // rather than opening a new bin (unless post residual is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0;
        // Extra reward if next item also fits in post residual (chain packing).
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 14.0;
        }
    }

    // Lookahead coupling: reward if next item fits post-residual, penalize if it
    // would be stranded by a near-perfect fill.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as u32 >= next_item_size {
            score -= 6.0 * (1.0 - pr / cap);
        } else {
            // Next item won't fit here; slight penalty proportional to how close we were.
            score += 3.0 * (1.0 - (pr / next).min(1.0));
        }
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // existing fits are poor or stream is early (exploration phase).
    if bin_residual == bin_capacity {
        let exploration_bonus = 12.0 * (1.0 - progress);
        let fit_pressure = if fitting_bins_count == 0 { 0.0 } else { (fitting_bins_count as f64).ln() * 4.0 };
        score += 8.0 + fit_pressure - exploration_bonus;
        // If mean residual across open bins is large, discourage opening new bins.
        score += (mean_residual / cap).max(0.0) * 10.0;
    } else {
        // Prefer fuller bins among open ones when many bins are open.
        let fill_frac = 1.0 - pr / cap;
        score -= 5.0 * fill_frac * (open_bins_count as f64).sqrt().min(6.0);
    }

    // Global balance: if this bin's residual deviates far above the mean residual,
    // it's a good candidate to absorb the item (consolidate large gaps).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.06 * dev;

    // Late-stream tightening: near the end, be very greedy about filling bins.
    score -= 10.0 * progress * (1.0 - pr / cap);

    // Small tie-breaker on exact fit.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: f64, fitting_bins_count: usize) -> f64 {
    let _ = item_size;
    let _ = bin_residual;
    let _ = bin_capacity;
    let _ = open_bins_count;
    let _ = mean_residual;
    let _ = next_item_size;
    let _ = fitting_bins_count;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;
    score -= 12.0 * (progress * (1.0 - progress) * 4.0);
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are less useful; penalize dead space strongly.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fraction of capacity wasted after placement (non-linear penalty).
    score += 0.8 * (post / cap) * (post / cap) * cap;

    // Harmonic class buckets via integer division on post_residual.
    // Class 0: post_residual == 0 -> perfect fit, huge reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Class thresholds: residues in (0,10] are nearly dead space.
        let class = post_residual / 10; // 0..10 harmonic classes
        score += match class {
            0 => 18.0,                    // tiny unusable sliver
            1 => 8.0,
            2 => 3.0,
            3 => 0.0,
            4 => -4.0,
            5 => -6.0,                    // ~half capacity left, quite reusable
            6 => -5.0,
            7 => -3.0,
            8 => -1.0,
            _ => 0.0,
        };
    }

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain completion
        } else if next_item_size <= post_residual {
            // modulo harmonic match: next item leaves another small residue
            let next_post = post_residual - next_item_size;
            let nm = next_post % 10;
            if nm == 0 {
                score -= 20.0; // leaves a class-aligned residue
            } else if next_post <= 10 {
                score += 6.0; // chains into dead space
            } else {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item cannot use this bin's leftover
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    // (large post_residual relative to capacity) or bin is truly full-ish.
    if bin_residual == bin_capacity {
        // Empty bin: neutral baseline with mild exploration bonus early,
        // penalty later when many bins are open (avoid bin proliferation).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 40.0 + 25.0 * (1.0 - progress) + 4.0 * open_bins_count as f64;
        // If the item is large relative to capacity, fresh bin is fine.
        if item_size as f64 > 0.7 * cap {
            score -= 15.0;
        }
        // If lookahead is huge, a fresh bin can host both.
        if next_item_size > 0 && (item_size + next_item_size) as f64 <= cap {
            score -= 30.0;
        }
    }

    // Mild global pressure: prefer bins below mean residual (keeps balance).
    score += 0.15 * (post - mean_residual);

    // Small tie-breaker favoring tighter fits via modulo signature.
    score += (post_residual % 3) as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strong reward.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        if post_residual <= 10 {
            score += 120.0 * (11.0 - post_residual as f64);
        } else if post_residual < 20 {
            score += 30.0;
        }
    }

    // Reward residuals that can still host a typical future item.
    if post_residual >= 10 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 200.0;
        } else if gap <= 10 {
            score -= 40.0;
        }
    }
    // If next item would NOT fit here, mild penalty for chaining a bad fit.
    if next_item_size > post_residual && post_residual > 0 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost plus pressure from open bins.
        score += 60.0 + 8.0 * open_bins_count as f64;
        // Opening is more acceptable early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 40.0 * (1.0 - progress);
    } else {
        // Using an existing bin reduces open-bin pressure slightly.
        score -= 2.0 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (loose bins) to consolidate space.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact or near-exact match with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when the next item exactly fills the resulting residual.
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            // Next item still fits after this placement: mild reward, scaled by tightness.
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would NOT fit: penalize proportionally to wasted potential.
            score += 10.0 + gap * 0.5;
        }
    }

    // Penalize dead space relative to the mean residual across open bins.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 0.5 * (mean_residual - pr); // tighter than average: good
    } else {
        score += 0.3 * (pr - mean_residual); // looser than average: bad
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discourage opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by how many bins fit.
        score += 20.0 + 8.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (builds flexibility).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Small reward for very tight fits overall.
    if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 30.0 * tightness;

    // Penalize dead space that is too small to be useful later (below min item 1..100: use 10 as typical floor, but keep adaptive).
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 20.0 {
        score += 15.0 * (1.0 - dead / 20.0);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit here; penalize leaving residual the next item can't use.
            score += 5.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a decent existing fit beats a new bin.
        score += 25.0;
        // But if many bins are open with fragmented residuals, new bin is attractive.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count > 6 {
            score -= 10.0 + 5.0 * progress;
        }
        // If mean residual is small (open bins are nearly full), a fresh bin is valuable.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 20.0;
        }
    }

    // Mild global pressure: as stream progresses, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - tightness);

    // Penalize bins whose residual deviates wildly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual (good fit), with non-linear sharpening
    let mut score = x.powf(2.2) * 60.0 + x * 20.0;

    // Smooth non-linear interaction: as stream progresses, tighten fit preference more
    score += 40.0 * x.powf(2.2) * progress;

    // Penalize large dead space quadratically (wasted capacity)
    score += 0.004 * pr * pr;

    // Reward near-perfect fits via smooth exponential bonus
    score -= 25.0 * (-(pr as f64) / 12.0).exp();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits smoothly into post residual, reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            let slack = pr - nxt;
            score -= 18.0 * (-(slack / 20.0)).exp();
        } else {
            // next item won't fit; penalize slightly to prefer bins leaving usable space
            score += 6.0 * (1.0 - (-(pr / cap)).exp());
        }
    }

    // Smooth penalty for opening new bins when many bins are already open and residual is high
    let mean_r = mean_residual / cap;
    score += 10.0 * mean_r * (1.0 - progress);

    // Mild preference for filling bins when open bin count is large
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * x;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "reusable" classes (multiples of small divisors) are favored.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Reward small post_residual (tight fit) with a multiplicative pull.
    score *= 0.5 + cap_frac;

    // Dead-space penalty: post_residual in awkward low band (< 10) is nearly unusable
    // for items >= 10, but with unknown distribution treat < 5 as dead.
    if post_residual > 0 && post_residual < 5 {
        score += 25.0;
    }

    // Modulo arithmetic: leftover divisible by 4 or 5 is more likely reusable
    // under integer item sizes -> subtract a bonus.
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Harmonic compatibility: can next item fit exactly / well into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            if gap < 5 {
                score -= 6.0; // near-perfect chain
            } else {
                score -= (4.0 * (1.0 - gap as f64 / bin_capacity as f64)).max(0.0);
            }
        } else {
            // next item won't fit here: leftover must serve later items;
            // penalize leftovers that are too small to matter.
            if post_residual < 10 {
                score += 10.0;
            }
        }
    } else {
        // Last item: prefer tightest packing, reward filling bin near-full.
        score -= 5.0 * (1.0 - cap_frac);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when current bins are crowded with
    // large residuals or the fit is terrible.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        let bad_fit = item_size as f64 / bin_capacity as f64;
        if bad_fit < 0.4 && mean_residual > 30.0 {
            score -= 20.0; // open a fresh bin when existing ones are fragmented
        } else {
            score += 40.0 + crowd; // default: discourage new bins
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Mild penalty for very large item into nearly full bin creating slivers.
    if post_residual > 0 && item_size > 60 && post_residual < 15 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;

    // --- Strict dead-space avoidance ---
    // Any positive gap smaller than the smallest plausible item is permanently wasted.
    if post_residual > 0 {
        // Dead threshold: min item size (10), or the lookahead item if it is smaller.
        let dead_threshold = if next_item_size > 0 && next_item_size < 10 {
            next_item_size
        } else {
            10
        };
        if post_residual < dead_threshold {
            // Pressure scales with open_bins_count: the more bins we juggle,
            // the less tolerable a permanently unusable gap becomes.
            let pressure = 1.0 + open_bins_count as f64 / 10.0;
            score += 300.0 * pressure;
        } else if next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
            // Not strictly dead, but the known next item cannot use this gap:
            // mild penalty for likely near-dead space.
            score += 20.0;
        }
    }

    // --- Lookahead reward: gap can still host the next item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= next_item_size as f64 * 0.3;
    }

    // --- Last-chance bonus: this is the only open bin that fits ---
    // Prefer using it over opening a fresh bin, unless it creates dead space
    // (the dead-space penalty above dominates this bonus).
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- Residual-dispersion coupling: prefer bins tighter than the fleet mean ---
    let dispersion = bin_residual as f64 - mean_residual;
    if dispersion > 0.0 {
        score += dispersion * 0.1;
    }

    // --- New-bin opening pressure ---
    // Opening a bin must overcome a fixed surcharge plus a load-proportional
    // pressure that grows with the number of already-open bins.
    if is_new_bin {
        score += 5.0 + open_bins_count as f64 * 0.5;
    }

    // --- Stream-progression tilt: late in the stream, be slightly more
    //     conservative about leaving loose space in existing bins ---
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) — already captured by post_residual.

    // 2-step lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward scaled by how well the next item fills the leftover space.
            let fill_ratio = next_item_size as f64 / post_residual as f64;
            score -= 40.0 + 25.0 * fill_ratio;
        } else {
            // Penalize dead space the next item cannot use.
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Coupling with mean residual: bins with residual far below the mean are "tighter"
    // candidates; filling them first keeps larger residuals open for future items.
    let residual_gap = mean_residual - post_residual as f64;
    score += 0.1 * residual_gap;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a brand-new bin when decent open bins exist, unless the item
    // is large and no bin gives a good fit.
    if bin_residual == bin_capacity {
        let good_fit_exists = mean_residual >= item_size as f64 * 1.05;
        if good_fit_exists && open_bins_count > 0 {
            score += 35.0;
        }
        // Late in the stream, opening new bins is more wasteful.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * progress;
    }

    // Mild preference for using fewer bins overall: favor bins that are already
    // substantially filled.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fill;

    // Small penalty for very small leftovers that become dead space (< 10).
    if post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squash post_residual so small leftovers dominate.
    score *= 1.0 + (post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize dead space that no plausible future item (min size 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Lookahead: bonus if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (bin_residual - item_size) as f64;
        // Penalize new bins moderately; relax late in the stream when mean
        // residuals are fragmented.
        score += 18.0 + 20.0 * (1.0 - progress) - 0.15 * mean_residual;
        let _ = poor_fit;
    }

    // Mild preference for fuller bins when many bins are open (consolidation).
    score -= 0.05 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight time-decay on residual weight: early on, keep bins flexible.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let norm_post = post / cap;

    // Non-linear base: strongly reward tight fits (small post_residual),
    // with quadratic + quartic shaping of normalized post-residual.
    let mut score = post * (1.0 + norm_post * norm_post);

    // Smooth stream-progress coupling: later in the stream, dead space is
    // penalized more (fewer chances to reuse it), scaled by a smooth sine-free
    // polynomial ramp in progress.
    let ramp = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += ramp * norm_post * norm_post * cap * 0.5;

    // Interaction with mean residual: if this bin's post-residual deviates
    // upward from the fleet mean, penalize mildly (wasted potential).
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (smooth reward, not a hard switch).
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * ramp;
    }

    // Lookahead coupling: reward leaving post_residual that can still host
    // the next item; penalize post_residual that nearly-but-not-quite fits it.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = post - nxt;
        if gap >= 0.0 {
            score -= 6.0 * (1.0 - gap / cap); // next item fits: good
        } else {
            score += 3.0 * (-gap) / cap;      // near-miss dead space: bad
        }
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += 0.05 * (open_bins_count as f64) * norm_post;

    // New-bin candidate: neutral-ish baseline; only beats open bins when
    // their fits are poor (score above ~cap).
    if bin_residual == bin_capacity {
        score = cap * 1.05 + 2.0 * ramp;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Exact fit: perfect placement, strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of post_residual: classify leftover into usable bands.
    // Items are 1..100, so leftover classes via integer division thresholds.
    let pr = post_residual;
    let class = match pr {
        0 => 0,
        1..=10 => 1,       // dead space band
        11..=25 => 2,      // small-item usable
        26..=50 => 3,      // medium-item usable
        _ => 4,            // large leftover (bin still very usable)
    };
    // Reward usable leftovers, penalize dead-space band.
    score += match class {
        1 => 60.0,
        2 => 10.0,
        3 => -5.0,
        4 => -15.0,
        _ => 0.0,
    };

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Chain continuation is valuable; reward proportionally.
            score -= 20.0 + (pr - next_item_size) as f64 * 0.3;
        } else {
            // This placement strands the next item relative to this bin.
            score += 15.0;
            // Modulo-style harmony: if next item shares a "harmonic class"
            // with the item just placed (both small or both large), the
            // stranding is more forgivable (pairing likely elsewhere).
            let a = item_size / 25;
            let b = next_item_size / 25;
            if a == b {
                score -= 8.0;
            }
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin would leave
    // awkward dead space or mean residuals are already tight.
    if bin_residual == bin_capacity {
        // Baseline: opening a new bin is moderately costly.
        score += 45.0;
        // But if placing here would strand a large next item, new bin wins.
        if next_item_size > 0 && next_item_size > pr && pr < 25 {
            score -= 70.0;
        }
        // Early in stream with few bins, prefer consolidation.
        if open_bins_count <= 2 {
            score += 30.0;
        }
    }

    // Mild pressure against scattering when many bins are open.
    score += (open_bins_count as f64) * 0.5;

    // Tie-break toward bins with residual close to mean (keep spread tight).
    score += ((post_residual as f64) - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold the
    // smallest plausible item (<= 10) are wasted capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals too small for the lookahead item are also suspect
    // unless nothing else fits.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage opening new bins
    // when many are already open.
    score += 0.6 * open_bins_count as f64;

    // New-bin candidate: neutral-ish baseline that only wins when the
    // item fits badly everywhere; make it slightly costly so we prefer
    // reusing open bins with decent fits.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // But if opening a bin lets us keep a near-perfect future fit
        // (item is large), soften the penalty.
        if item_size >= bin_capacity * 3 / 4 {
            score -= 15.0;
        }
    }

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64).abs() * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leaves a gap; mildly reward proportional to fit tightness.
            let gap = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space: post_residual too small for next item.
            let dead = (next_item_size - post_residual) as f64;
            score += 15.0 * (dead / 100.0) * (dead / 100.0) * 100.0;
        }
    }

    // Relative-to-mean coupling: prefer bins with residuals below mean (tighter bins used first).
    score += 0.6 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize opening a new bin unless the item is large relative to capacity
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 90.0 * (1.0 - largeness);
    }

    // Stream progression: early on, be more willing to open bins (explore),
    // later, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 50.0 * (1.0 - progress);
    } else {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared residual penalty scaled by how full the bin gets.
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score += (post_residual as f64 / cap).powi(2) * 40.0;
    score -= fill * 20.0;

    // Lookahead: strongly favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
            // bonus proportional to leftover after chaining the next item
            let chain_left = post_residual - next_item_size;
            score -= (chain_left as f64 / cap) * 10.0;
        } else {
            // penalize leaving a sliver the next item can't use
            let waste = post_residual as f64;
            if waste < next_item_size as f64 {
                score += waste * 0.6;
            }
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    let is_new_bin = bin_residual == bin_capacity && open_bins_count > 0;
    if is_new_bin {
        // base cost of opening a new bin, discounted when mean residual is low
        let pressure = 1.0 - (mean_residual / cap);
        score += 35.0 * pressure;
        // early in the stream, opening bins is cheaper (build flexibility)
        let t = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - t) * 15.0;
        // if next item is huge, a fresh bin is valuable
        if next_item_size >= bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // mild preference for using bins with larger residuals among open ones
        score += (mean_residual - bin_residual as f64) * 0.15;
        // many open bins: encourage consolidation
        if open_bins_count > 4 {
            score -= 5.0;
        }
    }

    // Penalize creating dead space that nothing typical can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: post-residual, with smooth non-linear polynomial coupling to stream progress
    let mut score = pr
        - 18.0 * (1.0 - progress) * (1.0 - x) * x
        + 10.0 * progress * x * x;

    // Penalize tight fits more as stream progresses (dead space worth less early)
    score += (1.0 - progress) * (pr / (1.0 + pr));

    // Reward using bins that would otherwise be "last chance"
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress + 0.5);
    }

    // Lookahead coupling: bonus if next item fits the post-residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr as f64 {
            score -= 8.0 * (1.0 - nx / cap) * (1.0 - progress * 0.5);
        } else {
            score += 4.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for spreading across many bins relative to mean residual
    score += 0.05 * (open_bins_count as f64).ln() * (mean_residual - pr).abs();

    // New-bin candidate handling: keep it slightly unattractive unless residual is very tight
    if bin_residual == bin_capacity {
        score += 6.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Perfect or near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Dead-space penalty: leftover that cannot fit the smallest plausible item (1..100).
    // Leftovers < 10 are usually dead; leftovers in (50, cap) are still useful.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Harmonic quarter classes on post_residual (mod arithmetic on capacity fractions).
    let quarter = (post_residual * 4) / bin_capacity; // 0..3 integer class
    match quarter {
        0 => score -= 40.0,           // tiny leftover, tight fit
        1 => score += 20.0,           // quarter leftover
        2 => score -= 10.0,           // half leftover, flexible
        _ => {}                       // large leftover, neutral
    }

    // Lookahead: does next_item_size fit into post_residual? Reward chain placements.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact chain fit is gold.
            if next_item_size == post_residual {
                score -= 500.0;
            } else {
                // Reward proportional to how well next item fills the leftover.
                let fill = next_item_size as f64 / post.max(1.0);
                score -= 80.0 * fill;
            }
        } else {
            // Next item won't fit here: leftover may become dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(50.0);
        }
    } else {
        // Last item: prefer tightest fit overall.
        score -= 200.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin when decent open bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base cost of a fresh bin; reduced late in the stream when bins close anyway.
        score += 250.0 - 100.0 * progress;
        // If the item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.3 * item_size as f64;
        // If mean residual is small (open bins are crowded), fresh bin less wasteful.
        score -= (mean_residual / cap).min(1.0) * 60.0;
        // Discourage hoarding many open bins early.
        score += 8.0 * open_pressure * (1.0 - progress);
    }

    // Mild preference for fuller bins overall (tight-packing pressure).
    score -= 0.1 * (item_size as f64 / cap) * 100.0;

    // Small tie-break noise-free coupling with mean residual: prefer bins below mean fill
    // to balance, unless it's a tight fit (already handled above).
    score += 0.05 * (mean_residual - post);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps harshly.
    // Gaps below the minimum plausible item size (1..~15) are almost pure waste.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0; // tiny unusable sliver
        } else if post_residual < 20 {
            score += 25.0; // small gap, hard to fill
        } else if post_residual < 35 {
            score += 8.0; // moderate gap
        }
    } else {
        // Perfect fit: strong reward.
        score -= 80.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward if the next item exactly fills the resulting gap.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // The gap cannot host the next item: mild dead-space penalty scaled by gap size.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.5;
    }

    // Tight fit reward: item occupies a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few open bins,
    // allow opening new bins for good fits.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * 3.0;

    // Prefer bins whose residual is already below the mean (consolidating waste).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Late in the stream, be more conservative: fill existing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin gets a baseline cost so it only wins when
    // open bins would create severe dead space.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * tightness;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / (bin_capacity as f64));
        if gap == 0.0 {
            score -= 25.0; // perfect chain: this bin will be closed by the next item
        }
    } else if next_item_size > 0 {
        // Next item cannot use the leftover space -> penalize dead space
        score += 10.0;
    }

    // Compare post_residual against mean residual: avoid making this bin an outlier
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening a new bin when open bins already exist and fit is decent
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0;
    }

    // Late in the stream, prefer closing bins cleanly (smaller residuals win)
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / bin_residual as f64;

    // Reward tight fits (small post_residual already base; amplify)
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space only if it's likely unusable (below typical item sizes)
    let dead = post_residual as f64;
    if dead > 0.0 {
        // waste proportional to unusability: smaller residual relative to capacity is worse
        let unusable = dead / bin_capacity as f64;
        score += 8.0 * unusable * unusable;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins unless current fit is bad
    if is_new_bin {
        // base penalty for bin proliferation
        let mut pen = 15.0;
        // worse to open new bin when existing fits are decent (post_residual small)
        if post_residual >= 0 {
            pen += 10.0 * (1.0 - fit_ratio.min(1.0));
        }
        // early in stream: more future items, cheaper to consolidate; later: allow new bins more freely
        pen *= (1.0 - 0.5 * t);
        // if many open bins already, discourage more
        pen += 0.5 * open_bins_count as f64;
        // if next item is large, a fresh bin is valuable (lookahead)
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            pen -= 18.0;
        }
        // if no other bin fits well (post_residual of best fit large), reduce penalty
        score += pen;
    } else {
        // Reward placing into bins whose residual matches next item (lookahead pairing)
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            let gap = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        }
        // Prefer bins with residual below mean (compact bins), slight effect
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // Time horizon: early stream favors consolidation (lower score for near-full bins)
        score += 4.0 * t * (bin_residual as f64 / bin_capacity as f64);
    }

    // Global pressure: when many bins are open relative to items seen, tighten packing
    if total_items > 0 {
        let density = open_bins_count as f64 / (step_index.max(1) as f64);
        score += 3.0 * density * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with a non-linear (quadratic) penalty
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling with stream progress: late in stream, waste matters more
    score += 30.0 * progress * norm_pr * norm_pr * cap;

    // Reward tight fits more strongly as stream advances (smooth interaction)
    score -= 25.0 * progress * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Penalize large residuals relative to mean residual (dead-space coupling)
    score += 10.0 * (norm_pr - mean_residual / cap).abs();

    // Last-chance bonus: if this is the only fitting bin, favor it smoothly
    let last_chance = 1.0 / fitting_bins_count as f64;
    score -= 20.0 * last_chance * (1.0 - norm_pr);

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 {
        let fits_next = if (pr >= next_item_size as f64) { 1.0 } else { 0.0 };
        let smooth = fits_next * (1.0 - (next_item_size as f64 / cap));
        score -= 15.0 * smooth;
    } else {
        // Last item: strongly minimize post residual
        score += 20.0 * norm_pr;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.5 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse size classes (capacity fractions)
    let item_class = (item_size * 4) / bin_capacity;          // 0..3
    let next_class = ((next_item_size as u32) * 4) / bin_capacity; // 0..3 (0 if next==0)

    // Perfect-fit harmonic reward: post_residual falls on a small harmonic residue
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // exact fill — ideal
    } else if pr <= 10 {
        score -= 30.0; // near-perfect, dead space minimal
    } else if pr <= 20 {
        score -= 12.0;
    } else if pr > 50 {
        score += 8.0; // wasteful half-empty bin
    }

    // Modulo-arithmetic dead-space penalty: residuals like 1..9 (mod 10) are hard to reuse
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 2.0;
    }

    // Harmonic pairing: reward when post_residual can host next_item_size exactly
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 45.0; // guaranteed next-item fit, chain completion
        } else if pr >= next_item_size {
            score -= 10.0; // next item still fits here
            // class-complementary bonus (large + small pairs)
            if item_class + next_class >= 3 && pr >= next_item_size + 10 {
                score -= 8.0;
            }
        } else {
            score += 15.0; // next item cannot reuse this residual
            // penalize awkward residues that block future items
            if pr % 10 != 0 {
                score += (pr % 10) as f64 * 1.5;
            }
        }
    } else {
        // last item: maximize tightness
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral baseline, but discourage opening new bins
    // when a reasonable fit exists in an open bin
    if bin_residual == bin_capacity {
        score += 25.0; // base penalty for opening a new bin
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 5.0; // big next item: fresh bin slightly more attractive
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it is a good dump
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.3;
    } else {
        score += (-dev) * 0.15;
    }

    // Progress modulation: late in the stream, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize unusable dead space: gaps too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit: big reward
    if post_residual == 0 {
        score -= 100.0;
    }
    // Reward tight fits relative to bin residual
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // If next item fits in the post residual, reward (keeps bin useful)
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize when post residual can't fit next item but is still sizeable
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * post_residual as f64;
    }

    // Last chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open bins pressure: discourage opening new bins when few bins open,
    // encourage consolidation when many bins open
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize proportional to progress and open bins
        score += 25.0 + 2.0 * open_bins_count as f64 + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
        // but if all open bins fit poorly, allow new bin
        if mean_residual < item_size as f64 * 1.05 {
            score -= 30.0;
        }
    } else {
        // existing bin: slight bonus when many bins open (consolidate)
        score -= 0.2 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (fill the emptier bins first)
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 && post_residual > 0 {
        let next_fits = (next_item_size as f64) <= post_residual as f64;
        if next_fits {
            // Reward proportionally to how well next item fills the leftover.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 60.0 * next_fill;
            // Exact 2-chain: post_residual == next_item_size
            if post_residual == next_item_size {
                score -= 500.0;
            }
        } else {
            // Dead space the next item cannot use: penalize small gaps more.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 40.0 * (1.0 - gap / 100.0);
            }
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average.
    score -= 3.0 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor unless item is large
    // relative to capacity (then a fresh bin is genuinely attractive).
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 25.0 * (1.0 - large);
        if next_item_size > 0 && (next_item_size as f64) <= (bin_capacity - item_size) as f64 {
            score -= 30.0;
        }
    }

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (wasted space penalized super-linearly).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item uses leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * fill;
        } else {
            // leftover too small for next item: penalize dead space
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += 0.5 * dead;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins
    // are open or early in the stream (packing density still achievable).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual is below the mean (consolidate small leftovers).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Prefer fuller bins overall (small residual before placement).
    score += 0.2 * bin_residual as f64;

    // Late in stream: be greedier about exact fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: post_residual scaled by progress-dependent polynomial
    let poly = 1.0 + 0.5 * progress * progress + 0.25 * progress * (1.0 - progress);
    score *= poly;

    // Reward tight fits (small post_residual relative to capacity) with a smooth saturation
    let tightness = 1.0 - (post / cap);
    score -= 20.0 * tightness * tightness * tightness;

    // Penalize dead space that cannot fit a typical next item, smoothly
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap > 0.0 {
            let waste = gap / cap;
            score += 15.0 * waste * waste * (1.0 + progress);
        } else {
            // next item fits: reward chaining
            score -= 8.0 * (1.0 - progress) * (-gap / cap);
        }
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln_1p();
    }

    // Mild preference for bins below mean residual early (keep balance), stronger late
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += (2.0 + 4.0 * progress) * dev * dev * dev.signum();

    // New-bin candidate: penalize opening new bins more as stream progresses / many bins open
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress + 0.5 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post_residual strongly (quadratic).
    let pr = post_residual as f64;
    score -= 40.0 * (1.0 - pr / bin_capacity as f64).powi(3);

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: dead space that no item (>=1) can use well.
    // Small residuals (<10) are unusable dead space -> penalize mildly unless exact.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Modulo-class coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 30.0;
        } else {
            let nxt = next_item_size as f64;
            let waste = (post_residual as f64) - nxt;
            score -= 15.0 * (1.0 - waste / bin_capacity as f64);
        }
    }
    // If next item cannot fit here, this bin's leftover risks becoming dead space;
    // penalize proportional to how small the residual is relative to min item size.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0 * (10.0f64.min(next_item_size as f64) - post_residual as f64).max(0.0) / 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Opening a bin early in stream is cheap; late in stream it wastes capacity.
        score += 35.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
        // If many bins fit the item, avoid spreading.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Prefer filling bins with below-average residual (balance avoidance of many half-empty bins).
    score -= 0.05 * (mean_residual - pr).max(-50.0);

    // Harmonic class of item: large items (>= 50) should go into bins where they leave
    // a residual in a "good" class (>= next item size, or 0).
    if item_size >= bin_capacity / 2 && post_residual > 0 && post_residual < 15 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead space avoidance ---
    // Dead space = residual that is too small to fit a typical item (min size 1..100 unknown,
    // so treat "unusable" as a fraction of capacity; small gaps are likely wasted).
    let gap = post_residual as f64;
    let small_gap_threshold = 0.25 * bin_capacity as f64; // gaps < 25% capacity are suspect
    if gap > 0.0 && gap < small_gap_threshold {
        // Penalize unusable small gaps quadratically: a gap of 10 is far worse than 25.
        let unus = (small_gap_threshold - gap) / small_gap_threshold;
        score += 60.0 * unus * unus;
    }
    // Perfect or near-perfect fits are excellent: strongly subtract.
    if gap == 0 {
        score -= 80.0;
    } else if gap <= 5 {
        score -= 40.0;
    }

    // --- Tightness reward: fraction of bin consumed by this placement ---
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill * fill;

    // --- Last-chance pressure ---
    // If this is the only bin that fits the item, strongly prefer using it
    // rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Open bins pressure: discourage spreading across many bins ---
    // More open bins => mild penalty for placements that keep many bins half-full;
    // encourage consolidating into existing bins instead of opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * open_pressure;

    // --- New-bin candidate handling ---
    // A brand-new empty bin has bin_residual == bin_capacity. Opening a new bin is
    // only attractive for large items or when all existing fits leave bad gaps.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin: grows with number of already-open bins.
        score += 20.0 + 4.0 * open_bins_count as f64;
        // If the item is large, a fresh bin is reasonable (it will fill well).
        if fill > 0.7 {
            score -= 15.0 * (fill - 0.7) / 0.3;
        }
        // If this is the last chance (no other fitting bin), new bin must win.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // --- Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = next_item_size as f64 / post_residual as f64;
        if next_fit > 0.8 {
            score -= 20.0 * (next_fit - 0.8) / 0.2;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here: small penalty for leaving a gap the next item can't use.
        score += 8.0;
    }

    // --- Stream progression: early in the stream, be slightly more willing to open
    // bins flexibly; late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fill;

    // --- Mean residual coupling: if the mean residual across open bins is large,
    // we have slack; penalize creating more slack (post_residual) extra.
    if mean_residual > 30.0 {
        score += 0.15 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward a perfect fit now (no dead space).
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual,
    // penalize when post residual is too small to ever be useful.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0; // chain fit: bin fully used over two steps
        } else if next_item_size >= post_residual && post_residual > 0 {
            // next item cannot use the remaining space
            score += 25.0;
            // extra penalty if the leftover is tiny dead space
            if post_residual < 10 {
                score += 20.0;
            }
        } else {
            // next item fits after this one: mild reward scaled by tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 15.0 * tight;
        }
    }

    // Penalize leaving large residual relative to mean residual (wasteful spread).
    let cap = bin_capacity as f64;
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when the item is huge and would leave
    // an awkward residual elsewhere, or when no open bin fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        // default penalty so we prefer existing bins
        score += 15.0;
        // reward opening a new bin for very large items (poor fits elsewhere)
        if big_item > 0.6 {
            score -= 25.0 * (big_item - 0.6) / 0.4;
        }
        // if the item would leave a small dead space in any open bin, discourage new bin
        if next_item_size > 0 && post_residual == next_item_size {
            score += 40.0;
        }
        // early stream: opening bins is cheap-ish, slight discount
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Mild preference for tighter bins overall when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual), with a non-linear bonus.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else {
            score += 10.0; // blocks the lookahead item
        }
        // Perfect chain: current + next fit exactly
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: keep empty bins attractive early,
    // discourage opening new bins when open bins have slack.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 20.0 * progress;
        if mean_residual > item_size as f64 {
            score += 10.0; // existing bins have room; don't open a new one
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // reserving a fresh bin for a big item chain can help
        }
    }

    // Prefer filling bins below the mean residual (balance-aware).
    let diff = bin_residual as f64 - mean_residual;
    score += 0.15 * diff;

    // Slight preference for fewer open bins as the stream matures.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, mildly convex so small residuals are favored superlinearly.
    let mut score = pr * (1.0 + 0.6 * pr_norm * pr_norm);

    // Non-linear coupling of residual with stream progress:
    // late in the stream, tight fits matter more (dead space is never recoverable).
    let tightness = 1.0 - pr_norm; // 1.0 = perfect fit
    let progress_coupling = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score -= 18.0 * tightness * tightness * (0.5 + progress_coupling);

    // Penalize residual far from mean residual (fragmentation of the fleet),
    // with a smooth quadratic divergence term.
    let diff = pr - mean_residual;
    score += 0.05 * diff * diff / (1.0 + mean_residual * 0.01);

    // Last-chance bonus: if this is the only fitting bin, strongly reward using it
    // rather than opening a new bin (smoothly scaled by how well it fits).
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - pr_norm * pr_norm);
    }

    // Lookahead: reward leaving room for the next item (smooth interaction).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let room = (pr - nx).max(0.0) / cap;
        let perfect = ((pr as f64) - nx).abs() / cap;
        score += 6.0 * room * room - 10.0 * (1.0 - perfect).max(0.0) * progress_coupling;
    }

    // Mild penalty when many bins are open: encourage consolidation early on.
    score += 0.4 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    // New-bin candidate handling: an empty bin has maximal residual;
    // penalize it smoothly so it only wins when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits (0) and small
    // "complement-friendly" residuals are rewarded via modular arithmetic.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr <= 10 {
        score -= 25.0; // tiny dead space, nearly perfect
    } else if pr % 10 == 0 {
        score -= 12.0; // decadal residual: likely reusable by future items
    } else if pr % 5 == 0 {
        score -= 6.0;
    }

    // Penalty for large awkward residuals scaled by capacity fraction.
    let frac = pr as f64 / cap;
    if frac > 0.5 {
        score += 10.0 * (frac - 0.5); // half-empty bins are wasteful targets
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 8.0 + 0.15 * (pr - next_item_size) as f64;
        } else {
            // next item won't fit here: mildly penalize leaving large residue
            score += 0.05 * (next_item_size - pr).min(40) as f64;
        }
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only open a new bin if current residuals are fragmented.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // open new bin only when mean residual is small (open bins are tight)
        score = 40.0 + 0.5 * mean_residual - 20.0 * (mean_gap / cap);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size > bin_residual {
            score += 5.0;
        }
    }

    // Slight preference to fill earlier (older) bins as stream progresses.
    score += 0.01 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // anything useful (below the smallest plausible item) are pure waste.
    let min_useful = 10u32;
    if post_residual < min_useful {
        // Perfect or near-perfect fill: strongly reward.
        score -= 60.0 + (min_useful - post_residual) as f64;
    } else {
        // Penalize gaps that cannot fit the lookahead item (likely dead space).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 25.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
        // Non-linear penalty on awkward mid-size gaps (hard to fill later).
        let mid = post_residual as f64;
        score += 0.15 * (mid / 50.0).powi(2) * 50.0;
    }

    // Reward tight fits relative to the bin's current residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Last-chance pressure: if this is the only fitting bin, using it avoids
    // opening a new bin — reward, scaled by how many bins are open.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 20.0 + (open_bins_count as f64).min(20.0);
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins
    // and mildly discourage using bins whose residual is far from the mean.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist that could still be used.
        if open_bins_count > 0 {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    } else {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Late in the stream, consolidation matters more: favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward when next item fits into post_residual
    if next_item_size > 0 {
        let next_fits = (post_residual as f64) >= (next_item_size as f64);
        if next_fits {
            score -= 120.0;
            // extra reward for tight chain fit
            score -= 60.0 * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        } else {
            // penalize leaving a gap that the next item just barely misses
            let gap = post_residual as f64 - next_item_size as f64;
            if gap > -20.0 && gap < 0.0 {
                score += 40.0;
            }
        }
    }

    // Penalize large dead space relative to mean residual across bins
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.5 * dead;
    } else {
        score += 0.25 * dead; // slightly reward being below mean residual (tighter bin)
    }

    // Last-chance bin bonus: if this is the only fitting bin, prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Discourage opening new bins when open bins are mostly empty
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless open bins are congested
        let congestion = mean_residual / bin_capacity as f64;
        score += 80.0 + 200.0 * (1.0 - congestion);
    }

    // Mild preference for filling more of the bin early in the stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: the smaller the post_residual, the better.
    score -= 12.0 * (1.0 - (post_residual as f64 / bin_capacity as f64)).powi(3);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // small unusable slivers are wasted capacity
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly reward; if next item barely misses, penalize.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            score -= 8.0 * (1.0 - (post - next) / bin_capacity as f64);
        } else {
            score += 4.0 * ((next - post) / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be conservative with open bins;
    // late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Congestion control: many open bins with high mean residual -> prefer packing
    // into existing bins rather than opening new ones.
    let congestion = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 0.5 * congestion.min(20.0);
    }

    // New-bin candidate: only attractive when the item is large and no bin fits well.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        score += 18.0 * (1.0 - tightness); // penalize opening bins for small items
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: normalized waste raised to a higher power
    let waste_frac = post / cap;
    score -= (1.0 - waste_frac) * (1.0 - waste_frac) * item_size as f64 * 0.5;

    // Smooth progress coupling: penalize leftover space more as stream advances
    score += waste_frac * waste_frac * (1.0 + progress) * 20.0;

    // Lookahead: reward if next item fits into the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (nxt / post).min(1.0));
        } else {
            score += 5.0 * waste_frac * progress;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap) < 0.5;
        score += if poor_fit { 12.0 + 8.0 * progress } else { 25.0 };
    }

    // Mean-residual coupling: prefer bins close to mean (keeps spread balanced)
    score += ((post - mean_residual).abs() / cap) * 6.0;

    // Slight preference for filling fuller bins when many bins are open
    score -= (open_bins_count as f64).ln().max(0.0) * waste_frac * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible by common item
    // sizes are reusable, others are likely dead space.
    let pr = post_residual;
    if pr > 0 {
        let mut reuse_bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if pr % m == 0 {
                reuse_bonus += 6.0;
            }
        }
        score -= reuse_bonus;

        // Integer-division threshold: residual in [1,9] is nearly dead space.
        if pr / 10 == 0 {
            score += 25.0;
        } else if pr / 10 == 1 {
            score += 5.0;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - 0.1 * slack;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual: penalize proportionally.
        score += 4.0;
    }

    // New-bin candidate: prefer it only when all open residuals are poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Base penalty so full bins win; relax as mean residual degrades.
        score += 30.0 + 0.15 * mean_residual - 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 45.0;
        }
    } else {
        // Favor bins with residual close to item (tight fit) via capacity fraction.
        let fill_frac = item_size as f64 / bin_capacity as f64;
        score -= 8.0 * fill_frac;
    }

    // Spread pressure: with many open bins, prefer tightening existing ones.
    score += 0.3 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for the minimum item (size 1..100 unknown,
    // but small gaps below a threshold are rarely reusable).
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }

    // Reward tight fits (wasted fraction small).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer existing bins.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual != bin_capacity {
        score -= pressure * fill_ratio;
    } else {
        // New-bin candidate: penalize opening bins when open bins already fit.
        score += pressure * 0.5;
    }

    // Prefer placing into bins whose residual is already below average
    // (consolidate small residuals, keep large residuals flexible).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Lookahead: if next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    }
    // Penalize if post residual is smaller than next item but nonzero (dead for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.2 * (post_residual as f64);
    }

    // Slight late-stream conservatism: keep bins tight as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item fits snugly in the remaining space
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - snug / bin_capacity as f64);
    }

    // Penalize dead space too small for typical items (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to capacity
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * (item_size as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave large waste
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64);
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (tighter bins)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Early in stream: keep bins balanced; late: pack greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits (small post residual), with non-linear shaping.
    score -= 12.0 * (-post / 18.0).exp();

    // Penalize dead space that no plausible future item can use.
    if post > 0.0 && (next_item_size as f64) > post {
        score += 6.0 + 0.25 * post;
    }

    // Lookahead synergy: placing here lets the next item fit the leftover.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && post > 0.0 {
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty when many bins are open and this fit is loose (fragmentation).
    let fit_frac = item_size as f64 / bin_residual as f64;
    if fit_frac < 0.5 && open_bins_count > 2 {
        score += 4.0 * (1.0 - fit_frac);
    }

    // Encourage balancing residuals toward the mean early on.
    let t = step_index as f64 / total_items.max(1) as f64;
    score += 0.15 * (post - mean_residual) * (1.0 - t);

    // New-bin candidate handling: fresh empty bin gets a moderate default
    // score; better than a terrible fit, worse than any decent fit.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count == 0 {
            score -= 40.0; // nothing fits anywhere: open a new bin
        } else if fitting_bins_count == 1 {
            score += 25.0; // keep using the last-chance bin
        }
        if next_item_size > 0 && (next_item_size as u32) >= bin_capacity / 2 {
            score -= 8.0; // big next item: fresh capacity is valuable
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Reward tight fits, more strongly later in the stream
    score -= 25.0 * fit_ratio * fit_ratio * (0.5 + progress);

    // Penalize dead space relative to mean residual
    score += 0.3 * (pr as f64 - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: avoid opening new bins when only one bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - fit_ratio);
    }

    // Lookahead: prefer bins whose post residual can host next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 8.0 * (1.0 - (pr - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        score += 6.0;
    }

    // Mild pressure toward consolidation when many bins are open
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: discourage unless residuals are all poor
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good; harmonic class bonus on exact small remainders.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Harmonic class: bins whose residual falls into "usable" classes (>= next item) get a bonus.
        if next_item_size > 0 && post >= next_item_size {
            score -= 12.0 + 0.25 * (post as f64 - next_item_size as f64).sqrt();
        }
        // Penalize dead space in awkward classes: post_residual mod 10 small but nonzero is hard to fill.
        let m = post % 10;
        if m > 0 && post < 10 {
            score += 15.0; // tiny unusable sliver
        } else if m != 0 && post < 20 {
            score += 6.0;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post == next_item_size {
        score -= 25.0;
    }
    // If next item cannot fit here but could fit in bin_residual minus a smaller item, mild penalty.
    if next_item_size > 0 && post > 0 && post < next_item_size && bin_residual >= next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should generally lose unless open bins are crowded.
    if bin_residual == bin_capacity {
        // Base penalty so an open bin that fits reasonably beats a new bin.
        score += 40.0;
        // But if few open bins can fit, or mean residual is low (bins are full), open a new bin.
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        if mean_residual < item_size as f64 * 1.2 {
            score -= 35.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // Penalize new bins when many open bins already exist.
        score += (open_bins_count as f64).min(20.0) * 0.8;
    }

    // Prefer bins whose residual is close in class to the item (harmonic pairing).
    let cls = |x: u32| x / 10;
    if cls(post) == cls(item_size) && post >= item_size {
        score -= 8.0;
    }

    // Slight preference for spreading across bins when many are open with large mean residual.
    if post as f64 > mean_residual * 2.0 && open_bins_count > 1 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residual sizes that stay usable for typical items (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 15.0 - slack.min(15.0);
    }
    // Penalize if next item cannot use the gap.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // and discourage opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: make it costly unless few bins are open.
        score += 30.0 + pressure;
    } else {
        score -= pressure.min(20.0);
    }

    // Prefer bins with below-mean residual (tighter bins first keeps
    // larger residuals available for bigger items).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tighter post-fit residual is better (scaled mildly).
    score *= 0.6;

    // ---- 2-step lookahead coupling ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;

        // Perfect 2-chain: post_residual exactly equals next item size.
        let gap = (post - nxt).abs();
        if gap < 0.5 {
            // Chain consumes the bin completely over two steps: huge reward.
            score -= 40.0;
        } else if post >= nxt {
            // Next item fits here afterwards: reward proportional to tightness.
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
            // Bonus if the combined placement leaves almost nothing.
            if gap <= 5.0 {
                score -= 8.0;
            }
        } else {
            // Next item cannot use the leftover: penalize dead space,
            // worse when the leftover is small-but-unusable (fragmentation).
            let waste = post;
            score += 0.35 * waste;
            if waste < 10.0 {
                score += 6.0; // tiny unusable sliver is pure waste
            }
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // ---- context adjustments ----
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Compare residual to mean residual across open bins.
    if bin_residual as f64 > mean_residual * 1.3 {
        // This bin is "loose" relative to others; using it rebalances.
        score -= 4.0;
    } else if (bin_residual as f64) < mean_residual * 0.7 {
        score += 3.0;
    }

    // Early in the stream: be more willing to open/spread across bins.
    if progress < 0.2 && bin_residual == bin_capacity {
        score -= 5.0;
    }

    // Many open bins: discourage opening yet another new bin.
    if bin_residual == bin_capacity {
        score += 2.0 * open_bins_count as f64;
        // But if nothing else fits well (many fitting bins means competition),
        // the empty-bin call competes naturally via post_residual = capacity.
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 20.0; // new bin useless for chaining a big next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score += 8.0 * (1.0 - fill_ratio) * post_residual as f64 / bin_capacity as f64;

    // Penalize creating unusable dead space relative to the smallest plausible item.
    if post_residual > 0 {
        score += 12.0 * (1.0 - post_residual as f64 / 100.0).exp();
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * next_item_size as f64 / 100.0;
        } else {
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with residual close to the mean residual (balance load),
    // but only when the bin is not near-empty.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Early in the stream, allow spreading items to create diverse residuals;
    // later, consolidate into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (open_bins_count as f64).ln().max(0.0);
    score -= progress * 4.0;

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let poor_fit = if post_residual == bin_capacity as u32 { 0.0 } else { 0.0 };
        let _ = poor_fit;
        let avg_waste = mean_residual / open_bins_count.max(1) as f64;
        if fitting_bins_count <= 1 {
            score -= 5.0; // opening fresh bin is fine when nothing else fits well
        } else if avg_waste < 15.0 {
            score += 20.0; // open bins are tight, avoid fragmentation
        } else {
            score += 6.0; // mild penalty for opening new bin when space exists
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer small post_residual (tight fit), non-linearly scaled.
    let mut score = (pr / cap).powf(1.7) * 40.0;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, waste matters more; early, keep bins flexible.
    let w = 0.5 + 0.5 * (progress * progress * (3.0 - 2.0 * progress)); // smoothstep
    score += (pr / cap).powf(3.0) * 30.0 * w;

    // Reward near-perfect fits with a smooth bump around pr ~ 0.
    score -= (-pr / 12.0).powi(2).exp() * 10.0;

    // Penalize large residuals relative to mean residual (dead space).
    score += ((pr - mean_residual) / cap).abs() * 6.0;

    // Lookahead: bonus if next item fits the post residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            let tight = 1.0 - ((pr as f64 - nxt) / cap);
            score -= 8.0 * tight * tight;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild pressure against accumulating many open bins early.
    score += (open_bins_count as f64) * (1.0 - progress) * 0.4;

    // New-bin candidate: only attractive when residual would be tiny anyway
    // or no good fit exists; make empty bin moderately unattractive by default.
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (1.0 - fit_ratio).powf(2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space quantization.
    // Residuals 0..10 are nearly perfect; 1..9 classes are "harmonic slots".
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward small residuals super-linearly.
    score -= 60.0 * (1.0 - frac).powi(6);

    // Harmonic dead-space classes: residuals that are small multiples of
    // common item sizes (10,20,25,50) are reusable; odd residues are dead.
    let harmonic = post_residual % 10 == 0 || post_residual % 25 == 0;
    if harmonic {
        score -= 8.0;
    } else if post_residual > 0 {
        score += 4.0;
    }

    // Lookahead coupling: penalize if the next item cannot use post_residual.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 10.0; // next item forces another bin anyway
        } else {
            // Reward when post_residual is a tight fit for next item
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 12.0;
            } else if gap > 40 {
                score += 6.0;
            }
        }
    }

    // Last-chance bonus: this is the only bin that fits; strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across many open bins; prefer consolidation.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // New-bin candidate: neutral-ish baseline; only attractive when all
    // open bins have tiny residuals (would create bad fits).
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.4;
        if fitting_bins_count == 1 {
            score += 30.0; // never open new bin when it's the only fit
        }
    }

    // Late-stream tightening: waste matters more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += frac * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A residual that is too small for any plausible future item (min size 1)
    // is pure dead space; residuals that block common item sizes are worse.
    if post_residual > 0 {
        // Perfect fit: heavily reward.
        score -= 40.0;
        if post_residual == 0 {}
    }
    if post_residual > 0 && post_residual < 10 {
        // Unusable dead space (below minimum item size): strong penalty.
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Residual that only tiny items can use: moderate penalty.
        score += 25.0;
    } else if post_residual > 50 {
        // Large residual is flexible: mild reward.
        score -= 10.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        // Bonus if post_residual exactly matches next item (chained perfect fit).
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // This placement strands the next item: penalty scaled by how close it was.
        let miss = (next_item_size as f64 - post_residual as f64).min(30.0);
        score += 5.0 + miss;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer reusing existing space
    // and avoid opening new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins count.
        score += 20.0 + pressure;
        // Late in the stream, new bins are especially costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
    } else {
        // Reward using existing bins more when many are open.
        score -= pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // packing here consolidates space (good); if above mean, it fragments.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (minimize dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post residual, this is a perfect chain — reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Next item fits: reward proportional to how snugly it fits.
            let slack_after_next = post_residual - next_item_size;
            score -= 120.0 - (slack_after_next as f64).min(100.0);
        } else {
            // Next item will NOT fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 2.0;
        }
    }

    // Compare against mean residual across open bins: prefer bins whose
    // residual is below average (tighter bins get filled first).
    score += (bin_residual as f64 - mean_residual) * 0.8;

    // Last-chance bin: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large relative to capacity (poor fit prospects elsewhere) or when
    // many bins are open (spread load for future items).
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize opening a new bin for small items.
        score += 250.0 * (1.0 - fill_ratio);
        // But if many bins are open and next item is large, new bin is fine.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * bin_capacity as f64 {
            score -= 100.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - progress);
    }

    // Mild preference for consolidating into fewer bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward small post-residual.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Penalize dead space quadratically, scaled by how "wasted" it is.
        let dead = post_residual as f64 / bin_capacity as f64;
        score += dead * dead * 80.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // With multiple options, prefer the bin that leaves the most usable residual
        // for other candidates — mild tie-break toward tightness.
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Lookahead: if the next item can fit into this bin's post-residual,
    // reward; if the next item is big and post-residual is a useless sliver
    // for it, penalize creating dead space.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= ni {
            score -= 12.0 + 10.0 * (1.0 - pr / (pr + ni));
        } else {
            // Dead space relative to the upcoming item.
            let waste = (ni - pr) / ni;
            score += 18.0 * waste;
        }
        // If next item fits exactly into post_residual, big bonus (perfect chain).
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Global state coupling: when many bins are open, prefer compacting
    // into existing ones rather than opening new ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    if bin_residual < bin_capacity {
        score -= 3.0 * pressure.min(20.0);
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it's a "dirty" bin — good to consume it. If above mean, mild penalty.
    let r = bin_residual as f64;
    if r < mean_residual {
        score -= 0.15 * (mean_residual - r);
    } else {
        score += 0.10 * (r - mean_residual);
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger
    // post-residual slightly); late in the stream, compact aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);
    score -= 15.0 * progress * (post_residual == 0) as i32 as f64;

    // New-bin candidate handling: an empty bin is only preferred when all
    // open bins would produce terrible fits (large dead space) or when
    // lookahead suggests the next item pairs badly with existing residuals.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: moderate, so good existing fits win.
        score = 45.0;
        if fitting_bins_count == 0 {
            // No open bin fits: must open a new bin.
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // A single last-chance bin exists; opening a new bin is wasteful
            // unless that fit would be dreadful (post_residual tiny sliver).
            if post_residual <= 8 {
                score += 5.0; // sliver anyway; new bin slightly ok
            } else {
                score += 40.0; // keep using the last-chance bin
            }
        }
        // Lookahead guard: if next item is huge, a fresh bin keeps flexibility.
        if next_item_size >= 70 {
            score -= 15.0;
        }
        // Early stream: fresh bins give flexibility.
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = fitting_bins_count as f64;

    // Base: prefer small post-residual, with smooth polynomial shaping.
    let x = pr / cap; // normalized post-residual in [0,1]
    let mut score = pr as f64;

    // Non-linear polynomial coupling: reward tight fits super-linearly,
    // penalize large dead space with a convex term.
    score -= (1.0 - x) * (1.0 - x) * (1.0 + it / cap) * 8.0;
    score += x * x * x * 20.0;

    // Smooth stream-progress coupling: late in the stream, waste matters more.
    let late = progress * progress;
    score += pr * late * 0.6;

    // Interaction between fill ratio and progress (smooth cross term).
    let fill = it / cap;
    score -= fill * (1.0 - x) * (1.0 + 3.0 * progress) * 5.0;

    // Last-chance bin bonus (smooth, not hard threshold).
    let scarcity = 1.0 / fit;
    score -= 6.0 * scarcity * (1.0 - x);

    // Lookahead: if next item fits snugly into resulting residual, reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let snug = 1.0 - gap / cap;
        score -= snug.max(0.0) * snug * 4.0;
    }

    // Mild penalty when bin residual deviates from mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 3.0;

    // Slight pressure against proliferating many open bins early.
    score += (open_bins_count as f64).sqrt() * (1.0 - late) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "denominator band" of capacity it falls into.
    // Bands: (0,10], (10,20], (20,25], (25,34], (34,50], (50,100]
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -60.0 // perfect fit: strongly reward
    } else if pr <= 10 {
        0.0 // prime real estate for small items
    } else if pr <= 20 {
        8.0
    } else if pr <= 25 {
        20.0
    } else if pr <= 34 {
        35.0
    } else if pr <= 50 {
        55.0
    } else {
        90.0 // more than half the bin wasted
    };
    score += class_penalty;

    // Integer-division harmonics: can next item fit exactly or nearly in the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size;
        if nxt > pr {
            // next item cannot follow here; residual becomes dead space for lookahead
            score += (pr as f64) * 0.6;
        } else {
            let leftover = pr - nxt;
            // reward chains where leftover stays in a useful small class
            if leftover == 0 {
                score -= 40.0;
            } else if leftover <= 10 {
                score -= 25.0;
            } else if leftover <= 20 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        // with many options, prefer tighter fits (already via post_residual)
        score += (fitting_bins_count as f64) * 1.5;
    }

    // Empty new-bin candidate: penalize opening a bin unless current residual is very poor
    if bin_residual == bin_capacity {
        score = 120.0 + item_size as f64 * 0.3
            - if pr == 0 { 0.0 } else { 0.0 };
        // allow opening when item is huge and would leave tiny waste elsewhere anyway
        if item_size >= 70 {
            score -= 10.0;
        }
    }

    // Progress coupling: later in stream, waste matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Prefer bins tighter than the mean residual (good packing density)
    score += ((mean_residual - bin_residual as f64) * 0.2).clamp(-20.0, 20.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual gap is "dead" if it's smaller than the smallest plausible item.
    let dead_threshold = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }

    // Reward perfect / near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize large leftover gaps that only fit the smallest items
    // (wasteful unless the gap is big enough to be reusable).
    let reusable = (post_residual as f64) >= 0.35 * bin_capacity as f64;
    if !reusable && post_residual > 0 {
        score += 0.5 * post_residual as f64;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into new bins;
    // the empty new-bin candidate gets penalized proportionally to open_bins_count.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if nothing fits well elsewhere (high mean residual mismatch), allow new bin.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Lookahead: if next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use the leftover: leftover likely becomes dead space.
        score += 0.6 * post_residual as f64;
    }

    // Slight preference early in the stream to consolidate (fewer bins early).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * (1.0 - progress) * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Mild tie-break toward bins below mean residual (tighter bins first).
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins that end up nearly empty of slack.
    let perfect_fit_bonus = if post_residual == 0 {
        1000.0
    } else if post_residual <= 5 {
        400.0
    } else {
        0.0
    };
    score -= perfect_fit_bonus;

    // 2-step lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 900.0; // chain of perfect fits
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            if leftover <= 5 {
                score -= 500.0; // two-step near-perfect chain
            } else {
                // penalize large dead space after hypothetical next placement
                score += leftover as f64 * 0.5;
            }
        } else {
            // next item cannot fit here after this placement; mild penalty scaled by overshoot
            let overshoot = next_item_size - post_residual;
            score += overshoot as f64 * 0.3;
        }
    }

    // Compare post_residual against mean residual: prefer bins whose slack
    // stays close to (or below) the mean, avoiding outlier dead space.
    let mean_dev = (post_residual as f64 - mean_residual).abs();
    score += mean_dev * 0.4;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // and no good fit exists (high post_residual waste would otherwise occur).
    if bin_residual == bin_capacity {
        // opening fresh: good if item is big (little waste) and few fitting bins
        let waste = (bin_capacity - item_size) as f64;
        score = waste * 1.5;
        if fitting_bins_count <= 1 {
            score -= 350.0; // no good alternative -> new bin is fine
        }
        if item_size >= bin_capacity / 2 {
            score -= 150.0;
        }
    }

    // Tightness reward: favor bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 100.0;

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 50.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residuals, especially unusable ones (< smallest plausible item).
    if post_residual < 10 {
        score += 30.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Last-chance bin bonus: avoid opening a new bin when only one bin fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0; // dead space relative to lookahead
        }
        // If next item exactly matches post-residual, strong bonus.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 6.0 * pressure * (1.0 - (bin_residual as f64 / bin_capacity as f64));

    // Global residual coupling: penalize bins far from mean residual when mean is high.
    let res = bin_residual as f64;
    let dev = (res - mean_residual).abs();
    score += 0.05 * dev * (mean_residual / bin_capacity as f64);

    // Time horizon: early in stream, be pickier about tight fits; late, pack greedily.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= t * 10.0 * fill;

    // Slight preference for existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 15.0;
        // But allow new bin if current best fits are poor (large post_residual elsewhere is handled by comparison).
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // new bin may serve both items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr
        + 8.0 * fit_norm * fit_norm * cap
        - 4.0 * fit_norm * fit_norm * fit_norm * cap;

    // Perfect-fit reward (smooth quadratic bump near zero residual)
    score -= 20.0 * (1.0 - fit_norm) * (1.0 - fit_norm) * (1.0 - fit_norm);

    // Stream progress coupling: later in stream, penalize loose fits more strongly
    let progress_coupling = progress * pr * (0.5 + fit_norm);
    score += 2.5 * progress_coupling;

    // Last-chance bin bonus: strongly favor when only this bin fits
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * (1.0 - fit_norm);
    }

    // Lookahead: penalize if post residual can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 6.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 3.0 * (pr - nxt) / cap * (1.0 - progress);
        }
    }

    // Mean residual context: avoid bins far from the fleet mean (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Crowding pressure: more open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln() * (1.0 - fit_norm) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes (harmonic classes) are more reusable than odd leftovers.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space penalty for tiny, awkward remainders.
        if pr < 10 {
            score += 40.0;
        }
        // Reward remainders lying in "harmonic" classes: multiples of 5,
        // 10, 20, 25, 50 are easier to fill with typical items.
        let harmonic_bonus = if pr % 50 == 0 {
            30.0
        } else if pr % 25 == 0 {
            22.0
        } else if pr % 20 == 0 {
            18.0
        } else if pr % 10 == 0 {
            14.0
        } else if pr % 5 == 0 {
            8.0
        } else {
            0.0
        };
        score -= harmonic_bonus as f64;

        // Integer-division threshold: leftovers in [30, 60] are the sweet
        // spot for lookahead pairing.
        let half_class = pr / 10; // coarse class 0..=10
        match half_class {
            3 | 4 | 5 => score -= 12.0,
            1 | 2 => score += 6.0, // too small to be useful
            8 | 9 | 10 => score += 4.0, // nearly empty bin, less urgent
            _ => {}
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot follow into this bin: mild penalty scaled
            // by how much capacity is wasted.
            score += 0.15 * (pr as f64);
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless open bins are crowded
    // or the fit here would be terrible.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_fit_elsewhere = mean_residual < item_size as f64;
        if !poor_fit_elsewhere && fitting_bins_count > 0 {
            score += 35.0 + 2.0 * crowded.min(20.0);
        } else {
            score += 5.0;
        }
    }

    // Mild preference for tighter bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (bin_residual as f64) * 0.05;

    // Prefer bins below the mean residual (tighter packing first).
    score += 0.1 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: tight fit is good (low post_residual), but penalize the "dead zone"
    // of small unusable gaps super-linearly.
    let mut score = post_residual as f64;

    // Dead-space penalty: gaps that are too small for likely future items
    // (items >= 10 typically, but distribution unknown; treat gaps < ~15 as near-dead).
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            score -= 4.0;
        } else {
            // Next item cannot use this residual -> residual likely dead.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // (discourage opening new bins); with few open bins, spreading is cheaper.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * (bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + (bin_residual - item_size).min(20) as f64;
    }

    // New-bin candidate handling: make an empty bin moderately attractive only
    // when the fit in this bin is bad (large post_residual relative to capacity).
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        // Good fits (small post_residual) keep the empty bin unattractive.
        score += 5.0 + fit_quality * 20.0;
    }

    // Mild progress term: later in the stream, tighten placements more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.3;

    // Mean residual coupling: if average residual across open bins is high,
    // we have slack; prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
