pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize wasted space quadratically.
    let waste = post_residual as f64;
    score += 0.15 * waste * waste / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: penalize if placing the item here leaves no room for the next item
    // while the next item would otherwise fit in the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0; // chain packing is good
        } else {
            score += 10.0; // dead space relative to lookahead
            // extra penalty if the dead space is small and unusable
            if post_residual < next_item_size / 2 {
                score += 15.0;
            }
        }
    }

    // New-bin candidate logic: an empty bin should only win when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open or stream is late.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 120.0 - 60.0 * progress;
        if open_bins_count > 4 {
            open_cost -= 20.0;
        }
        // If next item pairs with this one perfectly, opening a new bin is attractive.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            open_cost -= 90.0;
        }
        // If the current bin would leave tiny unusable residual, opening is better.
        if post_residual > 0 && post_residual < 10 {
            open_cost -= 60.0;
        }
        score += open_cost;
    }

    // Global residual pressure: prefer bins whose residual deviates from the mean
    // in the direction that reduces fragmentation.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild preference for filling already-open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = post / cap; // normalized post residual in [0,1]

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = post;
    score += 30.0 * x * x * (1.0 - progress);
    score -= 25.0 * x * x * progress;
    score += 12.0 * x * x * x;
    score -= 8.0 * x * (1.0 - x) * (progress * (1.0 - progress) * 4.0);

    // Penalize dead space relative to next item's potential fit
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.35 * gap * (0.5 + progress);
        if next_item_size as f64 <= post {
            score -= 6.0 * (1.0 - progress);
        }
    }

    // Last-chance bonus: avoid opening a new bin when this is the only fitting one
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - x);
    }

    // Mild penalty when bin is far from mean residual state (fragmentation signal)
    let dev = (mean_residual - post).abs() / cap;
    score += 4.0 * dev * dev;

    // Encourage tight fits early, discourage wasting nearly-empty bins late
    score -= 10.0 * (1.0 - x) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction buckets. Leftovers in "useless" classes get penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds: /8, /4, /2 of capacity
    let eighth = cap / 8.0;
    let quarter = cap / 4.0;
    let half = cap / 2.0;

    if pr > half {
        // Huge leftover: bin was barely used — strongly penalize placing here
        score += 12.0;
    } else if pr > quarter {
        // Mid leftover: mildly undesirable unless it perfectly hosts next item
        score += 3.0;
    } else if pr > eighth {
        // Small leftover: good tight fit
        score -= 4.0;
    } else {
        // Near-perfect fill: big reward
        score -= 9.0;
    }

    // Integer-division harmonic class of post_residual mod small numbers:
    // residuals divisible into clean classes are more reusable.
    if post_residual > 0 {
        let m4 = post_residual % 4;
        let m5 = post_residual % 5;
        let class_bonus = match (m4, m5) {
            (0, 0) => -3.0,
            (0, _) | (_, 0) => -1.5,
            _ => 0.5,
        };
        score += class_bonus;
    }

    // Lookahead: does next item fit exactly / well in the post residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - pr).abs() < 1.0 {
            score -= 15.0; // perfect next-fit
        } else if nxt <= pr {
            // next fits: reward proportional to how much would remain after next
            let after_next = pr - nxt;
            if after_next <= eighth {
                score -= 7.0;
            } else if after_next <= quarter {
                score -= 3.0;
            } else {
                score += 1.0; // wasteful two-step fit
            }
        } else {
            // next item does NOT fit here: penalize if this bin is the only option
            if fitting_bins_count == 1 {
                score += 6.0;
            } else {
                score += 2.0;
            }
        }
    }

    // Last-chance bin logic: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual <= quarter {
        score -= 5.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only attractive when the current item is large or fits are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 6.0 } else { 0.0 };
        let large_item = if item_size as f64 > 0.6 * cap { 4.0 } else { 0.0 };
        score += 10.0 - scarcity - large_item - 3.0 * (1.0 - progress);
    }

    // Spread-aware adjustment: if this bin's residual is far from the mean,
    // nudging toward balanced residuals helps future flexibility.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.02 * dev;

    // Slight preference for tighter existing bins as stream progresses
    score += 0.5 * (step_index as f64 / (total_items.max(1) as f64)) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
