    }
    // If next item would be stranded by a small gap, penalize.
    if next_item_size > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Mean residual coupling: penalize placing into bins far from the mean residual
    // (keeps residual distribution balanced).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // New-bin candidate: mildly discourage opening a new bin unless the item is large
    // and few bins are open.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -1.0;
        if item_size >= 50 && open_bins_count < 4 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits tightly in the leftover space
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize post_residual that cannot hold the next item (dead space risk)
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Prefer bins whose residual is below mean (tighter bins get filled first)
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is terrible
    if bin_residual == bin_capacity {
        let crowded = if open_bins_count == 0 { 1.0 } else { mean_residual / bin_capacity as f64 };
        let bad_fit = (item_size as f64 / bin_capacity as f64).powi(2);
        score -= 15.0 * crowded * bad_fit;
        score += 20.0 * (1.0 - crowded);
    }

    // Mild late-stream pressure to consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 25.0;

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 15.0;
        } else {
            score += 10.0;
        }
        // Perfect chain: item + next item exactly fill residual.
        if post_residual == next_item_size as u32 {
            score -= 20.0;
        }
    }

    // Prefer fuller bins over emptier ones when several fit.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Global pressure: many open bins -> favor consolidation into existing bins;
    // few open bins -> allow opening new bins more freely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins are open or mean residual is usable.
        score += 30.0 + 50.0 * pressure + mean_residual * 0.5 - 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * pressure;
    }

    // Penalize bins whose residual deviates strongly from mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Mild time decay: late in stream, be more conservative about new bins.
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - pr) * (1.0 - pr);
    score -= 40.0 * poly * (0.5 + progress);

    // Penalize large dead space more aggressively as stream progresses
    score += progress * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward tight fits (small post residual) especially near the end
    score -= (1.0 - progress) * (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless post_residual would be very usable
    if bin_residual == bin_capacity {
        score += 15.0 - 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: reward bins whose post_residual can fit the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
    }

    // Coupling with mean residual: prefer bins near the mean (keeps spread balanced)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * dev / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core best-fit: reward tight fits strongly.
    score += 12.0 * (post_residual as f64 / cap);

    // Harmonic class logic: post_residual divisible by common item sizes
    // (small classes) leaves re-usable space -> reward.
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 6.0 + 0.1 * post_residual as f64;
                break;
            }
        }
        // Dead-space penalty: residual too small for the minimum item class.
        if post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Perfect closure.
        score -= 15.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // harmonic match: next item divides the leftover space
            if post_residual % next_item_size == 0 {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overflow
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or many bins are open (fragmentation pressure).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / cap);
        score += 18.0 + 2.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing large items in fresh bins
        }
        if post_residual == 0 || item_size as f64 > 0.8 * cap {
            score -= 22.0;
        }
    }

    // Slight preference for fuller bins over time (progressive tightening).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post_residual as f64 / cap);

    // Prefer bins below mean residual (balance exploitation of emptier bins).
    score += 0.05 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1) or
    // for the lookahead item are effectively wasted.
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual < next_item_size && next_item_size > 0 {
        // gap unusable by the next item -> dead space penalty grows as gap shrinks
        let gap = post_residual as f64;
        score += (10.0 - gap.min(10.0)) * 2.0;
        score += 15.0;
    }

    // Tight fit reward: how well the item fills the bin relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 20.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else {
        // pressure from many open bins: avoid spreading, prefer fuller bins
        score += open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is below the mean (i.e. fuller than average)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(30.0) * 0.3;
    } else {
        score += (res - mean_residual).min(30.0) * 0.2;
    }

    // New-bin candidate: only attractive when item is large and no good fit exists
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.5 {
            score -= 10.0 * (large_item - 0.5);
        } else {
            score += 20.0; // discourage opening bins for small items
        }
    }

    // Late in the stream, slightly prefer consolidating into existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain placement possible: reward proportional to tightness of chain.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.3 * slack;
        } else {
            // Dead space that the next item cannot use: penalize dead space hard,
            // scaled by how much of the bin is wasted.
            let waste = post_residual as f64;
            score += 1.5 * waste;
        }
    }

    // Compare post_residual against the mean residual: leaving less than the mean
    // means this bin becomes the "worst" bin, mildly penalize.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score += 0.4 * (mean_residual - pr);
    } else {
        score -= 0.2 * (pr - mean_residual);
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity (big items deserve fresh bins).
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / bin_capacity as f64;
        score += 50.0 - 70.0 * frac;
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use leftover; penalize proportionally
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with below-average residual (consolidate waste in few bins).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in stream: keep bins balanced; late: exploit tight fits more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.2 * (bin_residual as f64 - bin_capacity as f64 / 2.0).abs();

    // Many open bins: discourage spreading; few bins: encourage using existing ones.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: only attractive when no good existing option.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual / bin_capacity as f64).max(0.0)
        };
        score += 15.0 * desperation + 2.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // fresh bin pairs well with upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = item_size as f64 / cap;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let is_new_bin = (bin_residual as u32 == bin_capacity) as f64;

    // Base: minimize wasted post-residual (quadratic coupling)
    let mut score = pr * (1.0 + 0.004 * pr);

    // Smooth progress-dependent waste penalty: later in stream, waste hurts more
    let waste_weight = 1.0 + 2.5 * progress * progress;
    score += 0.01 * pr * pr * waste_weight;

    // Reward tight fits (post_residual near zero) with smooth saturation
    let tight = 1.0 - (pr / cap).powi(2);
    score -= 12.0 * tight * tight;

    // Penalize residual that is too small to ever be useful again (dead space)
    let next_fits = (next_item_size as f64 <= pr) as f64;
    let dead = (1.0 - next_fits) * (1.0 - ((pr as f64) / 10.0).min(1.0));
    score += 8.0 * dead;

    // Lookahead coupling: if next item fits this bin's post-residual, reward
    score -= 6.0 * next_fits * (next_item_size as f64 / cap);

    // Last-chance bonus: only one fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening new bins mildly,
    // but relax penalty when existing fit leaves large waste (smooth trade-off)
    let new_bin_penalty = 15.0 * (1.0 - fit_norm) * (0.5 + 0.5 * progress);
    score += is_new_bin * new_bin_penalty;

    // Mild dispersion penalty: avoid creating residuals far below mean residual
    let disp = (mean_residual - pr).abs() / cap;
    score += 3.0 * disp * disp;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction bucket it lands in.
    let frac = post_residual as f64 / bin_capacity as f64;
    let sixth = post_residual % (bin_capacity / 6); // modulo structure on capacity fractions

    // Reward residuals that are exact harmonic divisions (perfectly reusable classes)
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual == bin_capacity / 2 || post_residual == bin_capacity / 3
        || post_residual == bin_capacity / 4 || post_residual == bin_capacity / 5 {
        score -= 12.0; // clean harmonic class residuals are highly reusable
    } else if post_residual < 10 {
        score += 8.0; // tiny dead space, penalize
    }

    // Penalize residuals just above common item sizes (awkward zone)
    if post_residual > 0 && post_residual < 20 {
        score += 6.0;
    }

    // Modulo coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            // harmonic class of the resulting double-residual
            if slack % 10 == 0 {
                score -= 6.0;
            }
            score += slack as f64 * 0.3;
        } else {
            // next item cannot follow in this bin; mildly penalize small residuals
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when residual would be awkward or bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = post_residual < 15 && post_residual > 0;
        if awkward || (mean_residual < 20.0 && open_bins_count > 2) {
            score -= 10.0 + 5.0 * progress;
        } else {
            score += 20.0; // prefer placing into existing bins otherwise
        }
    }

    // Mild preference for tighter-than-average bins
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Sixth-class modulation: residuals in the same modulo-16 class as next item pair well
    if next_item_size > 0 && sixth == next_item_size % (bin_capacity / 6) && post_residual >= next_item_size {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0 * (1.0 - (post_residual as f64) / 20.0);
