    }

    // Perfect-fit lookahead: if next item exactly fills post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item can still fit: mildly reward keeping usable residual.
        score -= 6.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here; residual becomes dead weight unless reusable later.
        score += 8.0;
    }

    // Open-bin pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 20.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        // Allow new bin only if no bin fits at all.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else if fitting_bins_count == 1 {
        // Last-chance bin: strongly prefer using it to avoid opening a bin.
        score -= 30.0;
    }

    // Prefer tighter bins relative to fleet mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact match between post_residual and next item size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 50.0; // perfect 2-step fit: this bin becomes fully packed next step
        }
        // penalize leaving residual that neither fits next item nor is tiny
        if post_residual < next_item_size && post_residual > 0 {
            score += 8.0;
        }
    } else {
