    if bin_residual == bin_capacity {
        let fullness = item_size as f64 / bin_capacity as f64;
        if fullness > 0.6 {
            score -= 20.0 * fullness;
        } else {
            score += 15.0; // discourage opening new bin for small items
        }
        if mean_residual < 20.0 {
            score -= 10.0; // open bins nearly exhausted
        }
    }

    // Slight preference for packing into bins with lower residual overall
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
