    // Lookahead coupling: if the next item fits exactly into post_residual, strong bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 + 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot fit here; slight penalty proportional to overflow
            score += 4.0 * ((next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing ones
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global state: if this bin's residual is below mean residual, it's a good filler
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Time horizon: early in the stream, be conservative (prefer new bins for large items);
    // late in the stream, squeeze everything in
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;
    if bin_residual == bin_capacity {
        // New-bin candidate: mild penalty so it's chosen only when fits are poor
        score += 6.0 + 20.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let prog = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling: post_residual normalized, squared and cubic terms modulated by progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let p2 = x * x;
    let p3 = p2 * x;

    // Early: prefer tight fits (low post_residual) strongly; late: tolerate slack less, penalize dead space more.
    score += (0.5 - prog) * 20.0 * p3 * cap;           // cubic reward for tight fit early on
    score += prog * 15.0 * p2 * cap;                   // quadratic dead-space penalty grows over stream
    score -= (1.0 - prog) * 8.0 * p2 * cap;            // smooth early counter-term

    // Interaction with mean residual: avoid bins far from fleet average (smooth quadratic)
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / (1.0 + prog);

    // Lookahead: reward leaving space that can host the next item (smooth via quadratic overlap)
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let diff = pr - n;
        if diff >= 0.0 {
            score -= 6.0 * (1.0 - (diff / cap).powi(2));
        } else {
            score += 4.0 + 0.1 * (-diff);
        }
    }

    // Last-chance bin: strong smooth bonus to use it rather than open new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - p2);
    }

    // Mild preference for consolidated bins when many are open
    score += 0.3 * open_bins_count as f64 * p2;

    // New-bin candidate: keep neutral-ish baseline so it wins only when fits are poor
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - prog) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition capacity into 4 bands.
    let quarter = bin_capacity / 4;
    let band = post_residual / quarter.max(1);
    match band {
        0 => score -= 18.0, // tight fit: nearly full bin, excellent
        1 => score -= 4.0,  // small leftover
        2 => score += 6.0,  // mid leftover: mediocre
        _ => score += 14.0, // large leftover: wasteful
    }

    // Exact divisibility bonus: post_residual divisible by common item classes
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 3.0; }
        else if pr % 3 == 0 { score -= 1.0; }
        else { score += 3.0; } // awkward class
    }

    // Lookahead harmonic coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: reward, scaled by how snugly
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here: penalize if this bin leaves a dead zone
            let dead = pr as f64;
            if dead < next_item_size as f64 {
                score += 5.0 * (dead / cap);
            }
        }
    } else {
        // last item: just minimize residual
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer existing bins unless residual is tiny
    if bin_residual == bin_capacity {
        // new bin: baseline cost plus penalty when good fits exist
        score = cap * 0.75 + (fitting_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // slight bonus for fresh bin when item is large
            if item_size as f64 > cap * 0.6 { score -= 10.0; }
        }
    }

    // Progress-aware pressure: late in stream, consolidation matters more
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    // Spread-aware: if mean residual is low, treasure tight placements more
    score -= 3.0 * (1.0 - mean_residual / cap).max(0.0);

    // Tie-break on item size: larger items prefer tighter bins
    score += (item_size as f64 / cap) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space: small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Pressure from number of open bins: prefer existing bins when many are open.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus pressure, scaled by stream progression.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = (bin_capacity as f64) * 0.5 + open_pressure + 20.0 * progress;
    } else {
        score -= open_pressure;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size {
        // Dead space relative to the known next item.
        score += 8.0;
    }

    // Slight preference for bins below mean residual (keeps balance).
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fits post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.9 * gap;                       // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 25.0;                        // perfect 2-chain: strong reward
        }
        // if next item can't fit anywhere after this placement, penalize dead space
        if next_item_size as f64 > post_residual as f64 {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Compare against mean residual: bins tighter than average are good targets
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize creating tiny unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Prefer filling bins that are already quite full (low residual relative to capacity)
    let fullness = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 8.0 * fullness;

    // Early in stream, be slightly more willing to open new bins (keep options open)
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);          // new-bin candidate cheaper early, expensive late
    } else {
        score -= 2.0 * progress;                  // late in stream, favor existing bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize post_residual relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if next item would nearly fit but not quite (dead space risk).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.3 * (post_residual as f64 - next_item_size as f64).abs();
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Global state coupling: prefer bins below mean residual (balancing).
    score += 0.2 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor empty-bin candidate); later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score += 60.0 * progress - 20.0 * (1.0 - progress);
        // Opening a new bin is fine if current fit is terrible.
        if post_residual > 40 {
            score -= 35.0;
        }
    } else {
        // Late in stream, penalize leaving many open bins with slack.
        score += 0.1 * open_bins_count as f64 * (1.0 - progress);
    }

    // Mild preference for fuller bins overall.
    score -= 0.15 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth non-linear coupling: penalize large residuals more strongly as stream progresses
    let prn = pr / cap;
    score += 12.0 * prn * prn * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with a smooth saturating term
    score -= 8.0 * (1.0 - prn) * (1.0 - prn) * (1.0 - progress);

    // Dead-space penalty: residuals too small for typical future items
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let wasted = (pr - nxt).max(0.0) / cap;
        score += 15.0 * wasted * wasted;
        // Smooth bonus if next item fits exactly
        let fits_next = ((pr - nxt).abs()) / cap;
        score -= 6.0 * (1.0 - fits_next).max(0.0) * (1.0 - fits_next).max(0.0);
    }

    // Last-chance bin: smooth reward when few fitting bins exist
    let scarcity = 1.0 / (1.0 + fitting_bins_count as f64);
    score -= 10.0 * scarcity * (1.0 - prn);

    // Mild penalty for opening new bins late in the stream when many are open
    let new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += new_bin * (4.0 + 6.0 * progress) * (open_bins_count as f64).sqrt();

    // Dampen preference for bins far from mean residual (balance)
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "reusable" is the leftover space
    // modulo common item-size granularities (10, 20, 25, 50).
    let r = post_residual;
    let class_bonus = if r == 0 {
        -30.0 // perfect fit, ideal
    } else if r % 10 == 0 && r >= 10 {
        -8.0 // leftover is a multiple of the base granularity: very reusable
    } else if r % 20 == 0 || r % 25 == 0 {
        -5.0 // coarse harmonic class
    } else if r % 50 == 0 {
        -6.0
    } else if r < 10 {
        12.0 // dead space below the minimum item size
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division thresholds: how many "average" items still fit post-placement
    let avg_item = 30.0f64;
    let slots = (r as f64 / avg_item).floor();
    score -= 2.5 * slots;

    // Penalize leftovers in awkward harmonic bands (r in 11..19, 21..24, 26..49 non-multiples)
    if r >= 11 && r <= 19 { score += 6.0; }
    if r >= 21 && r <= 24 { score += 4.0; }

    // Lookahead coupling: does the next item fit harmonically into the leftover?
    if next_item_size > 0 {
        if next_item_size <= r {
            // next item exactly fills or harmonically divides leftover
            if r % next_item_size == 0 { score -= 10.0; }
            else { score -= 4.0; }
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += 3.0;
        }
        // next item is large: prefer conserving big-residual bins
        if next_item_size >= 60 && r < next_item_size { score += 5.0; }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large and few bins fit it
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (item_size as f64 / bin_capacity as f64) * (1.0 - 0.3 * progress);
        score += 25.0 - 20.0 * pressure;
        if fitting_bins_count == 0 { score -= 40.0; }
    }

    // Prefer tight fits: reward small post_residual relative to bin capacity
    score -= 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild penalty when many open bins share high mean residual (fragmentation signal)
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gap is "dead" if smaller than the minimum item size (1) is trivially fine,
    // so treat gaps below a conservative threshold as wasted.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0; // creating unusable sliver
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit: zero waste
    }

    // Reward tight fits relative to item size
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 15.0 * fit_ratio;

    // Penalize opening new bins when pressure is high
    let pressure = open_bins_count as f64 / (step_index.max(1) as f64 + 1.0);
    if bin_residual == bin_capacity {
        // brand-new bin candidate: penalize, but relax when few bins fit the item
        score += 30.0;
        if fitting_bins_count <= 1 {
            score -= 45.0; // last chance: allow new bin
        }
        score += pressure * 20.0;
    } else if fitting_bins_count == 1 {
        // this is the only bin that fits: strongly favor using it
        score -= 35.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0;
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 6.0; // next item can't use the gap -> dead space risk
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Mild progress adaptation: later in stream, be more waste-averse
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step lookahead fit: post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect pair fill bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Penalize leaving dead space the next item cannot use
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 + 0.5 * post_residual as f64;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 30.0;
    }

    // Penalize large dead space relative to mean residual
    score += 0.3 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: avoid opening a new bin if this fits reasonably well
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild penalty for wasting a nearly-empty bin context; prefer tight fits late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it neutral-ish, only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        score += 20.0 - 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that becomes unusable for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny sliver is wasted
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits into the post residual, reward; else penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 4.0 * (1.0 - (next_item_size as f64 - post_residual as f64) / bin_capacity as f64);
        }
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // later, allow opening new bins to spread load.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, discount later.
        score += 12.0 * (1.0 - progress) - 4.0 * progress;
        // Opening a new bin is more attractive if open bins have low mean residual.
        score -= 10.0 * (mean_residual / bin_capacity as f64 - 0.3).max(0.0);
    } else {
        // Favor bins below mean residual (they need filling).
        score -= 3.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    }

    // Many open bins: prefer filling existing ones over opening more.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    // Prefer placing larger items into fuller bins (best-fit coupling).
    score -= 0.05 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;
    let prog2 = progress * progress;

    // Non-linear coupling of post_residual with progress
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += (pr_norm * pr_norm) * 30.0 * (0.5 + prog2);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += gap * gap * 0.05;
        // Reward leaving exactly enough room for the next item
        let tight = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= (1.0 - tight / bin_capacity as f64).max(0.0) * 8.0;
    }

    // Reward using bins tightly (small post_residual relative to item)
    score -= item_size as f64 * (1.0 - prog2) * 0.3;

    // Last-chance bonus: only one bin fits -> strongly favor it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for spreading across many open bins when residuals are large
    let mr = mean_residual / bin_capacity as f64;
    score += open_bins_count as f64 * mr * 0.5;

    // New-bin candidate: slightly penalize early, allow later via smooth term
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) + 4.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality classes.
    // Residuals that can still host common item sizes are valuable.
    let usable = |r: u32| -> f64 {
        // classes: r >= 50 (half bin), r >= 30, r >= 20, r >= 10, else dead
        if r >= 50 { 0.0 }
        else if r >= 30 { 6.0 }
        else if r >= 20 { 12.0 }
        else if r >= 10 { 18.0 }
        else { 30.0 } // dead space penalty
    };
    score += usable(post_residual);

    // Reward tight fits: exact fill or small remainder.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead coupling: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // excellent: chain placement possible
            score -= 15.0 + 0.1 * next_item_size as f64;
            // harmonic class match: next item fits into the same class slot
            let class_gap = (post_residual - next_item_size) % 10;
            score -= (9 - class_gap) as f64 * 0.5;
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            let waste = next_item_size - post_residual;
            score += 0.3 * waste as f64;
        }
    }

    // Last-chance bonus: only bin that fits; strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: opening a new bin is only good when existing
    // residuals are poor (high mean residual / fragmented classes) or
    // the item is large relative to what open bins can absorb.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // base resistance to opening new bins
        score += 25.0
            // more open bins -> more reluctant to open another
            + 1.5 * open_bins_count as f64
            // early stream: be slightly more willing to open bins
            - 10.0 * (1.0 - progress)
            // if mean residual is large, open bins are wasteful already -> new bin ok
            - 0.2 * mean_residual;
        // large items prefer fresh bins when fragmentation is high
        if item_size >= 60 && fragmentation > 20.0 {
            score -= 20.0;
        }
    }

    // Mild penalty for leaving exactly awkward residuals (mod-10 dead zones)
    if post_residual % 10 == 1 || post_residual % 10 == 9 {
        score += 3.0;
    }

    // Small preference for balancing residuals toward the mean
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps (dead space) more aggressively than large residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 20 {
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits.
    score -= 10.0 * (item_size as f64 / bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item would leave a tiny dead space, penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and stream progress.
        score += 20.0 + 0.5 * open_bins_count as f64 + 30.0 * progress;
    } else {
        score += 0.3 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably from mean.
    score += 0.2 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // perfect 2-step chain
        } else if next_item_size < post_residual {
            // partial fit: reward proportional to how well next item consumes leftover
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * frac;
            // penalize leaving a sliver the next item barely fits into
            if post_residual - next_item_size < 10 {
                score += 12.0;
            }
        } else {
            // next item cannot use the leftover at all -> dead space risk
            score += 10.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers creating fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // among many candidates, prefer tighter fits
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) - 8.0;
        if next_item_size > 0 && next_item_size >= item_size {
            // roomy new bin good for chaining big items
            score -= 6.0;
        }
        if fitting_bins_count == 1 {
            score += 15.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual as f64 > mean_residual {
            score += 5.0;
        }
    }

    // Late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    score -= 3.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Perfect pair: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with slack: discourage spreading waste; prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 4 {
        score += (open_bins_count as f64).ln() * 2.0 * (1.0 - progress);
    }

    // Compare against mean residual: prefer bins tighter than average.
    score += 0.4 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual == 0;
        if good_fit_exists {
            score += 100.0; // never open new bin when a perfect fit exists
        } else if next_item_size > 0 && next_item_size > post_residual.max(0) && fitting_bins_count <= 2 {
            score -= 12.0 * progress; // late stream: prefer fresh bin over bad fit
        } else {
            score += 10.0;
        }
    }

    // Slight preference for filling larger-residual bins early (keep small slacks flexible).
    score -= 0.05 * bin_residual as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let norm_post = post / cap;

    // Base: post residual with non-linear shaping (quadratic waste term)
    let mut score = post + 30.0 * norm_post * norm_post;

    // Smooth stream-progress coupling: waste penalized more heavily later in stream
    score *= 1.0 + 0.6 * progress * norm_post;

    // Reward tight fits (low post residual) with a smooth saturating bonus
    let tightness = 1.0 - norm_post;
    score -= 12.0 * tightness * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 10.0 * progress;
    }

    // Many open bins: mild penalty to encourage consolidation
    score += 0.8 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual is close to the mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let gap = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 15.0 * (1.0 - gap);
    }
    // If next item cannot fit here but would fit an untouched residual, penalize wasting space
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 8.0 * norm_post;
    }

    // New-bin candidate: penalize slightly so it is chosen only when fits are poor,
    // but relax this penalty late in the stream when consolidation matters less
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftover mod 10 buckets.
    // Leftovers that are "nice" (multiples of 10, esp. small ones) are reusable.
    let nice = post_residual % 10 == 0;
    if nice {
        score -= 6.0;
    } else {
        // penalize awkward leftovers, worse when close to but not on a class boundary
        score += (10 - (post_residual % 10)) as f64 * 0.4;
    }

    // Dead-space penalty: leftover too small to hold the smallest plausible item
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual) superlinearly
    if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual <= 15 {
        score -= 5.0;
    }

    // Integer-division thresholds: leftover divisible by next item size is gold
    if next_item_size > 0 && post_residual > 0 {
        if post_residual % next_item_size == 0 {
            score -= 8.0;
        }
        // leftover big enough for lookahead item: good
        if post_residual >= next_item_size {
            score -= 3.0;
        } else if next_item_size >= 10 {
            // leftover wasted relative to lookahead
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when all open bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // base penalty for opening a new bin
        score += 20.0;
        // but if no open bin fits, new bin is the only option: cancel penalty
        score -= pressure * 40.0;
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference for bins below mean residual (balance load)
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable
    // (item sizes >= 1, but practically small gaps waste capacity).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 25.0;
    } else if post_residual <= 20 {
        // Moderately small gaps still risky.
        score += 0.8 * (20 - post_residual) as f64;
    }

    // Reward leaving room for the lookahead item if it can use the gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // Penalize gaps that neither fit the next item nor are large.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Last chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading; favor filling.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * pressure;

    // New-bin candidate: only attractive when all open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        let worst_gap = if post_residual > 0 && post_residual < 10 { 40.0 * (10 - post_residual) as f64 } else { 0.0 };
        score += 15.0 - worst_gap;
    }

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: compare post_residual against next_item_size
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if (pr - nr).abs() < 0.5 {
            // Perfect fit for the next item: strong reward
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // Next item still fits after this placement: reward proportional to snugness
            score -= 12.0 * (1.0 - (pr - nr) / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize by how much it misses
            score += 4.0 + 0.25 * (nr - pr);
        }
    }

    // Last-chance bonus: only bin that can fit the item; avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize mildly, less so for large items (which leave small residuals)
    if bin_residual == bin_capacity {
        score += 14.0 - 0.12 * item_size as f64;
    }

    // Prefer bins tighter than the fleet mean residual (consume fragmented space first)
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are excellent: reward near-perfect packing.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    } else if post_residual <= 25 {
        score -= 6.0;
    }

    // Dead space: penalize residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits the post-residual, this placement chains nicely.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Bonus if the chain is near-exact.
        if post_residual - next_item_size <= 10 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // Next item can't use leftover here but could elsewhere; mild penalty.
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer bins where this item is a relatively better fit.
        score += 2.0 * (fitting_bins_count as f64).min(5.0);
    }

    // Global pressure: many open bins with slack -> prefer consolidation into existing bins.
    let mean_slack = mean_residual;
    if mean_slack > (bin_capacity as f64) * 0.5 {
        score += 5.0; // lots of slack overall; avoid waste
    }

    // Time horizon: early in the stream, be more conservative (favor new bins for big items);
    // late in the stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= progress * 10.0 * fill_ratio; // late stream: reward high fill ratio
    score += (1.0 - progress) * (item_size as f64 / 20.0); // early stream: penalize large items in partial bins

    // New-bin candidate adjustment: an empty bin is only attractive if the item is large
    // or existing bins are very full (small mean residual means open bins are crowded).
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 30.0;
        let big_item = item_size >= 50;
        if crowded || big_item {
            score -= 15.0;
        } else {
            score += 20.0; // prefer existing bins when they have room
        }
    }

    // Mild penalty for opening bins when many are already open but underused.
    if open_bins_count > 4 && bin_residual == bin_capacity && !big_item_flag(item_size) {
        score += 3.0 * ((open_bins_count as f64) - 4.0).min(6.0);
    }

    score
}

#[inline]
fn big_item_flag(item_size: u32) -> bool {
    item_size >= 50
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += poly * cap * 0.5;

    // Reward tight fits smoothly (low post residual)
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * item_size as f64 * 0.3;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize opening new bins late / many open bins
    score += (open_bins_count as f64).ln() * norm_pr * 5.0;

    // Lookahead: favor bins whose post residual fits next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        score += (next_item_size as f64 - pr).max(0.0) * 0.1;
    }

    // Mean residual coupling
    score += (mean_residual - pr) * 0.2;

    // New-bin candidate: mild penalty so real bins are preferred unless fit is bad
    if bin_residual == bin_capacity {
        score += 10.0 + progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space into capacity-fraction buckets.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;

    // Reward tight fits: post_residual in the lowest harmonic class.
    if post_residual <= eighth {
        score -= 18.0;
    } else if post_residual <= quarter {
        score -= 8.0;
    } else if post_residual <= bin_capacity / 2 {
        score -= 2.0;
    } else {
        // Very large leftover: poor utilization, penalize.
        score += 6.0;
    }

    // Lookahead harmony: does the next item fit into the post residual?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Perfect chaining: next item exactly fills or leaves small residue.
            let chain_post = post_residual - next_item_size;
            if chain_post <= eighth {
                score -= 25.0;
            } else if chain_post <= quarter {
                score -= 12.0;
            } else {
                score -= 4.0;
            }
            // Exact harmonic match reward (next item divides remaining space evenly)
            if chain_post == 0 {
                score -= 10.0;
            }
        } else {
            // Next item won't fit here: this bin becomes a dead-end for the lookahead.
            score += 10.0 + 0.25 * nx;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item is large relative to capacity
    // or when open bins are congested (high mean residual spread).
    if bin_residual == bin_capacity {
        // Fresh bin has full residual; base score is already high (= capacity).
        // Penalize opening a new bin when plenty of bins can still fit the item.
        if fitting_bins_count > 2 {
            score += 40.0;
        }
        // Favor new bin early in stream or when open bins are mostly full.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if mean_residual < cap * 0.15 {
            score -= 12.0; // existing bins nearly full -> new bin is fine
        }
        if item_size >= bin_capacity / 2 {
            score -= 6.0; // large items start fresh bins cleanly
        }
        if progress < 0.2 {
            score -= 3.0; // early stream: fresh bins are cheap
        }
    }

    // Modulo-style tie-breaking on post_residual to prefer residues that
    // align with common item-size classes (multiples of 10).
    let common = post_residual % 10;
    if common == 0 {
        score -= 3.0;
    } else if common >= 5 {
        score += 1.5;
    }

    // Slight penalty for scattering across many open bins.
    if open_bins_count > 20 {
        score += 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical items are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Last-chance bonus: only bin that fits avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins.
    score += 0.35 * open_bins_count as f64 * (1.0 - (post_residual as f64 / bin_capacity as f64));

    // Lookahead: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Slight preference for tighter bins relative to mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    }

    // Make new-bin candidate (empty bin) costly unless nothing else is viable.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Progression: later in stream, penalize opening new bins more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-perfect match: next item fits into post_residual with tiny waste.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: penalize proportionally to how badly it misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 0.8 * miss;
    }

    // Reward tight fits relative to mean residual of open bins.
    score -= (mean_residual - post_residual as f64).max(-50.0).min(50.0) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize creating small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Late in the stream, avoid opening new bins; prefer reusing existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later.
        score += 30.0 + 90.0 * progress;
        // Opening a new bin is fine if the next item is large and would leave this bin empty anyway.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 40.0;
        }
    } else {
        score -= 15.0 * progress;
    }

    // Prefer bins with more open bins available less; when few bins are open, reuse aggressively.
    if open_bins_count <= 2 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize small-but-unusable dead space (post residual too small for typical items).
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            score += 8.0; // next item won't fit here
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Prefer bins with residual below mean residual (fill fuller bins first).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Prefer opening new bins early in the stream; conserve flexibility later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize less early, more late.
        score += 20.0 * progress + 0.5 * open_bins_count as f64;
        // Opening a new bin is attractive if the item is large and fits poorly elsewhere.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 15.0 * progress;
        }
    } else {
        // Slight penalty for using many open bins when few remain to be seen.
        score += 0.3 * (1.0 - progress) * open_bins_count as f64;
    }

    // Reward exact fills.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly non-linear (dead space penalized super-linearly)
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling of post-residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-like
    score += poly * 30.0 * norm_pr;

    // Reward tight fits: small post residual, stronger late in stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (10.0 + 25.0 * poly);

    // Lookahead: if next item fits exactly in post residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let gap = pr - next_item_size as f64;
        score -= 15.0 * (1.0 - gap / cap);
    } else if next_item_size > 0 {
        // next item cannot use residual: penalize wasted space smoothly
        score += 8.0 * norm_pr * poly;
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * poly;
    }

    // Mean residual coupling: prefer bins close to mean (balance), smooth term
    let dev = (pr - mean_residual) / cap;
    score += 5.0 * dev * dev;

    // Crowding: many open bins -> prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual modulo a quantum of 10
    // captures "waste classes" — residuals like 1..9 are near-unusable dead space.
    let quantum = 10u32;
    let waste_class = post_residual % quantum;
    if post_residual > 0 {
        // Penalize small nonzero residuals (dead space) super-linearly.
        if waste_class > 0 && waste_class < 5 {
            score += (quantum - waste_class) as f64 * 2.0;
        } else if waste_class >= 5 {
            score += waste_class as f64 * 0.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Integer-division threshold: how many "average items" still fit.
    let avg_item = if total_items > 0 { bin_capacity / 2 } else { 50 };
    let fits_left = post_residual / avg_item.max(1);
    score -= fits_left as f64 * 3.0;

    // Lookahead coupling: harmonic class of next item vs post residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward, especially if it nearly fills the bin.
            score -= 15.0;
            let combined = post_residual - next_item_size;
            if combined % quantum == 0 {
                score -= 10.0; // harmonic alignment
            }
        } else {
            // Next item won't fit: penalize leaving a bin that strands it.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate (empty bin): only attractive when open bins are congested
    // or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        if congestion < 0.2 || item_size > 60 {
            score -= 12.0 + congestion * 20.0;
        } else {
            score += 15.0; // prefer using existing space when reasonably free
        }
    }

    // Mild pressure to consolidate as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (tighter bins first).
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Moderate dead space (10..20) is mildly penalized.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit: zero post_residual is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Exact fit for the next item's lookahead: big bonus for leaving exactly next_item_size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Leaving a gap too small for the next item is a dead-space risk.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only fitting bin, reward using it to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: add a fixed opening cost so it's chosen only when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Slight preference for filling tighter bins relative to mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and the next item size (perfect chaining of two items in one bin).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match gets a strong bonus; near matches get a decaying one.
        let match_bonus = if diff == 0.0 {
            60.0
        } else {
            40.0 / (1.0 + diff / 10.0)
        };
        // Only reward if the next item actually fits after this placement.
        if post_residual >= next_item_size {
            score -= match_bonus;
        } else {
            // Next item cannot fit here: penalize proportionally to how much
            // of the next item's demand is unmet (dead space for the chain).
            let shortfall = (next_item_size - post_residual) as f64;
            score += 0.3 * shortfall;
        }
    }

    // Penalize post_residual that is too small to ever be useful
    // (smaller than the typical minimum item size ~10): unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Prefer filling bins whose residual is already below the mean residual
    // (consolidate fullness, keep empty-ish bins available for future items).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Mild preference for reusing existing bins over opening new ones,
    // scaled by how crowded the bin already is (tight fits favored).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    if bin_residual != bin_capacity {
        score -= 8.0 * tightness;
    } else {
        // New-bin candidate: penalize unless it would give a much better
        // 2-step chain than any open bin (handled by lookahead terms above).
        score += 5.0;
    }

    // Late in the stream, prioritize closing out bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large dead space non-linearly, but only when truly unusable.
    let dead = post_residual as f64;
    score += 0.35 * (dead * dead) / bin_capacity as f64;

    // Reward tight fits: small post_residual is good.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: huge bonus
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect fit
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize slightly if we waste space it could have used.
        score += 6.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (penalize
    // cramming into existing bins less); late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let consolidation = 1.0 + 2.0 * progress;
    score /= consolidation;

    // Many open bins with high mean residual: encourage filling the fullest bins.
    if open_bins_count > 0 {
        let rel = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score -= 10.0 * rel; // prefer bins with more residual than average
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // fits well. Give it a baseline that's competitive but not dominant.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 20.0;
        score = bin_capacity as f64 - early_bonus
            - if fitting_bins_count == 0 { 80.0 } else { 0.0 };
        // If the next item is large and this item is small, opening fresh is attractive.
        if next_item_size > item_size * 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: penalize wasted space, quadratically for large dead space.
    let mut score = post + 0.004 * post * post / cap;

    // Tight-fit reward: smooth polynomial coupling of fit quality with stream progress.
    let fit_quality = 1.0 - post / cap; // 1 = perfect fit
    score -= 12.0 * fit_quality * fit_quality * fit_quality * (0.6 + 0.4 * progress);

    // Dead-space danger: residuals too small for the smallest plausible item are worthless.
    let small_item = if next_item_size > 0 && next_item_size < item_size { next_item_size } else { 10 };
    let unusable = (small_item as f64 - post).max(0.0);
    score += 0.15 * unusable * (1.0 + progress);

    // Lookahead: reward bins whose post-residual still fits the next item (smooth coupling).
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap >= 0.0 {
            let compat = 1.0 - gap / cap;
            score -= 6.0 * compat * compat * (0.5 + 0.5 * progress);
        } else {
            score += 0.08 * (-gap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    } else if fitting_bins_count > 2 {
        score += 1.5 * ((fitting_bins_count - 2) as f64).min(4.0) * (1.0 - progress);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.4 * open_bins_count as f64 * (post / cap) * (0.5 + 0.5 * progress);

    // New-bin candidate: make an empty bin attractive only when the current fit is poor.
    if bin_residual == bin_capacity {
        let poor_fit = (item_size as f64 / cap).powi(2);
        score = cap * (0.9 - 0.25 * progress) - 20.0 * poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue modulo 10 (capacity fraction classes)
    let class = post_residual % 10;
    // Residues that are hard to fill (small primes-ish gaps) get penalized
    let dead_penalty: f64 = match class {
        1 | 2 | 3 | 4 | 6 | 7 | 8 | 9 => 3.0,
        0 => -2.0, // perfectly aligned residual is reusable
        5 => 0.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Integer-division threshold: post_residual bucketed by quarters of capacity
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        score += 8.0; // tiny leftover = dead space
    } else if post_residual <= 2 * quarter {
        score -= 1.0; // half-ish leftover is decent
    } else {
        score -= 4.0; // large leftover is flexible
    }

    // Coupling with next item: reward residuals that exactly or nearly fit lookahead
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 6.0;
            } else {
                score -= 3.0;
            }
        } else {
            // lookahead won't fit here: penalize proportionally to wasted capacity
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.25;
        }
    }

    // Last-chance bonus: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only good when it enables
    // a tight packing of the lookahead (harmonic pairing), otherwise discourage.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) % 10 == 0 {
            score += 2.0; // aligned new bin, mild preference
        } else {
            score += 10.0; // discourage opening bins casually
        }
        // Very late in stream, fewer bins matter less
        if total_items > 0 && step_index as f64 / total_items as f64 > 0.9 {
            score -= 5.0;
        }
    }

    // Mean-residual coupling: if this bin is far below mean residual, it's already
    // fragmented; prefer bins with residual close to item usage.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for fuller bins as stream progresses
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (bin_capacity - post_residual) as f64 * 0.01 * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps super-linearly.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
