    // Reward tight fits relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / 20.0;
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
