    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        score += 12.0;
        // If lookahead item is large, a fresh bin is more attractive.
        if next_item_size > 50 {
            score -= 8.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 6.0;
    }

    // Lookahead: avoid leaving a gap that exactly blocks the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }
    // Reward residual that still fits the next item (keeps bin useful).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Mean residual coupling: prefer bins close to the mean (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 5.0;

