    if next_item_size > 0 && post_residual >= next_item_size {
        // Perfect chain: next item exactly fills the leftover space -> strong reward.
        let exact = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - exact / bin_capacity as f64);
        // Prefer larger leftover usable for the future item relative to mean residual.
        score -= 0.5 * (next_item_size as f64 / (mean_residual + 1.0));
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space, especially small slivers.
        let waste = post_residual as f64;
        if waste < 10.0 {
            score += 25.0; // tiny unusable sliver
        } else {
            score += 0.3 * waste;
        }
    }

    // Penalize bins far from the mean residual (avoid fragmenting average state).
    score += 0.2 * ((post_residual as f64 - mean_residual).abs());

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // the current item is large and would leave a big hole in an existing bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item_penalty = if item_size > 50 && post_residual > 0 && (post_residual as f64) < 10.0 { 50.0 } else { 0.0 };
        score += 10.0 + 40.0 * progress + big_item_penalty;
        // A fresh bin is good if lookahead chains well (e.g. item + next item near capacity).
        if next_item_size > 0 && (item_size + next_item_size) as f64 >= 0.9 * bin_capacity as f64 {
            score -= 35.0;
        }
    }

    // Mild preference for tighter bins overall as stream progresses.
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * (step_index as f64 / (total_items.max(1) as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual relative to capacity.
    score -= (1.0 - (post_residual as f64) / cap) * 30.0;

    // Penalize dead space that no future item can plausibly fill.
    // Dead space = post_residual smaller than the smallest plausible item (assume ~10)
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize leaving awkward leftovers.
            let gap = (next_item_size as i64 - post_residual as i64).unsigned_abs() as f64;
            score += gap * 0.5;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when fits are poor
    // or the stream is early. Make the fresh bin mildly expensive by default.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Fit quality of the current item in an empty bin:
        let fit_quality = 1.0 - (item_size as f64 / cap);
        // Penalize new bins more when the item fits well elsewhere (large item => low penalty)
        score += 55.0 * (1.0 - fit_quality);
        // Early in the stream, opening bins is cheaper; late, expensive.
        score += 30.0 * progress;
        // If many bins are already open, discourage proliferation.
        score += (open_bins_count as f64).sqrt() * 4.0;
        // If the next item could pair with this item in a fresh bin, ease opening.
        if next_item_size > 0 && (next_item_size + item_size) as f64 <= cap {
            score -= 20.0;
        }
    }

    // Prefer bins with residuals below the mean (consolidating waste) slightly.
    let dev = (bin_residual as f64) - mean_residual;
    score += dev * 0.15;

    // Mild preference to fill bins that are already fairly full.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= fill * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling: reward tight fits quadratically.
    let fit_ratio = item_size as f64 / cap;
    score -= 12.0 * fit_ratio * fit_ratio * (1.0 + progress);

    // Penalize small unusable residuals (dead space) smoothly.
    let dead = pr / cap;
    score += 30.0 * dead * dead * dead * (1.0 - dead).max(0.0);

    // Lookahead: reward bins whose post-residual fits the next item.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let nx = next_item_size as f64 / cap;
        score -= 8.0 * nx * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 4.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    // Mild penalty for opening new bins when many bins are open.
    let is_new = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new {
        score += 6.0 + 2.0 * (open_bins_count as f64).sqrt() + 5.0 * progress;
    }

    // Interaction with mean residual: prefer bins near the mean (balance).
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: bins whose residual falls into
    // "reusable" classes (multiples of common item sizes) should be favored.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Fractional capacity class of the post residual (eighths of the bin).
    let frac = post / cap;
    let class = (frac * 8.0).floor() as i64;

    // Reward residuals that are still "large enough" to host typical items,
    // penalize awkward mid-range dead space via a harmonic penalty.
    let harmonic = 1.0 / (class as f64 + 1.0);
    score += 20.0 * harmonic;

    // Modulo arithmetic on post_residual: residuals divisible by small
    // common sizes (10, 20, 25, 50) are more likely to be filled later.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }
    } else {
        // Perfect fit: reward strongly.
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits the post residual exactly or
    // nearly, reward this placement.
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        if (post - nd).abs() < 1.0 {
            score -= 12.0;
        } else if post >= nd && post - nd <= 10.0 {
            score -= 7.0;
        } else if post < nd && post > 0.0 {
            // next item won't fit here: dead space likely, penalize.
            score += 5.0 * (1.0 - post / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and few bins are open (early stream, big item -> fresh bin is fine).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big = item_size as f64 > 0.6 * cap;
        if big && open_bins_count > 0 && progress > 0.2 {
            score += 10.0; // discourage wasting fresh bins later on big items
        } else {
            score += 3.0; // mild default penalty for new bin
        }
    }

    // Mean residual context: when open bins are on average roomy, prefer
    // filling the emptiest ones; tighten scoring accordingly.
    score -= 0.3 * (mean_residual - post) / cap;

    // Progress-based tie-breaker: late in the stream, consolidate more
    // aggressively (dead space is costlier when few items remain).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual < 35 {
        score += 5.0;
    }

    // Reward tight fits strongly.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into the post residual, big bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Open bins pressure: many open bins -> prefer filling existing bins,
    // penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += 10.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Prefer bins with below-average residual (denser bins) when many bins open.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size exactly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 6.0 * (1.0 - slack as f64 / bin_capacity as f64);
        if slack == 0 {
            score -= 10.0; // perfect 2-step fit
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space: next item cannot use this residual
        score += 4.0;
    }

    // Compare post_residual relative to mean residual: prefer tighter-than-average fits
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Penalize leaving large unusable residual
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // tiny residual is nearly perfect packing
    } else if post_residual >= 10 && post_residual < 20 {
        score += 1.5; // awkward dead zone
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // New-bin candidate: only attractive late in the stream or when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 12.0 - 8.0 * progress - 0.5 * crowding;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // new bin pairs well with upcoming large item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fill is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // The next item can still fit here: keep this bin attractive.
        score -= 18.0;
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item.
        score += 12.0;
    }

    // Last chance bin: strongly prefer using it over opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: mild penalty that grows with number of open bins,
    // encouraging consolidation, but relax late in the stream.
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 + 0.3 * open_bins_count as f64 - 5.0 * progress;
        // If the next item would fit perfectly in the leftover, opening a fresh
        // bin is less attractive.
        if next_item_size > 0 && next_item_size == post_residual {
            score += 10.0;
        }
    }

    // Slight preference for bins whose residual is below the mean (tight bins).
    score += 0.05 * (mean_residual - post_residual as f64);

    // Penalize leaving awkward small residuals (wasted slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear penalty growth
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth coupling of post-residual with stream progress:
    // late in the stream, dead space becomes more costly
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Reward tight fits (small post_residual relative to item) via smooth term
    let tightness = 1.0 - norm_pr;
    score -= (item_size as f64 / cap) * tightness * 12.0;

    // Penalize when this is the only fitting bin less strongly (we must use it)
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Lookahead: if next item fits in the post-residual, reward this bin
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        // next item won't fit: mild penalty scaled by how much it misses
        let miss = (next_item_size as f64 - pr) / cap;
        score += 4.0 * miss * miss;
    }

    // Prefer filling bins with larger mean residual (consolidate waste)
    score -= 0.05 * (mean_residual - pr);

    // Slight preference for using existing bins over opening new ones,
    // weakening as stream progresses (allow more bins late if needed)
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress);
    }

    // Mild penalty for many open bins, smoothed
    score += 0.02 * open_bins_count as f64 * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable" sizes
    // (multiples of 10 are classic harmonic anchors; small residues are dead space).
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect closure: best possible outcome
    } else {
        let class = post % 10;
        // Residues that are multiples of 10 pair well with common item sizes
        score -= match class {
            0 => 25.0,
            5 => 12.0,
            _ => 0.0,
        };
        // Dead-space penalty grows super-linearly for tiny unusable residues
        if post < 10 {
            score += (10 - post) as f64 * 3.0;
        }
        // Integer-division threshold: high post_residual means lots of room left,
        // mildly preferred so big future items still fit.
        let div = post / 20; // 0..5 harmonic band
        score -= div as f64 * 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is part of a perfect chain -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 45.0;
        } else if next_item_size <= post {
            // next item fits but leaves a residue; penalize bad chained residue
            let chain_res = post - next_item_size;
            score -= 15.0 - (chain_res % 10) as f64 * 0.8;
        } else {
            // next item won't fit here; penalize more if this bin was the only option
            score += 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so we only
    // open new bins when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 0.5);
        // If current item is large relative to capacity, opening fresh is cheaper
        let waste_if_open = bin_capacity - item_size;
        if waste_if_open < 20 {
            score -= 30.0;
        }
    } else {
        // Prefer tighter fits: reward small post_residual relative to capacity
        let tightness = 1.0 - (post as f64 / bin_capacity as f64);
        score -= tightness * 20.0;
    }

    // Stream progression: late in the stream, close bins aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mean residual context: if this bin's residual is far below the mean,
    // it is a tight fit worth prioritizing.
    score -= (mean_residual - post as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead space: gaps below min item size (1..10) are worthless,
    // gaps in [10, 20) are hard to fill. Non-linear dead-space penalty.
    let gap = post_residual as f64;
    if gap > 0.0 && gap < 10.0 {
        score += 60.0 * (1.0 - gap / 10.0); // fully wasted capacity
    } else if gap >= 10.0 && gap < 20.0 {
        score += 25.0 * (1.0 - (gap - 10.0) / 10.0);
    }

    // Reward tight fits (small post_residual relative to item size)
    if item_size > 0 {
        score -= 0.35 * (item_size as f64) * (1.0 - gap / bin_residual.max(1) as f64);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 80.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item
    if next_item_size > 0 && post_residual > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual - next_item_size < 10 {
            score -= 20.0;
        }
    }
    // Penalize leaving a gap that the next item almost fits but cannot
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual + 10 > next_item_size {
        score += 30.0;
    }

    // Open-bins pressure: with many open bins, favor reusing this bin over opening new ones
    score -= 0.8 * open_bins_count as f64;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: mildly penalize opening a new bin unless stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 + 25.0 * progress;
    }

    // Prefer bins tighter than the mean residual
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual > next_item_size {
            score -= 50.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't fit here; penalize leftover less if tiny
            score += 20.0;
        }
    } else {
        // last item: prefer filling existing bins fully
        score -= 200.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize creating dead space below typical item sizes (unusable gap)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in stream, be slightly more willing to open new bins for large items
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new bin candidate: baseline cost, less attractive as stream progresses
        score += 30.0 + 40.0 * progress;
        if item_size > 60 && next_item_size > 60 {
            score -= 25.0; // big items pair poorly, allow fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let residual = bin_residual as f64;
    let fill_ratio = if residual > 0.0 { item_size as f64 / residual } else { 0.0 };
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize small-but-nonzero dead space (unusable slivers), but reward exact fits.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 12.0; // dead sliver
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Lookahead: if the next item can fit into the post-residual, this bin stays valuable.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            score -= 10.0 * (1.0 - next / 100.0);
        } else {
            // Post-residual too small for the next item: penalize proportionally to waste.
            score += 6.0 * (post_residual as f64 / 100.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins with large mean residual: discourage scattering into already-loose bins.
    if open_bins_count > 2 {
        let looseness = (mean_residual - residual) / bin_capacity as f64;
        score += 5.0 * looseness;
    }

    // Time horizon: early in the stream, be more willing to consolidate into existing bins;
    // late in the stream, allow opening new bins for cleaner packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early, relax late; also penalize if many bins already open.
        score += 25.0 * (1.0 - progress) + 1.5 * open_bins_count as f64;
        // If no existing bin is a good fit (post_residual tiny), new bin becomes attractive.
        if post_residual == bin_capacity && item_size >= 50 {
            score -= 10.0;
        }
    } else {
        score -= 5.0 * progress;
    }

    // Mild global pressure: when mean residual across bins is low, favor existing bins more.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer bins leaving small residual (best-fit), scaled smoothly.
    let mut score = pr;

    // Non-linear polynomial coupling: residual waste penalized more as stream progresses.
    let norm_pr = pr / cap;
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Coupling of item size with post residual: large items in tight bins favored.
    score -= 0.05 * (it / cap) * (cap - pr);

    // Dead-space penalty: residual too small for any future item (below min size 1,
    // but relative to mean residual structure) — smooth term.
    let dead = ((12.0 - pr) / 12.0).max(0.0);
    score += 6.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins mildly, more when open bins exist
    // and mean residual is large (existing space available).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * (open_bins_count as f64) + 0.2 * mean_residual;
        // Late in stream with small next item, opening is cheaper.
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Lookahead: reward bins whose post-residual fits the next item exactly-ish.
        let gap = ((next_item_size as f64) - pr).abs();
        score -= 10.0 * (1.0 - gap / cap).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10
    let class = post_residual % 10;
    // Dead-space penalty: residuals not expressible as sums of typical item sizes
    // are penalized; small "harmonic" residuals (0, multiples of 10) are rewarded.
    let harmonic_bonus = match class {
        0 => 25.0,                    // perfectly harmonic residual
        5 => 10.0,                    // half-harmonic
        1 | 9 => -3.0,
        2 | 8 => -6.0,
        3 | 7 => -10.0,
        _ => -15.0,                   // 4,6: awkward class
    };
    score -= harmonic_bonus;

    // Integer-division thresholds on post_residual: very small residuals waste bins
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // nearly-dead space
    }
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    }

    // Capacity-fraction coupling: reward filling toward capacity fractions
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;
    if fill_frac >= 0.5 && fill_frac < 1.0 {
        score -= 15.0 * fill_frac;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 60.0; // chained perfect fit
        } else {
            let next_class = (post_residual - next_item_size) % 10;
            if next_class == 0 { score -= 30.0; }
            else { score -= 8.0; }
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 12.0; // next item can't use this residual
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin fit is bad
    if bin_residual == bin_capacity {
        let good_fit = post_residual < 30 && (post_residual % 10 == 0 || post_residual % 10 == 5);
        score += if good_fit { 10.0 } else { 70.0 + mean_residual * 0.3 };
    }

    // Stream progression: late in stream, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / cap);

    // Bin count pressure: many open bins -> favor filling existing ones
    score += 2.0 * open_bins_count as f64 * 0.1;

    // Mean residual divergence: prefer bins close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps more than large ones.
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            // Dead space: nearly unusable gap -> heavy penalty.
            score += (10.0 - gap) * 12.0;
        } else if gap < 20.0 {
            // Marginal gap: likely unusable for future items (min size 10).
            score += (20.0 - gap) * 4.0;
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open bins pressure: discourage spreading across many bins when tight fits exist.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 {
        if next_item_size as f64 == post_residual as f64 {
            score -= 35.0;
        } else if next_item_size as u32 > post_residual {
            // Next item won't fit here; slightly penalize leaving a gap that traps it.
            if post_residual > 0 && post_residual < next_item_size {
                score += 6.0;
            }
        }
    }

    // New-bin candidate: make opening a new bin costly unless current bin would be left
    // with a terrible gap or no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 25.0;
        // If the only fitting bin would leave a tiny dead space, allow new bin instead.
        if post_residual == 0 {
            // Empty bin keeps residual 100; score is 25 - bonuses, acceptable.
        }
        // As stream matures, opening new bins gets cheaper (waste unavoidable).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
        // If many open bins with high mean residual, prefer packing into them.
        score += (mean_residual / 10.0).min(15.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when next item fits perfectly into the post-residual space.
        if post_residual == next_item_size {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize large leftover dead space.
            score += 0.15 * gap;
        }
    }

    // Reward tight fits relative to the item itself.
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 - post_residual as f64);

    // Penalize deviation from mean residual (avoid fragmenting the fleet unevenly).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current item is large and
    // would leave big dead space elsewhere, or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let tight_fleet = mean_residual < 0.35 * bin_capacity as f64;
        if tight_fleet || item_size > 60 {
            score -= 12.0 + 10.0 * progress;
        } else {
            score += 20.0; // discourage opening bins while existing ones have room
        }
    }

    // Slight preference for keeping a small pool of open bins early in the stream.
    score += 0.05 * open_bins_count as f64 * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
