pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with non-linear sharpening.
    let mut score = pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling with stream progress: tighten packing later in the stream.
    score += 40.0 * progress * norm_pr * (1.0 - progress);

    // Penalize dead space that cannot fit a plausible next item.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 12.0 * ((next_item_size as f64) - pr) / cap;
    } else if next_item_size > 0 {
        // Reward bins whose post-residual still accommodates the lookahead item.
        score -= 6.0 * (1.0 - (next_item_size as f64) / pr);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mildly favor consolidating into bins below mean residual (tighter bins).
    score -= 4.0 * ((mean_residual - pr) / cap);

    // New-bin candidate: neutral-ish baseline, penalized early, allowed late
    // or when the fit would be poor.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.5 * progress) + 0.5 * pr;
        if next_item_size > 0 && (next_item_size as f64) > (bin_capacity - item_size) as f64 {
            score -= 30.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
