pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap below the minimum item size (1..100 range -> threshold ~12) is dead space.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0 * (dead_threshold - post_residual as f64);
    }

    // Non-linear penalty on small-but-nonzero residuals that most items can't fill.
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64).powf(1.6) * 0.8;
    }

    // Perfect or near-perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 80.0;
    }

    // Reward using a bin when it's the only fitting bin (last chance before new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is good.
    score += (open_bins_count as f64).powf(1.2) * 0.5;

    // Prefer tighter bins: penalize if this bin's residual is far above mean residual.
    if (bin_residual as f64) > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    }

    // Lookahead: if next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score += 5.0; // mild penalty: keeping flexibility is slightly worse than exact match
    }

    // New-bin candidate: penalize mildly so we only open when fits are truly bad;
    // but early in the stream opening fresh bins is cheaper.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 - 20.0 * progress;
        if post_residual as f64 > 0.0 { score += 10.0; } // empty bin has no post residual issue; keep guard
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match of post_residual with next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // ideal: next item exactly fills this bin afterwards
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += gap * 0.35; // penalize mismatch proportionally
            // bonus if next item could still fit after this placement
            if post_residual >= next_item_size {
                score -= 8.0;
            }
        }
    } else {
        // last item: prefer tightest fill
        score -= 5.0;
    }

    // Compare against mean residual across open bins
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize leaving dead space that is very small (unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let poor_fit = next_item_size > 0
            && post_residual == bin_capacity
            && (fitting_bins_count == 0 || (post_residual as i64 - next_item_size as i64).unsigned_abs() > 15);
        if poor_fit {
            score -= 10.0;
        } else {
            score += 20.0; // discourage opening new bins when decent fits exist
        }
    }

    // Late in stream: tighten packing, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 6.0;

    // Prefer bins whose residual is already small (consolidate fragmentation)
    score += (bin_residual as f64 / bin_capacity as f64) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Penalize dead space: post_residual smaller than the minimum item size is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score += 20.0; // next item would leave dead space here
        } else if next_item_size > post_residual {
            score += 8.0; // this bin becomes dead for the next item
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Empty new-bin candidate: prefer it only when open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are opened only when justified.
        score += 35.0;
        // More open bins with high mean residual -> discourage opening another.
        score += mean_residual * 0.4 + open_bins_count as f64 * 3.0;
        // Early in the stream, opening bins is cheaper (future items can use them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
        // If item is large relative to capacity, new bin is more attractive.
        score -= (item_size as f64 / bin_capacity as f64) * 20.0;
    } else {
        // Favor bins whose residual is close to the item (minimize fragmentation).
        let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
        score += tightness * 10.0;
        // Slightly prefer bins with residual well above mean (keeps balance).
        score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 5.0;
    }

    // Late in the stream, be greedier about tight fits (less future to amortize).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Dead-space penalty grows non-linearly with progress (late waste costs more)
    score += norm_pr * norm_pr * 40.0 * (0.3 + 0.7 * progress);

    // Reward tight fits, amplified over time
    score -= norm_item * (1.0 - norm_pr) * 30.0 * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening new bins when others fit, more early on
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // But allow new bin if post_residual would be perfect for next item
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 8.0;
        }
    }

    // Lookahead: reward leaving room for the next item
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * 15.0;
    }

    // Mild coupling with mean residual to prefer bins deviating from mean
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: group post_residual into capacity-fraction classes.
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap; // fraction of capacity left over

    // Penalize leftovers that fall into "dead" harmonic classes:
    // classes near (1/2, 3/4) are re-usable; tiny leftovers (< ~1/8) are dead space.
    if frac < 0.125 {
        score += 40.0 * (0.125 - frac); // dead-space penalty
    } else if frac < 0.25 {
        score -= 6.0; // quarter-class is decent
    } else if frac < 0.5 {
        score -= 10.0; // half-class is very reusable
    } else {
        score -= 4.0; // roomy bin, mild reward
    }

    // Integer-division threshold: can the next item fit exactly into the post residual?
    // Exact fit (post_residual % next_item_size == 0) creates perfect harmonic closure.
    if next_item_size > 0 && next_item_size <= post_residual {
        if post_residual % next_item_size == 0 {
            score -= 18.0; // perfect modulo match with lookahead
        } else if post_residual - next_item_size < 10 {
            score += 8.0; // would leave a sliver after next item
        } else {
            score -= 4.0; // next item still fits reasonably
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here anyway; mildly neutral, but if this bin is
        // already in a good harmonic class keep it attractive.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when all open bins
    // would produce bad fits. Give it a baseline cost that scales with stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 55.0 + 20.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.3 * mean_residual;
        if fitting_bins_count > 0 {
            score += 30.0; // discourage skipping usable open bins
        }
        // If next item is huge, a fresh bin is more valuable.
        if next_item_size > 0 && (next_item_size as f64) > 0.6 * cap {
            score -= 15.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large share of residual.
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill;

    // Slight preference to consolidate into fewer bins when many are open.
    score += 0.15 * open_bins_count as f64 * (1.0 - fill);

