    // Prefer filling bins that are already relatively full vs mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Strongly discourage opening a new bin while good open bins exist.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        // early in stream, be more willing to open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) < 0.2 {
            score -= 8.0;
        }
    }

    // Mild preference for tight fits overall.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty proportional to waste.
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64).min(1.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be conservative about filling bins poorly;
    // late in the stream, prioritize closing bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins with high mean residual -> prefer bins
    // below the mean residual (consolidation effect).
    let residual_gap = mean_residual - bin_residual as f64;
    score += 0.15 * residual_gap;

    // Penalize opening new bins when many bins are already open and item fits well.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.5 * open_bins_count as f64;
        // But if this is a large item and open bins are crowded, opening is fine.
        if item_size as f64 > mean_residual {
            score -= 10.0;
        }
    }

    // Mild bonus for bins whose residual is close to item size (perfect-ish fits).
    let slack = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.05 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Cubic term: penalize large dead space more aggressively as stream advances
    score += 40.0 * norm_pr * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits, stronger near the end of the stream
    score -= (cap - pr) * 0.15 * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += 6.0 * (1.0 - pr / nxt.max(1.0));
        } else {
            score -= 4.0 * (pr - nxt) / cap;
        }
    }

    // Slight penalty when many bins are open and residual is far from mean
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: neutral-ish baseline scaled by progress
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "reusable" class (large enough to host typical items) are favored.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds via integer division on post_residual.
    let class = post_residual / 10; // 0..=10 harmonic bucket
    let class_bonus: f64 = match class {
        0 => -30.0,                      // near-perfect fit, dead space ~0
        1 => -18.0,                      // tiny leftover, likely dead
        2..=4 => 6.0,                    // awkward mid gap (11-49)
        5..=7 => -8.0,                   // 50-79: still broadly usable
        _ => -12.0,                      // 80+: very reusable
    };
    score += class_bonus;

    // Exact-fit harmonic reward: post_residual divisible classes
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual % 10 == 0 {
        score -= 10.0; // round leftover tends to pair with round items
    }

    // Lookahead coupling: reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= (1.0 - slack / cap) * 15.0; // tighter future fit -> better
            if post_residual == next_item_size {
                score -= 25.0; // perfect chain
            }
        } else {
            score += 8.0; // next item won't fit here; bin likely closes
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    if bin_residual == bin_capacity {
        score += 12.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin keeps space for a possibly larger next item
        }
    }

    // Prefer filling bins that deviate below the mean residual (consolidate)
    score += 0.25 * (mean_residual - pr).max(0.0);

    // Mild late-stream pressure: consolidate more as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min size 1, but practically < ~10) are wasted capacity.
    if post_residual > 0 {
        if post_residual <= 10 {
            // Unusable gap: penalize heavily, scaled by how much capacity is locked.
            score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
        } else if post_residual >= next_item_size as f64 as u32 && next_item_size > 0 {
            // Residual can host the next item: reward lookahead compatibility.
            score -= 6.0;
            if post_residual == next_item_size {
                score -= 10.0; // perfect lookahead fill
            }
        }
        // Moderate dead space: mild penalty proportional to locked capacity.
        score += 0.15 * (post_residual as f64);
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless needed.
    score += 0.5 * (open_bins_count as f64);

    // Prefer bins below mean residual (denser bins absorb items first).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when the item fits poorly everywhere
    // else or creates a near-perfect split of a fresh bin.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with how many bins are already open.
        score += 20.0 + 0.4 * (open_bins_count as f64);
        // Reward opening a fresh bin when the item is large relative to capacity
        // (leaves a clean, reusable residual).
        let fill_frac = (item_size as f64) / (bin_capacity as f64);
        if fill_frac > 0.8 {
            score -= 18.0;
        }
        // If no other bin fits, opening a new bin is necessary: soften cost.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Slight stream-progression pressure: as the stream ends, prefer closing
    // bins tightly over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Reward near-matching residuals for the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual as f64 - next_item_size as f64);
        score -= 200.0 / (1.0 + slack);
    }
    // Penalize creating a residual that cannot fit the next item
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 150.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Penalize opening new bins when open bins can fit
    if bin_residual == bin_capacity {
        score += 50.0 + (open_bins_count as f64 * 2.0);
    }

    // Late-stream consolidation: favor filling bins more tightly as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere else (last-chance or very fragmented state).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize new bins more when few bins fit the item (last chance
        // should be used), and when the open-bin count is small.
        let mut new_bin_penalty = 40.0 + 6.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            new_bin_penalty += 120.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        new_bin_penalty *= 0.5 + 1.5 * progress;
        // If next item is large, opening a fresh bin may be wise; soften penalty.
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            new_bin_penalty *= 0.6;
        }
        score += new_bin_penalty;
        return score;
    }

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Lookahead: if the next item exactly fits the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect pairing
        } else if next_item_size <= post_residual {
            // next item fits here too; mild reward proportional to use of space
            let use_ratio = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * use_ratio;
        } else {
            // next item won't fit; penalize leaving awkward gaps
            let gap = post_residual as f64;
            if gap > 0.0 && gap < 10.0 {
                score -= 10.0; // small dead space is fine
            } else if gap >= 10.0 && gap < next_item_size as f64 {
                score += 12.0; // gap that blocks the known next item
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, heavily favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Among multiple fitting bins, prefer ones with less residual (best-fit bias)
        score += 0.15 * (bin_residual as f64 - item_size as f64);
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (fill the fullest bins first, keeping large residuals available).
    let resid_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (resid_f - mean_residual);
    }

    // Time horizon: as stream progresses, be more conservative about
    // leaving large residuals (less future to absorb them).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Slight penalty for very small items wasting big bins, scaled by progress.
    if item_size <= 20 && bin_residual >= 70 {
        score += 8.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: reward tight fits (low post residual), with non-linear sharpening
    let mut score = pr_norm * pr_norm * cap;

    // Polynomial coupling of post_residual with stream progress:
    // late in the stream, residual waste matters more (harder to fill later)
    let progress_coupling = pr_norm * (1.0 + 2.0 * progress * progress) * 30.0;
    score += progress_coupling;

    // Smooth penalty for large post residual relative to mean residual (dead space)
    let mean_norm = mean_residual / cap;
    score += (pr_norm - mean_norm) * (pr_norm - mean_norm) * 40.0 * (0.5 + progress);

    // Reward when this bin is the last fitting option (avoid opening new bins)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: bonus if next item fits into post residual (smooth ramp)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 15.0 * fit_frac * (1.0 - fit_frac) * 4.0;
    }

    // Mild penalty for spreading across too many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: smooth penalty so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 20.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class the dead space into harmonic buckets of capacity/8
        let class = (post_residual * 8 / bin_capacity) as f64;
        // Small classes (0,1) are good (tight fit); large classes waste
        score += class * class * 2.0;

        // Dead space that cannot fit the next item is worse
        if next_item_size > 0 && post_residual < next_item_size {
            score += 25.0;
        } else if next_item_size > 0 {
            // reward if next item fits snugly into the new residual
            let nxt = next_item_size as f64;
            if (pr - nxt).abs() < cap * 0.05 {
                score -= 20.0;
            }
            score -= 5.0;
        }

        // Modulo-10 arithmetic on post_residual: round residuals pair well
        let m10 = post_residual % 10;
        if m10 == 0 {
            score -= 8.0;
        } else if m10 >= 5 {
            score += m10 as f64 * 0.5;
        }

        // Last chance bin: strong reward to avoid opening a new bin
        if fitting_bins_count == 1 {
            score -= 30.0;
        }

        // New bin candidate: penalize unless current open bins are too full
        if bin_residual == bin_capacity {
            let pressure = mean_residual / cap;
            score += 40.0 - pressure * 20.0 + (open_bins_count as f64) * 0.5;
        }

        // Late in stream: prefer tighter packing
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += pr * (0.2 + 0.6 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are unusable gaps -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward using a bin whose residual closely matches the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 30.0;

    // Last chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor new bin
    // only when this placement would waste a lot.
    let pressure = open_bins_count as f64 / (total_items as f64).max(1.0);
    score += pressure * 20.0 * (post_residual as f64 / bin_capacity as f64);

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: neutral baseline with slight bias toward using open
    // bins unless dead space penalty dominates.
    if bin_residual == bin_capacity {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled slightly.
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when the next item exactly fills the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect 2-chain: post_residual consumed entirely by next item.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item still fits; reward proportional to leftover after it.
            let after_next = post_residual - next_item_size;
            score -= 25.0 - (after_next as f64) * 0.3;
        } else {
            // Next item won't fit here; penalize large dead space.
            let waste = next_item_size - post_residual;
            score += (waste as f64) * 0.5;
        }
    }

    // Penalize leaving small unusable slivers (dead space) relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver is nearly worthless
    }

    // Coupling with mean_residual: prefer bins that are outliers below the mean
    // (i.e., fill down the emptiest bins first to consolidate space).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the fit is poor.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; add penalty so only bad fits in open bins
        // make a new bin attractive.
        score += (bin_capacity as f64) * 0.55;
        // But if no existing bin fits at all, opening fresh is fine.
        if fitting_bins_count == 0 {
            score -= (bin_capacity as f64) * 0.55;
        }
    }

    // Late-stream consolidation: as the stream progresses, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 30.0;
    }

    // Slight preference for bins with residual close to item_size (near-exact fits).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squashed post-residual dominates the score.
    score -= (bin_residual as f64 - post_residual as f64) * 0.35;

    // Penalize small dead space that no future item can plausibly use
    // (items are >= 1, but usable-space reward decays with fragmentation).
    if post_residual > 0 {
        score += 12.0 / (post_residual as f64).sqrt();
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly reward this placement; if it blocks the next item, penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack_after_pair = post_residual as f64 - next_item_size as f64;
            score -= 6.0 * (1.0 - slack_after_pair / bin_capacity as f64);
        } else {
            score += 2.0 * (next_item_size as f64 - post_residual as f64).min(30.0);
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin is attractive only when
    // existing bins fit poorly or are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if open_bins_count == 0 { 40.0 } else { 0.0 };
        let poor_options = if fitting_bins_count == 0 { 15.0 } else { 0.0 };
        let mean_pull = (mean_residual - item_size as f64).max(0.0) * 0.3;
        score += 18.0 - 12.0 * progress - scarcity - poor_options + mean_pull;
    } else {
        // Prefer bins whose residual is far above the mean (drain large bins first),
        // keeping small residuals available for small items late in the stream.
        score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Mild time pressure: early in the stream, consolidating into few bins
    // is favored; late in the stream, avoid over-tight packing that strands space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * (1.0 - progress) / (open_bins_count.max(1) as f64);

    // Slight preference for bins with residual close to a multiple of item size,
    // encouraging repeatable stacking patterns.
    if item_size > 0 && bin_residual % item_size == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Smooth non-linear penalty on wasted space, amplified by stream progress.
    let waste_frac = post / cap;
    let poly = waste_frac * waste_frac * (1.0 + 3.0 * progress);
    score += 25.0 * poly;

    // Reward tight fits (small post_residual) with a cubic bonus.
    score -= 18.0 * (1.0 - waste_frac).powi(3);

    // Interaction: small residual is valuable late in the stream.
    score += 8.0 * waste_frac * progress;

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: penalize leaving residual that neither helps nor matches next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 6.0 * (1.0 - (post - nxt) / cap).abs();
        } else {
            score += 5.0 * (nxt - post) / cap;
        }
    }

    // Mild pressure against proliferation of open bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap - waste_frac).abs();

    // Slight preference for using existing bins over opening new ones early.
    score -= 2.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality classes.
    // Class 0 (perfect fit) heavily rewarded; small residuals penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space class: residual below the minimum item size (1) can't happen,
        // but residuals too small to hold typical items are wasted.
        // Use modulo-classes on post_residual (harmonic buckets of 10).
        let class = post_residual % 10;
        score += match class {
            0 => -30.0,          // exact decade residual: very reusable
            1..=3 => 12.0,       // awkward sliver
            4..=6 => 4.0,
            7..=9 => -6.0,       // roomy enough for mid items
            _ => 0.0,
        };

        // Fractional capacity classes: post_residual relative to capacity quarters.
        let quarter = (pr / (cap / 4.0)).floor();
        score += match quarter as u32 {
            0 => 10.0,   // < 25% left: nearly dead
            1 => 0.0,
            2 => -8.0,
            _ => -15.0,  // > 75% left: very flexible
        };
    }

    // Integer-division threshold: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain fit: reward proportionally, stronger for tight chains.
            score -= 25.0 + 0.3 * (next_item_size as f64);
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit here; slight penalty if we leave a big unusable gap.
            if (post_residual as u32) < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer fullest bins (tightest fit) when many bins are open.
    score -= 0.5 * (bin_residual as f64 / cap) * (open_bins_count as f64).sqrt();

    // Early stream: be greedy toward filling existing bins; late stream: keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (post_residual as f64 / cap);

    // New-bin candidate: penalize slightly so it's only chosen when open bins are bad,
    // but reward it if no good residual class exists among open bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // reserving empty bin for large upcoming item
        }
    }

    // Small alignment bonus: residual divisible by common item sizes (harmonic divisibility).
    if post_residual > 0 {
        for d in [10u32, 20, 25, 50] {
            if post_residual % d == 0 {
                score -= 8.0;
                break;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual that is still usable).
    if post_residual > 0 && post_residual >= 10 && post_residual <= 20 {
        score -= 8.0;
    }

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Open-bins pressure: penalize using bins when many are open,
    // but only mildly, so tight fits still win.
    score += (open_bins_count as f64) * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into the post_residual,
    // reward this placement (chain packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Penalize new-bin opening when reasonable open capacity exists,
    // unless the item is large relative to mean residual (poor fits everywhere).
    if bin_residual == bin_capacity {
        score += 20.0;
        if item_size as f64 > mean_residual {
            score -= 25.0;
        }
    }

    // Mild progression term: as the stream advances, prefer consolidating
    // into fewer bins (slightly stronger pressure to fill existing bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-match: next item fits into post_residual with small slack -> graded reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual {
        // Next item cannot chain into this bin: penalize dead space left behind.
        let dead = post_residual as f64;
        score += 0.3 * dead;
    }

    // Reward filling bins tightly relative to the mean residual of open bins.
    let residual_f = bin_residual as f64;
    if residual_f > mean_residual {
        score -= 0.2 * (residual_f - mean_residual);
    } else {
        score += 0.2 * (mean_residual - residual_f);
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins when open bins exist and the item is small.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 0.5 * item_size as f64;
    }

    // Late in the stream, prefer consolidating into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 0 && bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize dead space that no future item (min size 1..~10) can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // small gap is actually great — nearly perfect fill
    }

    // Last-chance bonus: only this bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 2 {
        score += 3.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize proportionally to wasted gap
            score += 0.3 * post_residual as f64;
        }
    }

    // Time horizon: early in stream, be conservative (prefer spreading);
    // late in stream, prefer filling existing bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - fit_ratio);

    // Global state coupling: many open bins with high mean residual →
    // encourage consolidation into existing bins.
    let consolidation = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln_1p();
    score -= 5.0 * consolidation;

    // Penalize leaving a residual exactly matching a common awkward gap.
    if post_residual == 1 || post_residual == 2 {
        score -= 8.0;
    }

    // Slight preference for bins already partially filled (avoid fragmentation).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 6.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with non-linear polynomial coupling
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Progress-coupled tightness pressure: later in stream, value tight fits more
    let progress_gain = progress * pr * norm_pr * 2.0;
    score -= progress_gain;

    // Dead-space penalty: residuals too small to matter later (non-linear)
    let dead = (norm_pr * (1.0 - norm_pr)).sqrt();
    score += (1.0 - dead) * 10.0 * (1.0 - progress);

    // Lookahead coupling: if next item fits in post-residual, reward strongly (smooth)
    if next_item_size > 0 {
        let fits_next = if (pr - next_item_size as f64) >= 0.0 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs();
        let smooth = fits_next * (1.0 - gap / cap).max(0.0);
        score -= 25.0 * smooth * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only bin that fits
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Mild pressure to consolidate across many open bins
    score += open_bins_count as f64 * 0.5;

    // Mean residual alignment: prefer bins near mean residual (keeps flexibility)
    let dev = (pr - mean_residual).abs() / cap;
    score += dev * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- New-bin candidate handling ---
    let is_new_bin = bin_residual == bin_capacity && post_residual == bin_capacity - item_size;
    if is_new_bin {
        // Opening a new bin wastes all residual of an existing bin.
        // Penalize heavily if any open bin could fit (we prefer re-use).
        if fitting_bins_count > 0 {
            score += 45.0 + 5.0 * (fitting_bins_count as f64);
        }
        // Late in the stream, new bins are even worse (less time to fill them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
        // Small items in a fresh bin are fine (room to combine), big items less so.
        score += 0.25 * (item_size as f64);
        return score;
    }

    // --- Perfect fit reward ---
    if post_residual == 0 {
        score -= 60.0;
    }

    // --- Harmonic class logic on post_residual ---
    // Classify dead space into residue classes mod 10; small odd residues
    // (1..9 not divisible by 10) are hard to reuse -> penalize.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // Tiny dead space: excellent (nearly perfect fit), but odd residues
        // can never be filled by even items... still, tiny is tiny.
        score -= 8.0;
    }
    // Integer-division thresholds: post_residual in "half" bands of capacity
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr <= quarter {
        score -= 12.0; // compact bin, good
    } else if pr <= half {
        score += 0.0; // neutral
    } else {
        // Leaving more than half a bin: wasteful placement.
        score += 0.35 * (pr as f64);
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits exactly in the post-residual: chain placement.
            score -= 15.0;
            if next_item_size == pr {
                score -= 20.0; // perfect chain
            }
        } else {
            // Next item won't fit here; mildly penalize leaving big residue
            // that will strand this bin.
            score += 0.10 * (pr as f64);
        }
    }

    // --- Last-chance bin bonus ---
    if fitting_bins_count == 1 {
        score -= 10.0; // only bin that fits: avoid opening a new bin
    }

    // --- Congestion / fragmentation pressure ---
    // Prefer filling bins when many are open; keep one "flex" bin loose.
    if open_bins_count > 3 {
        score += 0.05 * (post_residual as f64) * ((open_bins_count as f64).ln() + 1.0);
    }

    // --- Mean-residual coupling: prefer bins below mean residual (tighter bins) ---
    score += 0.15 * (mean_residual - post_residual as f64);

    // --- Modulo-5 harmonic class of item size vs residual ---
    // Items whose size mod 5 == residual mod 5 keep "aligned" residues,
    // which historically pair better; slight reward.
    if (item_size % 5) == (bin_residual % 5) {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it is too small to hold even the smallest
    // plausible item (sizes 1..100 => treat gap < 10 as nearly dead).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10.0 - post_residual as f64) * 4.0;
    }

    // Soft penalty for gaps that cannot fit the lookahead item but could
    // otherwise be useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }
    // Reward gaps that can still fit the next item (chaining placements).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferating bins; but allow opening a
    // new bin when existing bins would create dead space.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when mean residual across
    // open bins is large relative to the item (i.e. fits are all poor).
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual - item_size as f64;
        if poor_fit > 0.0 && poor_fit < 20.0 {
            score -= 8.0; // opening fresh bin avoids scattering small gaps
        } else {
            score += 12.0; // default: prefer existing bins
        }
    }

    // Slight preference for tighter existing bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fills: small post_residual is good, but even better if the
    // next item can slot into the leftover space (2-step lookahead matching).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here: reward proportional to how snugly it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 - slack * 0.25;
        } else {
            // Next item does NOT fit here: penalize leaving awkward dead space
            // that is too small for the lookahead item.
            let dead = post_residual as f64;
            if dead < next_item_size as f64 {
                score += dead * 0.35;
            }
        }
    }

    // Prefer bins whose residual deviates below the mean (tight bins first).
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item, use it
    // rather than opening a new bin (avoid fragmenting).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize the brand-new empty bin candidate mildly, unless the item is large
    // and no open bin is a good fit (post_residual would be tiny anyway, so the
    // base score already favors it there).
    if bin_residual == bin_capacity {
        score += 12.0;
        // Allow new bin for large items late in the stream when open bins are fragmented.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size > 50 && mean_residual < item_size as f64 * 0.5 {
            score -= 20.0;
        }
        let _ = progress;
    }

    // Slight preference to keep many bins tight as the stream progresses.
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= 30.0 * (1.0 - gap as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 8.0; // next item won't chain here
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize spreading across many open bins when mean residual is large.
    score += 0.15 * open_bins_count as f64 + 0.05 * mean_residual;

    // Time horizon: later in stream, favor consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large relative to residual
    // of typical open bin, or nothing fits well.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 55.0 - 25.0 * big_item * big_item
            + 0.1 * open_bins_count as f64
            - (if fitting_bins_count == 0 { 15.0 } else { 0.0 });
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 + 3.0 * progress) * 40.0;
    score += coupling;

    // Penalize large post-residual more as stream progresses (less time to reuse space)
    score += progress * pr * pr / cap * 0.5;

    // Reward tight fits (small post_residual) with a smooth cubic term
    score -= (1.0 - norm_pr).powi(3) * 15.0;

    // Last-chance bin bonus: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening new bins unless post_residual would be large
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
        // If next item fits well in the fresh bin, soften penalty
        if next_item_size > 0 && (next_item_size as f64) <= pr {
            score -= 6.0;
        }
    }

    // Lookahead: reward leaving space usable by the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap)).powi(2);
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }

    // Penalize bins far from mean residual (fragmentation smoothing)
    score += ((pr - mean_residual) / cap).abs() * 5.0;

    // Slight preference for fewer open bins early on
    score += (open_bins_count as f64) * (1.0 - progress) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10/25) keep future pairing options alive.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit, always reward
    } else if pr % 50 == 0 {
        -12.0
    } else if pr % 25 == 0 {
        -8.0
    } else if pr % 10 == 0 {
        -5.0
    } else if pr < 10 {
        15.0 // tiny dead space, unusable
    } else {
        0.0
    };
    score += class_bonus;

    // Integer-division threshold: residual bucket by fifths of capacity.
    let fifth = bin_capacity / 5;
    let bucket = pr / fifth;
    score += bucket as f64 * 2.0;

    // Lookahead coupling: does next_item_size fit harmonically into pr?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // next item exactly fills this bin
        } else if next_item_size <= pr {
            let gap = pr - next_item_size;
            if gap % 10 == 0 { score -= 6.0; } else { score += gap as f64 * 0.1; }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad
    // or the stream is early and we want diversity.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 - 10.0 * progress;
        if fitting_bins_count == 0 { score -= 40.0; }
        if item_size >= 50 { score -= 8.0; } // big items deserve fresh bins
    }

    // Congestion: many open bins -> prefer tighter packing (low post_residual).
    if open_bins_count > 8 {
        score += (post_residual as f64) * 0.05;
    }

    // Mean-residual drift: if this bin is far above mean residual, its space
    // is "richer"; slight penalty for wasting it on a poor fit.
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small post_residuals that can never fit
    // future items are punished heavily (nonlinear).
    if post_residual > 0 {
        let gap = post_residual as f64;
        if gap < 10.0 {
            score += 120.0 * (10.0 - gap);
        } else if gap < 20.0 {
            score += 40.0 * (20.0 - gap) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 150.0;
    }

    // Reward tight fits generally: residual fraction consumed.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 4.0 * open_bins_count as f64;

    // If next item fits exactly into post_residual, big reward (chained fit).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 100.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this bin's leftover: penalize wasted space
        score += 15.0;
    }

    // Prefer bins with below-mean residual (keep large residuals for large items).
    if (bin_residual as f64) > mean_residual + 5.0 {
        score += 10.0;
    }

    // New-bin candidate: only attractive when current item is huge or no good fits.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        score += 60.0 - pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual <= 2 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly matches the next item size (chain packing).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 60.0; // perfect chain: item then next item fills bin
        } else if gap <= 3.0 {
            score -= 30.0;
        } else if gap <= 10.0 {
            score -= 12.0;
        } else {
            score += gap * 0.3; // penalize dead space the next item cannot use
        }
        // If next item cannot fit in the post-residual, penalize mildly
        if post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin before opening a new bin: strong incentive to use it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New empty bin candidate: penalize so it is only chosen when no
    // reasonable open-bin fit exists.
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if the item is large, a fresh bin is more attractive
        score -= item_size as f64 * 0.2;
        // early in stream, opening new bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 15.0;
    }

    // Slight preference for filling tighter bins generally
    score += (bin_capacity as f64 - bin_residual as f64) * -0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (post_residual small relative to item).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 6.0;
        }
        // Bonus if post-residual + next item leaves a near-perfect chain fit.
        let chain = post_residual as f64 - next_item_size as f64;
        if chain >= 0.0 && chain < 8.0 {
            score -= 8.0;
        }
    }

    // Time horizon: early in stream, prefer consolidating into few bins;
    // later, tolerate opening new bins to keep residuals balanced.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (bin_residual as f64 - mean_residual).abs() / 100.0;

    // Prefer bins with residuals above the mean (balance across bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let open_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let bad_open = open_bins_count as f64 * 0.5;
        score += 45.0 - 40.0 * open_pressure + bad_open * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild penalty for very large items going into large-residual bins.
    if item_size >= 70 && bin_residual >= 90 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fills (low post residual).
    let mut score = post;

    // Non-linear coupling: post residual weighted by progress^2 (late stream => tighter packing).
    let tightness = post / cap;
    score += 12.0 * tightness * tightness * (progress * progress);

    // Reward near-perfect fits smoothly (bell-shaped dip around small post_residual).
    let fit_bonus = (-tightness * tightness * 40.0).exp();
    score -= 15.0 * fit_bonus;

    // Lookahead: penalize if post residual can't fit next item but could almost.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Reward residual that accommodates the next item (chaining placements).
            let slack = (post - nxt) / cap;
            score -= 8.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            // Dead space: unusable for next item; penalize proportionally to waste.
            let waste = post / cap;
            score += 10.0 * waste * waste * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    score -= 2.0 * open_pressure * (1.0 - tightness);

    // Mean residual coupling: prefer bins below mean residual (tighter than average).
    score += 0.15 * (mean_residual - post).abs().signum() * (mean_residual - post);

    // New-bin candidate: make empty bin slightly unattractive unless residuals are all bad.
    if bin_residual == bin_capacity {
        score += 6.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (small dead space).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Harmonic class logic: residual classes via integer division thresholds.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect closure
    } else if pr < 10 {
        score -= 15.0; // nearly closed, small dead space
    } else {
        // Penalize residuals that cannot host a typical next item.
        if next_item_size > 0 {
            if next_item_size > pr {
                score += 25.0; // next item cannot fit here anyway
            } else {
                // Reward residuals that are exact multiples of the next item size
                if pr % next_item_size == 0 {
                    score -= 20.0;
                }
                // Reward if next item fits with a tiny remainder (harmonic pair)
                let rem = pr % next_item_size;
                if rem > 0 && rem < 10 {
                    score -= 10.0;
                }
            }
        }
        // Modulo-class penalty on awkward residual bands (dead-space zones)
        let class = pr / 10; // integer division threshold classes
        match class {
            1 => score += 8.0,   // 10..19 residual: hard to fill
            2 => score += 4.0,   // 20..29
            3 => score -= 2.0,   // 30..39 decent
            5 => score -= 4.0,   // 50..59 good target zone
            6 => score -= 6.0,   // 60..69
            _ => {}
        }
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_score = 55.0
            - 45.0 * pressure
            - 25.0 * progress
            - (open_bins_count as f64).sqrt() * 2.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            new_bin_score -= 10.0;
        }
        score = score.min(new_bin_score);
    } else {
        // Mild penalty for spreading across many bins when mean residual is high.
        score += (open_bins_count as f64) * 0.5 * (mean_residual / bin_capacity as f64);
    }

    // Small lookahead coupling: if next item exactly fits current post-residual, big reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 35.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead space penalty: residuals that are too small to hold any plausible
    // future item (min size 1, but practically small gaps are wasted) are
    // heavily penalized, super-linearly.
    if post_residual > 0 {
        let pr = post_residual as f64;
        if post_residual < 10 {
            // unusable micro-gap
            score += 60.0 * (10.0 - pr) / 10.0;
        } else if post_residual < 25 {
            // hard-to-fill small gap
            score += 25.0 * (25.0 - pr) / 15.0;
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating into fewer bins when many are open.
    score += (open_bins_count as f64) * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 12.0;
        }
        // penalize if next item won't fit here anyway (dead space likely)
        if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Deviation from mean residual: bins far tighter than average are good targets.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Slight early-stream preference to open bins when few exist (spread risk).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when no good fit exists.
        score += 45.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match for the next item is heavily rewarded.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);
        // Exact match: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If the next item cannot fit here, penalize leaving a large gap.
        if next_item_size > post_residual {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fill.
        score += 10.0;
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1, but
    // typical items are larger); compare against mean residual of open bins.
    if (post_residual as f64) < mean_residual * 0.5 {
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Mild preference to fill existing bins rather than opening new ones when
    // many bins are already open.
    score -= 0.15 * open_bins_count as f64;

    // Slight phase awareness: early in the stream, be more willing to open new bins
    // (keep flexibility); later, consolidate tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin gets a baseline that makes it attractive only
    // when it would otherwise be a poor fit decision.
    if bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space that no
    // future item can use is wasted. Penalize residual in the "unusable" band.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let dead_zone_lo = 1.0;
    let dead_zone_hi = 10.0;
    if (post_residual as f64) > dead_zone_lo && (post_residual as f64) < dead_zone_hi {
        score += 15.0 * (1.0 - t);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item does NOT fit into this bin's post residual, mild penalty
    // (we may strand the next item), stronger when few bins can fit current item.
    if next_item_size > post_residual {
        score += 8.0 + 10.0 * (1.0 - t);
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Many alternatives: slight penalty for consuming a scarce small residual
        score += 3.0 * (fitting_bins_count.min(10) as f64) * (post_residual as f64) / bin_capacity as f64;
    }

    // Prefer bins with below-average residual (keep big holes for big items).
    score += 0.5 * ((bin_residual as f64) - mean_residual).max(0.0);

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item is large relative to capacity or current fit is poor.
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        let poor_fit = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 20.0 - 30.0 * large_item - 25.0 * poor_fit;
        // Late in the stream, opening new bins is less costly than fragmentation.
        score -= 10.0 * t;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling: quadratic decay of residual value over stream progress
    score -= 40.0 * (1.0 - progress) * (1.0 - norm_pr) * (1.0 - norm_pr);
    // penalize tiny dead space more as stream progresses
    let tiny = (norm_pr * (1.0 - norm_pr) * 4.0).min(1.0);
    score += 25.0 * progress * (1.0 - tiny);
    // lookahead: reward residual that can host the next item smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let slack = (pr - ns) / cap;
        if slack >= 0.0 {
            score -= 15.0 * (slack * slack + 0.5 * slack);
        } else {
            score += 12.0 * (-slack / cap);
        }
    }
    // last-chance bonus
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - norm_pr);
    }
    // smooth pressure term from mean residual and open bins
    let pressure = (mean_residual / cap - 0.5).tanh();
    score += 8.0 * pressure * (open_bins_count as f64).ln_1p();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls in "dead zones"
    // (residuals that few item sizes can still use) are penalized.
    let pr = post_residual;
    if pr > 0 {
        // Dead-space classes: leftover in (0..10) is nearly unusable (min item 1 though,
        // but small leftovers waste capacity fractionally).
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 12.0;
        }
        // Harmonic division thresholds: leftover exactly divisible by common item
        // classes (10/20/25/50) is "harmonic" and reusable.
        let harmonic = (pr % 10 == 0) as f64 * 6.0
            + (pr % 20 == 0) as f64 * 4.0
            + (pr % 25 == 0) as f64 * 3.0
            + (pr % 50 == 0) as f64 * 3.0;
        score -= harmonic;
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            // Next item fits: leftover after that matters via harmonic class.
            let npr = pr - next_item_size;
            score -= 10.0 - (npr as f64) * 0.1;
            if npr % 10 == 0 && npr > 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this bin's leftover: mild penalty, worse if leftover small.
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress and congestion.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.55 + progress * 10.0 + (open_bins_count as f64) * 0.5;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size >= 60 {
            score -= 12.0;
        }
        // If many bins fit the item already, opening new is unattractive (handled by
        // open bins getting low scores); if only one fits, new-bin cost stays high.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
    }

    // Tie-break toward fuller bins (smaller residual) and against spreading load.
    score += (mean_residual - bin_residual as f64) * 0.15;
    score += (open_bins_count as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest possible item are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 50.0; // perfect fit
    } else if post_residual <= 12 {
        score += 40.0; // tiny unusable gap: heavily penalize
    } else if post_residual <= 25 {
        score += 12.0; // poor residual
    } else if post_residual <= 45 {
        score -= 2.0; // decent residual
    } else {
        score -= 8.0; // large residual keeps bin flexible
    }

    // Reward tight fits (waste ratio relative to bin).
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 15.0 * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing ones,
    // penalize opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if item is large and residuals elsewhere are small.
        score += 10.0 + 8.0 * pressure - 20.0 * tightness - 5.0 * (mean_residual / bin_capacity as f64);
    } else {
        score -= 4.0 * pressure * (1.0 - 0.5 * progress);
    }

    // Lookahead: if the next item fits exactly into the post residual, reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 10.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual <= 10 {
            score += 10.0; // blocks the next item in this bin
        }
    }

    // Mild preference for fuller bins when residuals across bins are large.
    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward perfect chaining of next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward when next item exactly fills the bin after this placement.
        score -= 30.0 * (1.0 - diff / (bin_capacity as f64));
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a gap that neither the next item nor anything typical fits.
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 0.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only bin that can fit, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting space in a fresh bin when other bins exist (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 12.0 + 2.0 * open_bins_count as f64;
        // But opening a new bin is fine if the item is large relative to capacity.
        score -= 0.15 * item_size as f64;
    }

    // Prefer tight fits overall.
    score += 0.3 * post_residual as f64 * (post_residual as f64 / bin_capacity as f64);

    // Slight progression bias: early on, be more willing to open bins / spread load.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize new empty bins unless nothing fits well (avoid bin proliferation).
    if bin_residual == bin_capacity {
        score += 25.0 + (open_bins_count as f64).sqrt() * 5.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 8.0;
        } else {
            // Dead space: penalize residuals too small for typical next items.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Global pressure: many open bins relative to progress -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count as f64 > 3.0 + progress * 10.0 {
        score -= 6.0;
    }

    // Deviation from mean residual: prefer bins with residual close to (but >=) item need.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Discourage leaving large residuals late in the stream (less chance to reuse).
    if progress > 0.7 && post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = x * (1.0 - x) * 4.0; // parabola peaking at x=0.5
    score = score * (1.0 + progress);
    score += x * x * 30.0; // strong penalty for large dead space

    // Smooth coupling: exact fit reward amplified later in the stream.
    let fit = (1.0 - x).powi(3);
    score -= fit * (10.0 + 40.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 25.0 * progress;
    }

    // Prefer bins below mean residual (tighter bins) with smooth term.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Lookahead: reward if next item could use the post residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += (gap / cap) * 12.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many open bins early on.
    score += open_bins_count as f64 * 0.05 * (1.0 - progress);

    // New-bin candidate: make empty bin moderately attractive only for large items
    // or when the item leaves a very small residual elsewhere.
    if bin_residual == bin_capacity {
        let tightness = 1.0 - x; // item fills much of the new bin
        score = 60.0 - tightness * 45.0 * (0.5 + 0.5 * progress);
        if fitting_bins_count == 1 {
            score += 30.0; // discourage opening a new bin when an existing bin is a last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 (dead-space classes)
    let r = post_residual % 10;
    // Penalize "awkward" residues that few item sizes can fill (items 1..100, but
    // small residues are hardest to reuse). Reward exact fits.
    let awkward: f64 = match r {
        0 => -12.0,               // perfectly harmonic residual
        1 | 2 => 14.0,            // nearly impossible to fill
        3 | 4 | 6 | 7 => 6.0,     // moderately awkward
        5 => 2.0,                 // only 5s fill it
        8 | 9 => 3.0,             // 10-class reachable via 1..2 top-up
        _ => 0.0,
    };
    score += awkward;

    // Integer-division threshold classes on post_residual
    if post_residual == 0 {
        score -= 30.0; // perfect packing
    } else if post_residual <= 10 {
        score += 4.0; // small but fillable
    } else if post_residual > bin_capacity / 2 {
        score += 10.0; // half-empty bin: wasteful placement
    }

    // Capacity fraction coupling: fraction of bin consumed by this item
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_frac; // favor placing large items into good bins

    // Lookahead harmonic class: does next_item_size fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use this residual; penalize by leftover class
            let gap = next_item_size - post_residual;
            score += (gap % 10) as f64 * 0.8 + 2.0;
        }
    }

    // Last-chance bin before opening a new bin: strong reward
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when mean residual across open bins is small
    if bin_residual == bin_capacity {
        let mean_frac = mean_residual / bin_capacity as f64;
        score = 60.0 - 50.0 * mean_frac; // open new bin only if open bins are nearly full
        if next_item_size > 0 && next_item_size >= bin_residual {
            score += 5.0;
        }
    }

    // Stream progression: late in stream, be greedier about exact fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Mild tie-break: prefer fewer open bins competing
    score += (open_bins_count as f64).ln() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 12.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can fit into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item is close but leaves another tiny gap.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score -= (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact match with the next item (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: next item fills this bin exactly
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Dead space relative to next item: penalize more as gap grows.
            score += 0.35 * gap;
        }
    } else {
        // Last item: prefer tightest fit overall.
        score += 10.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Reward leaving small unusable residue only when it's tiny (waste minimization).
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    // Penalize creating dead space far below the minimum item size (unusable gap).
    if post_residual > 0 && post_residual < 10 && next_item_size > post_residual {
        score += 5.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Contextual coupling with mean residual: prefer bins tighter than average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Prefer fuller bins early in the stream; allow spreading later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for reusing existing bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 12.0; // new-bin candidate penalty
    } else {
        score -= 3.0;
    }

    // Very full bins get a small extra reward (compactness).
    if post_residual == 0 {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space: residual too small to be useful for typical items
    let min_useful = 10.0;
    if (post_residual as f64) < min_useful && post_residual > 0 {
        score += 30.0;
    }

    // Last-chance bin bonus: avoid opening a new bin when only one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect chain: item + next item exactly fill the bin
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // New-bin candidate handling: mildly penalize opening new bins early,
    // but allow it when open bins are all crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        score += 18.0 - 30.0 * crowding - 10.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 15.0; // fresh bin guarantees a fit for next item
        }
    }

    // Global balance: prefer bins whose residual is close to the mean (avoid fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Slight preference for using more-open-bins states to consolidate
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer low post-residual, with smooth polynomial coupling to progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Non-linear dead-space penalty: penalize residuals too small to be useful later
    let dead = (1.0 - norm_pr).powi(3) * (1.0 - norm_pr).powi(3);
    score += 12.0 * dead * (0.5 + progress);

    // Tight-fit reward: smooth coupling of small post-residual with item size
    let tight = 1.0 - (norm_pr * std::f64::consts::PI / 2.0).cos();
    score -= 6.0 * tight * (item_size as f64 / cap);

    // Lookahead: reward if next item fits in post-residual (smooth soft-fit)
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64 / cap;
        score += 4.0 * (1.0 - (-gap * 3.0).exp()) - 3.0 * (-gap * gap * 8.0).exp();
    }

    // Last-chance bonus: strongly favor using a scarce fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    } else {
        // mild dispersion penalty when many bins fit the item
        score += 1.5 * ((fitting_bins_count as f64).ln().max(0.0)) * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins deviating from the mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 3.0 * dev * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless it is genuinely attractive
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: capacity split into 4 quantum bands
    let q = bin_capacity / 4; // 25
    let band = post_residual / q; // 0..4

    // Reward small-but-usable leftovers (band 0/1 = tight fills), penalize mid gaps
    match band {
        0 => score -= 18.0,
        1 => score -= 6.0,
        2 => score += 8.0,
        _ => {}
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 30.0;
    }

    // Harmonic pairing: leftover matches next item (or its complement class)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 22.0;
        } else if next_item_size <= post_residual {
            // next item fits: bonus scaled by how snugly
            let snug = (post_residual - next_item_size) as f64;
            score -= 12.0 - snug * 0.15;
        } else {
            // next item won't fit here: penalize leftovers below smallest class
            if post_residual < next_item_size {
                score += 4.0;
            }
        }
        // modulo coupling: leftover and next item in same residue class mod 10
        if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
            score -= 3.0;
        }
    } else {
        // last item: strongly prefer tightest fill
        score -= 10.0;
    }

    // Last-chance bin: this is the only bin that fits -> strong reward
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins could absorb the item
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            // new bin competes with existing fits: penalize unless existing fits are bad
            let bad_fits = mean_residual < item_size as f64 * 1.2;
            if !bad_fits {
                score += 15.0;
            } else {
                score -= 5.0;
            }
        }
        // early stream: encourage a few bins to stay open for future pairing
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 && open_bins_count < 3 {
            score += 10.0;
        }
    }

    // Mild penalty for leaving residue in awkward harmonic classes (odd residues mod 5)
    if post_residual % 5 != 0 && post_residual > 0 {
        score += 2.0;
    }

    // Prefer bins below mean residual (filling emptier bins first balances classes)
    if (bin_residual as f64) > mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 60.0; // tiny useless gap
    } else if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr >= 10 && pr <= 20 {
        score -= 5.0; // still usable by min-size items
    } else if pr > 50 {
        score += 10.0; // wasteful large leftover
    }

    // Reward tight fits relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Pressure from number of open bins: discourage opening new bins
    // when many bins are already open, encourage consolidation.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 4.0 * open_bins_count as f64;
        // But if this bin is the last chance and fit is decent, allow it.
        if fitting_bins_count == 1 && post_residual <= 30 {
            score -= 20.0;
        }
        // Lookahead: if next item is large, a fresh bin is attractive.
        if next_item_size >= 50 {
            score -= 12.0;
        }
    } else {
        // Reward using existing bins, especially when few fit.
        if fitting_bins_count == 1 {
            score -= 30.0; // last chance: strongly prefer this bin
        }
        // Lookahead synergy: if next item fits the post residual, bonus.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 15.0;
        }
        // If next item won't fit anywhere after this placement, penalize
        // leaving a residual that strands it.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 20.0;
        }
    }

    // Mild consolidation pressure via mean residual deviation.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let look = next_item_size as f64;
        let gap = (post_residual as f64 - look).abs();
        // Perfect 2-step fit bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Proximity bonus: tighter match to next item => better
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);
        // Penalize residuals slightly below next item (dead space unusable by next item)
        if (post_residual as f64) < look {
            score += 0.5 * (look - post_residual as f64);
        }
        // Penalize large residual that next item cannot meaningfully use
        if post_residual as f64 > look * 2.0 {
            score += 0.2 * (post_residual as f64 - look * 2.0);
        }
    } else {
        // Last item: just minimize leftover
        score += 0.5 * post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins tighter than average
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny unusable dead space (fragmentation)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in stream: tighten packing, discourage opening new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early, penalized later
        score += 10.0 + 40.0 * progress;
        // But allow new bin if no existing bin gives a good 2-step fit
        if next_item_size > 0 && post_residual == bin_capacity && (bin_capacity as f64 - next_item_size as f64).abs() < 5.0 {
            score -= 20.0;
        }
    } else {
        score -= 5.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across too many bins
    score += 0.1 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward filling bins snugly (small post_residual).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize dead space that nothing can use (items >= 10, or next item).
    let min_item = if next_item_size > 0 { next_item_size.min(10) } else { 10 };
    if post_residual > 0 && (post_residual as u32) < min_item {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Bin becomes useless for the known next item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer the tightest; add mild diversity penalty.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // open bins are crowded or the item is large relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = mean_residual / bin_capacity as f64;
        // Penalize new bins generally, less so late in the stream or when
        // existing residuals are tight.
        let penalty = 35.0 - 10.0 * progress - 20.0 * (1.0 - crowded);
        score += penalty.max(5.0);
        // Large items open bins more readily.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Global state coupling: when mean residual is high, prefer using
    // large-residual bins (spread waste); when low, prefer tight bins.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Prefer reusing bins over proliferating open bins slightly.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual and its smooth polynomial couplings with progress
    let prn = pr / cap;                       // in [0, 1)
    let pr2 = prn * prn;
    let pr3 = pr2 * prn;

    // Base: prefer low post-residual, with progress-dependent curvature.
    // Early stream: linear-ish penalty; late stream: strongly punish mid-size gaps
    // (dead space) via convex quadratic, reward near-perfect fits via cubic drop.
    let mut score = pr * (0.6 + 0.8 * progress)
                  - 30.0 * pr2 * (0.5 + progress)
                  + 25.0 * pr3 * (1.0 - progress);

    // Smooth interaction: penalty grows quadratically with progress for wasted space
    score += 10.0 * pr2 * pr2 * progress;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving room for the next item (smooth Gaussian-like affinity)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (pr - nxt).abs();
        let aff = (-(slack * slack) / (2.0 * 400.0)).exp(); // sigma = 20
        score -= 12.0 * aff * (0.5 + progress);
    }

    // Penalize opening a new bin when the item fits elsewhere, unless residuals
    // across open bins are already tight (smooth tradeoff via mean_residual).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        let tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 * (1.0 - tightness * tightness) + 8.0 * progress;
    } else {
        // Reward bins whose residual is far from mean (diversity of sizes)
        let dev = (bin_residual as f64 - mean_residual) / cap;
        score -= 6.0 * dev * dev;
    }

    // Mild penalty on bin count pressure, smoothed
    score += 0.15 * (open_bins_count as f64).ln().max(0.0) * (0.5 + 0.5 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual is "usable"
    // (divisible into common small-item chunks) are rewarded.
    let r = post_residual;
    let class: f64 = if r == 0 {
        -30.0 // perfect fit: ideal closure
    } else if r % 10 == 0 {
        -12.0 // decile-aligned residual, highly reusable
    } else if r % 5 == 0 {
        -6.0
    } else if r <= 10 {
        8.0 // tiny dead space
    } else {
        0.0
    };
    score += class;

    // Integer-division threshold: residual large enough for a mid item (>= 20)
    // is worth more; small residuals are dead space.
    let usable_chunks = r / 20;
    score -= usable_chunks as f64 * 4.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this bin (chained packing).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size < r {
            let next_post = r - next_item_size;
            if next_post % 10 == 0 {
                score -= 10.0;
            } else if next_post <= 10 {
                score += 6.0; // next item would leave dead space
            }
        } else {
            // next item cannot follow here; slight penalty proportional to gap
            score += ((next_item_size - r) as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // and current bins are fragmented (mean residual small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        let mut new_bin_score = 20.0 + item_size as f64 * 0.3;
        if item_size >= 70 && fragmentation < 0.25 {
            new_bin_score -= 30.0; // big item, fragmented bins -> fresh bin ok
        }
        if progress > 0.9 {
            new_bin_score += 10.0; // late stream: consolidate
        }
        score += new_bin_score;
    }

    // Prefer tighter bins among open ones (best-fit bias).
    score += (bin_residual as f64) * 0.05;

    // Mild reward when many bins are open: keep them consolidated.
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps below the minimum item size are permanently unusable: penalize hard.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    } else if post_residual <= 3 {
        // Near-perfect fit, effectively dead space but tiny: mild reward.
        score -= 15.0;
    }

    // Smooth tightness reward: tighter fit is better, superlinear.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 10.0;

    // --- Lookahead coupling ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin can still host the next item: reward exact future fit.
            let future_gap = post_residual - next_item_size;
            score -= 8.0;
            if future_gap < 10 {
                score -= 10.0; // next item then fills bin perfectly
            }
        } else if post_residual > 0 {
            // Residual too small for next item: dead space for the future.
            score += 6.0;
        }
    }

    // --- Open-bin pressure ---
    // When many bins are open, prefer consolidating (avoid spreading).
    let pressure = open_bins_count as f64;
    score += pressure * 0.8;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Mean-residual anchoring: bins far below mean residual are "wasted" bins;
    // filling them is cheap, filling near-full bins is precious.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Stream progression: early on be more open to new bins (exploration),
    // late in the stream be frugal with open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 5.0;

    // New-bin candidate: empty bin should only win if current bin fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0 + pressure * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: strongly reward leaving nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            // reward chains that keep the next item placeable
            score -= (post_residual - next_item_size) as f64 * 0.25;
        } else {
            // next item cannot fit: penalize dead space scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Prefer bins whose residual is below mean (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // opening a fresh bin still allows a good next placement
            score -= 10.0;
        }
        // if few fitting bins and they are tight, new bin is attractive
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
    }

    // Mild preference for filling larger-capacity bins early in stream.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit a typical future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual >= 10 {
        let usable = post_residual as f64 / cap;
        score -= 6.0 * usable;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; mild penalty proportional to overflow gap
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Prefer bins whose residual is below mean (tighter bins get priority).
    score += 2.0 * (bin_residual as f64 - mean_residual).max(-cap) / cap;

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when open bins exist; allow it late or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count == 0 { 0.0 }
            else { mean_residual / cap };
        score += 40.0 * (1.0 - progress) * (1.0 - open_pressure) + 5.0;
        if open_bins_count == 0 {
            score -= 100.0; // must use a bin
        }
    }

    // Slight preference for filling bins that are already well-loaded.
    score -= 4.0 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = (1.0 - t) * (pr * pr) / cap + t * (fit * fit) * cap;
    score += 0.15 * poly;

    // Reward tight fits (small post_residual) with smooth decay.
    score -= 12.0 * (1.0 - fit).powi(3);

    // Penalize dead space that cannot fit the next item, smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).max(0.0);
        score += 0.25 * (gap * gap) / cap;
        if pr >= nx {
            score -= 4.0;
        }
    }

    // Last-chance bin bonus: smooth reward scaled by scarcity of fitting bins.
    if fitting_bins_count <= 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Mild pressure toward consolidation with open-bin count.
    score += 0.05 * open_bins_count as f64 * fit;

    // New-bin candidate: prefer only when item is large and fits are scarce.
    if bin_residual == bin_capacity {
        score += 10.0 - 0.1 * item_size as f64 + 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via squared post-residual pressure
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score += (pr * pr) / cap * 0.5;

    // Harmonic class of the leftover space: modulo classes on post_residual
    // Leftovers divisible by 10 are "harmonic" (many item sizes 1..100 can pair into them)
    let harmonic_class = post_residual % 10;
    match harmonic_class {
        0 => score -= 8.0,          // perfectly harmonic leftover
        5 => score -= 3.0,          // half-harmonic
        1 | 9 => score += 4.0,      // worst classes: nearly nothing or odd slivers
        2 | 8 => score += 2.5,
        3 | 7 => score += 1.5,
        _ => score += 1.0,
    }

    // Dead-space penalty: leftover too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead coupling: does the leftover's harmonic class match the next item?
    if next_item_size > 0 {
        let n = next_item_size;
        if post_residual == n {
            score -= 15.0; // exact chain fit
        } else if post_residual >= n {
            let slack = post_residual - n;
            // Reward when the remainder after next item is again harmonic
            if slack % 10 == 0 {
                score -= 6.0;
            } else if slack % 5 == 0 {
                score -= 3.0;
            }
            if slack < 10 && slack > 0 {
                score += 5.0; // would create a dead sliver after next item
            }
        } else {
            score += 6.0; // next item cannot use this bin's leftover
        }
    }

    // Integer-division thresholds: treat post_residual in capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 4.0; // keep bins with lots of room attractive
    } else if post_residual >= quarter {
        score -= 1.0;
    } else if post_residual > 0 {
        score += 3.0; // small fragments are low value
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no
    // open bin offers a decent fit (residual far from capacity means real bin).
    if bin_residual == bin_capacity {
        // Base cost of opening a fresh bin
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= cap * 0.5; // no alternative: must open
        } else {
            // If existing bins would leave very poor fits, allow opening
            if mean_residual < cap * 0.25 && open_bins_count > 0 {
                score -= cap * 0.45;
            }
            // Late in the stream, avoid bin proliferation
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 10.0;
        }
        // Big next item favors a fresh bin
        if next_item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild pressure to consolidate across many open bins
    score += open_bins_count as f64 * 0.05;
    score -= mean_residual * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are unusable.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // tiny dead space is nearly worthless
        } else if post_residual < 20 {
            score += 18.0;
        } else if post_residual < 35 {
            score += 6.0;
        } else {
            score -= 8.0; // large residual keeps flexibility
        }
    } else {
        score -= 30.0; // perfect fill is ideal
    }

    // Reward bins that can also host the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 10.0; // would strand the next item
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: more open bins -> favor consolidating into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when existing residuals are badly fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if mean_residual < 25.0 && post_residual == bin_capacity {
            score -= 20.0; // open bins nearly full: new bin is right
        } else {
            score += 15.0 + fragmentation * 0.3;
        }
    }

    // Mild stream-progression term: tighten packing as the stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // If next item can still fit in the leftover space, reward proportionally
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 * (next_item_size as f64 / (post_residual as f64).max(1.0));
    }

    // Penalize dead space that cannot host the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Favor bins tighter than the mean residual (good fit relative to fleet)
    score -= 10.0 * ((mean_residual - post_residual as f64) / bin_capacity as f64);

    // New empty bin: penalize unless it's a genuinely better long-term option
    if bin_residual == bin_capacity {
        score += 30.0;
        // Opening a new bin is more acceptable early in the stream
        score -= 20.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer filling bins with small residuals fully (near-perfect packing)
    if post_residual <= 5 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large post-residual relative to capacity (dead space)
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powf(1.7) * bin_capacity as f64;

    // Reward tight fits (small post-residual)
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 12 {
        score -= 10.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.25 * (next_item_size as f64);
            // bonus if next item fits almost exactly
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 6.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // post-residual too small for next item: penalize wasted space
            score += 5.0 * (1.0 - (post_residual as f64 / next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Crowding: when many bins are open, prefer consolidation (lower mean residual bins)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 2 {
        let dev = mean_residual - bin_residual as f64;
        score += 0.12 * dev * (open_bins_count as f64).ln();
    }

    // Late in stream: prefer filling existing bins tightly rather than opening new ones
    if progress > 0.6 {
        score -= 6.0 * progress;
    }

    // Mild penalty for near-empty bins being consumed by small items
    if bin_residual > 80 && item_size < 40 {
        score += 7.0;
    }

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 30.0;
        } else {
            // discourage opening new bin when alternatives exist
            score += 15.0 + 2.0 * open_bins_count as f64;
            if next_item_size > 0 && post_residual >= next_item_size {
                score -= 5.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post residual), with non-linear sharpening
    let mut score = pr * (1.0 + 1.5 * norm_pr * norm_pr);

    // Polynomial coupling with stream progress: early on, tolerate slack;
    // later, punish residual space more strongly (quadratic ramp)
    let progress_coupling = 1.0 + 2.0 * progress * progress;
    score *= progress_coupling;

    // Reward filling bins down toward zero residual (smooth bowl)
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Penalize dead space that is too small for typical future items
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (10.0 - pr) / 10.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: if next item fits into post residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (nxt / cap) * (1.0 - norm_pr);
        } else {
            // waste penalty proportional to overshoot
            score += 8.0 * ((nxt - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins vs consolidating
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Deviation from mean residual: prefer bins whose residual is near/below mean
    let dev = (pr as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev - 5.0 * dev;

    // New-bin candidate: penalize opening a fresh bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress + 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space?
    // Class 0: post_residual in {0} -> perfect closure, reward heavily.
    // Class 1: post_residual divisible by small harmonics (5,10) -> still reusable.
    // Class 2: awkward odd remainders -> penalize.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0;
    } else if pr <= 10 {
        // tiny dead space is bad unless it exactly closes the bin
        score += 12.0;
    } else if pr % 10 == 0 {
        score -= 8.0; // harmonic with capacity decade: highly reusable
    } else if pr % 5 == 0 {
        score -= 4.0;
    } else {
        score += 3.0; // non-harmonic leftover
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here: strong reward, scaled by how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 15.0 - snug.min(15.0) * 0.3;
            // harmonic bonus if next item exactly matches a divisor class
            if pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else if next_item_size <= bin_residual {
            // next item could fit this bin only if we DON'T place here... neutral
            score += 2.0;
        } else {
            // next item needs a fresh bin anyway; prefer consolidating now
            score -= 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin when decent open bins exist,
    // unless the current item is huge and open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 25.0
            - 15.0 * progress
            - (open_bins_count as f64).min(10.0)
            - if item_size > bin_capacity / 2 { 10.0 } else { 0.0 }
            - if fragmentation > 30.0 { 8.0 } else { 0.0 };
    } else {
        // mild preference for filling existing bins as stream matures
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * progress;
    }

    // Prefer bins whose residual is closest to mean (balance pressure),
    // with harmonic modulation on integer division of residual by item class.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Integer-division threshold: bins where item_size divides residual evenly
    if item_size > 0 && bin_residual % item_size == 0 && bin_residual != bin_capacity {
        score -= 7.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (min item size 1..100 unknown, so treat very small gaps
    // relative to typical sizes) are heavily penalized.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // unusable sliver
    } else if (post_residual as f64) < 25.0 {
        score += 20.0; // risky small gap
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Coupling: dead space penalty scales with how many bins are open
    // (more open bins -> more pressure to keep gaps usable).
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if (post_residual as f64) < dead_threshold {
        score += 15.0 * open_pressure;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 45.0;
        } else {
            score -= 8.0;
        }
    }
    // If next item cannot fit in post_residual, the gap is likely dead space.
    if next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current gaps are bad.
    if bin_residual == bin_capacity {
        score += 35.0 + 10.0 * open_pressure;
        if fitting_bins_count == 1 {
            score += 60.0; // never open a new bin when it's the only fit
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (balanced packing), mildly.
    score += ((post_residual as f64) - mean_residual).abs() * 0.15;

    // Progression: as stream advances, be more conservative about new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Near match: small gap between post_residual and next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 15.0 / (1.0 + gap);
        // Post residual smaller than next item => dead space unless tiny.
        if (post_residual as i64) < (next_item_size as i64) {
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        }
    }

    // Penalize large leftover relative to mean residual (wasteful fit).
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if post_residual as f64 > mean_r {
        score += (post_residual as f64 - mean_r) * 0.25;
    } else {
        score -= (mean_r - post_residual as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Late in the stream, consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 8.0;

    // New empty bin candidate: acceptable only if it promises a big useful
    // container; otherwise discourage spreading across bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Reward exact/very tight fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Dead-space penalty: residual left that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: strongly prefer filling existing bins to the max.
        score -= 20.0 * fit_ratio;
    }

    // Last-chance bonus: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize wasting space in bins whose residual is far above the mean
    // (keep flexible large-residual bins open for future items).
    let mean_gap = mean_residual - bin_residual as f64;
    if mean_gap > 0.0 {
        score += 0.15 * mean_gap;
    }

    // Late in the stream, consolidate aggressively into fewer bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage opening new bins / spreading out.
    score += 0.6 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    // New-bin candidate: make it less attractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 22.0 + 0.3 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.35 * progress * (1.0 - progress) * 4.0);

    // Smooth quadratic penalty on dead space (small post_residual is good, but
    // extremely small post_residual wastes almost nothing -> mild reward curve)
    score += 12.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits with smooth non-linear term
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * norm_item;

    // Lookahead coupling: penalize if post_residual is too small for next item
    // (smooth sigmoid-like interaction instead of hard threshold)
    if next_item_size > 0 {
        let fits_next = norm_pr - norm_next;
        let smooth = 1.0 / (1.0 + (-fits_next * 20.0).exp());
        score -= 6.0 * smooth * norm_next * (1.0 - progress * 0.5);
        score += 4.0 * (1.0 - smooth) * norm_next * progress;
    }

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - 0.5 * progress);
    }

    // Deter new-bin opening when plenty of fitting bins exist (smooth coupling)
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (10.0 + 8.0 * (1.0 - progress)) * (1.0 - 1.0 / (1.0 + (fitting_bins_count as f64).powi(2)));

    // Mean residual interaction: prefer bins deviating from mean to balance residuals
    score += 0.05 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues in the "dead zone" (< 10) are wasted space.
    let dead = (post_residual < 10) as i32 as f64;
    score -= dead * 6.0; // a closed-perfect bin is excellent

    // Modulo-class penalty: residual classes mod 10 that are hard to fill later
    let class = post_residual % 10;
    let hard_class = ((class == 1) || (class == 2) || (class == 9)) as i32 as f64;
    score += hard_class * 3.0;

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits: reward proportionally to how well it uses the residual
            let usage = next_item_size as f64 / post_residual as f64;
            score -= 2.0 + 4.0 * usage;
        } else {
            // next item cannot fit here: penalize leaving this residual stranded
            score += 1.5;
        }
        // Harmonic pairing: post_residual and next_item_size in same decade class
        if post_residual / 10 == next_item_size / 10 && post_residual >= next_item_size {
            score -= 2.5;
        }
    }

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    if bin_residual == bin_capacity {
        let large = (item_size >= 50) as i32 as f64;
        score += 10.0 - 6.0 * large;
    }

    // Mild preference for bins below mean residual (keeps balance)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // Late-stream consolidation: fewer open bins preferred as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest plausible item (say 10)
    // or smaller than the lookahead item when that item could otherwise fit well.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold && post_residual > 0 {
        score += 60.0; // completely wasted sliver
    }

    // Penalize gaps that can't fit the next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving a gap that exactly or nearly fits the next item.
        let gap_slack = (post_residual - next_item_size) as f64;
        score -= 15.0 * (1.0 - gap_slack / 50.0).max(0.0);
    }

    // Reward tight fits generally.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else {
        // Multiple candidates: mild pressure to spread load when many bins are open.
        score += 0.3 * open_bins_count as f64;
    }

    // Open-bin pressure: discourage opening new bins when existing residual capacity
    // is ample on average.
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if mean residual of open bins is small.
        score += 15.0 + mean_residual * 0.4;
        // Early in the stream, opening bins is cheap; later it is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // Placing into an existing bin reduces pressure; reward slightly more
        // when mean residual is high (we are consolidating).
        score -= 0.2 * mean_residual;
    }

    // Prefer bins whose residual is close to the item (best-fit flavor with
    // dead-space bias already applied).
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward residuals that exactly match the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);

        // Perfect chain: this placement leaves exactly the room the next item needs.
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // Next item cannot fit here afterwards; penalize wasting the residual.
        if post_residual > 0 && next_item_size > post_residual {
            score += 15.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    } else {
        // Last item: minimize leftover as strongly as possible.
        score += 30.0;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving less than average is good (tight packing), more is wasteful.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when current bins would leave large waste
    // or the item fits nothing well; otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64 - item_size as f64)
            - 10.0 * (fitting_bins_count as f64)
            + 20.0 * open_bins_count as f64 / (1.0 + step_index as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared normalized fill ratio.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space that can never be used by typical items (residual < 10).
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual too small for the next item: mild penalty for wasted space.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless current bin fits are terrible.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 - 20.0 * progress;
        // If mean residual across open bins is large, opening new bins is wasteful.
        score += 0.5 * mean_residual;
        // Few open bins and a small item: slightly more willing to open.
        if open_bins_count < 3 && item_size > 50 {
            score -= 15.0;
        }
    }

    // Global pressure: when many bins are open, prefer consolidation into existing bins.
    if open_bins_count > 5 {
        score -= 2.0;
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (1.0 - fill);

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let poly = pr * pr * (1.0 + 2.0 * progress) + 0.5 * pr * progress * (1.0 - progress);

    let mut score = post + poly * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= (1.0 - pr) * (1.0 - pr) * (10.0 + 20.0 * progress);

    // Penalize waste relative to mean residual of open bins.
    score += (pr * cap - mean_residual).abs() * 0.05;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space usable by the next item.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 8.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins late in the stream.
    score += open_bins_count as f64 * 0.3 * progress;

    // New-bin candidate: prefer it only when post_residual is large (good for future).
    if bin_residual == bin_capacity {
        score -= 5.0 * pr * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residues mod 10 create "dead space classes".
    // Class 0 (perfect multiples) is excellent; small nonzero residues (1..=5)
    // are near-perfect and also good; mid residues are wasteful.
    let residue = post_residual % 10;
    let class_bonus: f64 = match residue {
        0 => 18.0,
        1..=5 => 10.0 - residue as f64,
        _ => -(residue as f64 - 5.0) * 1.5,
    };
    score -= class_bonus;

    // Integer-division thresholds: post_residual in the "unusable tail"
    // (post < 10, smallest possible item) is dead space -> penalize.
    if post_residual < 10 {
        score += 25.0;
    }
    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits: fill ratio of the bin after placement.
    let fill = 1.0 - post / cap;
    score -= 12.0 * fill * fill;

    // Lookahead coupling: if the next item can fit into post_residual,
    // this placement chains nicely; otherwise penalize blocking.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // extra reward when next item exactly consumes the remainder class
            if post_residual % 10 == next_item_size % 10 && post_residual >= next_item_size {
                score -= 4.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // When many bins are open, prefer consolidating into existing space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (open_bins_count as f64).ln() * 2.0 * (0.5 + progress);

    // Prefer bins with residual below the running mean (compacting strategy),
    // but keep a mild pull toward the mean to avoid extreme fragmentation.
    let dev = post - mean_residual;
    score -= 0.15 * dev;
    score += 0.005 * dev * dev;

    // New-bin candidate: empty bin gets a moderate penalty so it only wins
    // when every open bin would leave a very wasteful remainder.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item (1..=100
    // interface, but treat anything below 12 as effectively unusable) are poison.
    if post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        // Moderate dead space: penalize proportionally to how "trapped" the gap is.
        score += (25.0 - post_residual as f64) * 1.5;
    } else {
        // Larger residuals are usable real estate; reward them mildly.
        score -= (post_residual as f64 - 25.0) * 0.15;
    }

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, this is a
    // golden two-item packing; reward it strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // If next item would leave a tiny unusable gap in this bin, discourage.
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 12 {
        score += 10.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // especially when this is the only fitting bin (last chance).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.8;

    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only bin that fits; strongly prefer using it over a new bin.
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open bin
    // offers a decent fit. Penalize it by the mean residual (large mean residual
    // => plenty of room already exists => opening a new bin is wasteful).
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.5 + open_bins_count as f64 * 1.5;
        // Early in the stream with no open bins, allow new bins cheaply.
        if open_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Filling a bin that is already tight relative to the mean is good.
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, normalized against capacity.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64) * (bin_capacity as f64);

    // 2-step lookahead: if the next item exactly fits the post_residual, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chain placement
        } else if post_residual >= next_item_size {
            // reward proportional to how snugly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // dead space for the next item: penalize unusable remainder
            let dead = (next_item_size - post_residual) as f64;
            score += 0.8 * dead;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // waste is bad; being tighter than average is good.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it unattractive unless it is genuinely needed
    // (no open bin fits, or this is the only fitting option and the fit is terrible).
    if bin_residual == bin_capacity {
        score += 70.0;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 10.0; // opening fresh for a large item followed by another large one
        }
        // Late in the stream, opening new bins is cheaper than long-term fragmentation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * progress;
    }

    // Small absolute bonus for very tight fits regardless of lookahead.
    if post_residual <= 5 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: early items -> prefer filling bins fully; late -> keep flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that likely cannot be reused: post_residual smaller than typical item.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    } else if (post_residual as f64) < mean_residual * 0.5 {
        score += 4.0;
    }

    // Lookahead: if next item fits into the resulting post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0 + 0.05 * next_item_size as f64;
        } else {
            // Next item won't fit here; penalize less if this bin is nearly full anyway.
            score += 2.0 * (1.0 - tightness);
        }
    }

    // Last-chance bonus: if only one bin fits, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Many open bins: encourage consolidation (prefer bins with residual below mean).
    if open_bins_count > 1 {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin is a decent fit or the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let poor_alternatives = fitting_bins_count == 0 || (post_residual as f64) < 0.25 * bin_capacity as f64;
        let large_item = (item_size as f64) > 0.7 * bin_capacity as f64;
        if poor_alternatives || large_item {
            score -= 3.0;
        } else {
            score += 12.0 + 10.0 * (1.0 - progress);
        }
    }

    // Mild late-stream preference for exact-ish packing.
    score += progress * (post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: reward tight fits (small post_residual), with a non-linear (quadratic) penalty
    // on leftover space so medium waste is punished more than linearly.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth polynomial coupling with stream progress: early in the stream, prefer
    // preserving flexibility (penalize very tight fits slightly); late in the stream,
    // reward tight fits aggressively since future opportunities shrink.
    let tightness = 1.0 - pr / cap;
    let coupling = progress * tightness * tightness - 0.5 * (1.0 - progress) * tightness;
    score -= 12.0 * coupling;

    // Lookahead: if the next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            score -= 8.0 * (1.0 - gap / cap);
        } else {
            score += 3.0 * (gap / cap);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, opening a new bin is costly.
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // Mild penalty when the bin's residual deviates from the fleet mean (keeps diversity),
    // scaled smoothly by number of open bins.
    let dev = (pr - mean_residual).abs();
    score += 0.02 * dev / (1.0 + open_bins_count as f64).ln();

    // New-bin candidate: make empty bins mildly attractive early, unattractive late.
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Reward tight fits: small post_residual gets strong discount.
    if post_residual > 0 {
        score -= 40.0 / post_residual as f64;
    } else {
        score -= 60.0; // perfect fill
    }

    // Harmonic class of post_residual modulo capacity quarters:
    // residuals that are multiples of 25 are more reusable.
    let pr = post_residual;
    if pr > 0 && pr % 25 == 0 {
        score -= 12.0;
    } else if pr < 10 {
        // dead space below smallest item size
        score += 25.0;
    }

    // Next-item lookahead: bonus if the next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 20.0 / (slack as f64 + 1.0);
        } else {
            // next item won't fit here; penalize large residuals less used
            score += 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // (item leaves large residual or doesn't pair with next item).
    if bin_residual == bin_capacity {
        let bad_fit = if post_residual > 0 && (post_residual < 10 || (next_item_size > 0 && next_item_size > post_residual && post_residual < 30)) { 1.0 } else { 0.0 };
        score = 45.0 - 25.0 * bad_fit + (open_bins_count as f64).sqrt() * 2.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small for the minimum item (1)
    // are pure waste; penalize very small gaps super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_frac;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: prefer denser bins when many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Prefer bins with residual below mean (filling emptier bins later).
    let res = bin_residual as f64;
    if res < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size < 10 {
        score -= 20.0;
    }
    // If next item cannot fit in post-residual and post-residual is dead space, penalize.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Baseline penalty so new bins are chosen only when placements are poor.
        score += 35.0;
        // More attractive late in the stream or with many open bins? No —
        // opening bins is costly, so scale penalty with open bins count.
        score += open_bins_count as f64 * 1.5;
        // If next item is large, a fresh bin is more useful.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin closed by next item
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 25.0 - leftover * 0.4; // partial chain, less reward as slack grows
        } else {
            // next item cannot follow; penalize dead space relative to gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.35;
        }
    }

    // Reward tight fits relative to mean residual of open bins.
    let residual_f = post_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.25;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win for big items or no good fit.
    if bin_residual == bin_capacity {
        if item_size >= 50 {
            score -= 5.0;
        } else {
            score += 30.0; // discourage wasting fresh bins on small items
        }
        if next_item_size > 0 && next_item_size <= post_residual && next_item_size == post_residual {
            score -= 40.0; // allow new bin when it enables a perfect chain
        }
    }

    // Slight preference to fill existing bins as stream progresses.
    score += (step_index as f64 / total_items.max(1) as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 18.0 * dead * dead * dead;
    }

    // Exact fill is excellent.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Perfect chain: next item exactly fills what remains.
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            // Post-residual too small for lookahead item: mild penalty.
            score += 0.06 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit, new bins pointless.
        if bin_residual == bin_capacity {
            score += 1000.0;
        }
        score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // New-bin candidate handling: penalize opening a new bin unless
    // current item is large and no open bin is tight-fitting.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let big_item = (item_size as f64) / (bin_capacity as f64);
        let open_pressure = (open_bins_count as f64) / (10.0 + open_bins_count as f64);
        // Base cost of a fresh bin.
        score += 25.0;
        // Discount new bin if item is huge (would leave tiny waste anyway)
        // and few bins are open or late in the stream.
        if big_item > 0.6 && (open_bins_count < 4 || progress > 0.8) {
            score -= 22.0 * big_item;
        }
        // Late stream: avoid spreading across many bins.
        if progress > 0.7 {
            score += 10.0 * open_pressure;
        }
        // If many fitting bins exist, opening new bin is wasteful.
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    }

    // Prefer bins whose residual is below the mean (consolidate emptier space usage):
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        score += 0.08 * (residual_f - mean_residual);
    }

    // Slight preference for bins with residual close to item_size + next_item_size.
    if next_item_size > 0 {
        let target = item_size as f64 + next_item_size as f64;
        score += 0.05 * (residual_f - target).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: favor small post residual (tight fit)
    let mut score = norm_pr;

    // Non-linear polynomial coupling with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: tolerate slack; late stream: punish it strongly
    score += norm_pr * (0.5 + 1.5 * p2 + 2.0 * p3);

    // Quadratic dead-space penalty: tiny post residual is great, mid-range slack is bad
    let dead = norm_pr * (1.0 - norm_pr);
    score += 0.6 * dead * (1.0 - progress);

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 0.8 + 0.5 * p2;
    }

    // Penalize opening new bins when many are open and residuals are plentiful
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / (1.0 + mean_residual / cap);
        score += 0.4 + 0.6 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (0.5 + scarcity);
    }

    // Lookahead coupling: if next item fits the post residual, reward heavily (smooth)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt).max(0.0) / cap;
        let fit_margin = 1.0 - (pr - nxt).abs() / cap;
        if pr >= nxt {
            score -= 0.5 * fit_margin * (1.0 + progress);
        } else {
            score += 0.2 * fits;
        }
    }

    // Slight preference for bins below mean residual (balance residuals smoothly)
    score += 0.1 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "useful" classes (multiples of common item sizes), penalize dead space.
    let pr = post_residual;
    if pr > 0 {
        // Class A: residual exactly reusable by common item sizes
        let mut best_fit_bonus = 0.0f64;
        for &d in &[10u32, 20, 25, 30, 40, 50, 60, 70, 80] {
            if pr % d == 0 && pr >= d {
                best_fit_bonus += 6.0;
            }
        }
        score -= best_fit_bonus;

        // Class B: residual leaves a small unusable sliver (< 10)
        if pr < 10 {
            score += (10 - pr) as f64 * 2.0; // dead space penalty
        }

        // Class C: integer-division threshold buckets
        let bucket = pr / 10; // 0..10
        match bucket {
            0 => score += 8.0,          // tiny residual: near-perfect fit
            1 | 2 => score -= 3.0,      // good compact usage
            3 | 4 => score -= 1.0,      // moderate
            5 | 6 => score += 2.0,      // half-empty bin: mediocre
            _ => {}                      // large residual: neutral (fresh bins live here)
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size < pr {
            // reward proportional to how well next item fills this bin
            let fill = next_item_size as f64 / pr as f64;
            score -= fill * 8.0;
            // modulo harmony between next item and residual
            if pr % next_item_size.max(1) == 0 {
                score -= 5.0;
            }
        } else {
            // next item cannot fit here: slight penalty if we'd waste capacity
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a bin, modulated by stream position and congestion.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut open_cost = 55.0;
        open_cost -= progress * 10.0;                 // late stream: slightly cheaper to open
        open_cost += (open_bins_count as f64).min(20.0); // congestion penalty
        // If mean residual is large, prefer existing bins
        open_cost += (mean_residual / cap).clamp(0.0, 1.0) * 25.0;
        // If the item is huge relative to typical residual, opening is fine
        if item_size as f64 > mean_residual {
            open_cost -= 20.0;
        }
        score = open_cost + post_residual as f64 * 0.5;
    }

    // Fractional capacity alignment: items near half or full capacity
    let frac = item_size as f64 / cap;
    if (frac - 0.5).abs() < 0.05 {
        score -= 2.0; // half-capacity items are flexible
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item (size 1..100 unknown distribution, so
    // treat anything below ~15 as likely dead space) are heavily penalized.
    let dead_threshold = 15u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += (dead_threshold - post_residual) as f64 * 6.0;
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fits (small post_residual) get a proportional bonus.
    score -= (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.05;

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; penalize less when this bin absorbs the item.
    score += open_bins_count as f64 * 0.35;

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward this placement; if next item would be blocked by a small
    // residual, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && post_residual < dead_threshold {
            score += 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has maximal residual; make it
    // moderately attractive only when current bins would leave bad dead space
    // or when bin pressure is low.
    if bin_residual == bin_capacity {
        let bad_fit_penalty = if post_residual > 0 && post_residual < dead_threshold { 0.0 } else { 1.0 };
        score -= 12.0 * bad_fit_penalty;
        score -= (open_bins_count == 0) as i32 as f64 * 30.0;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a good consolidator; reward reducing the spread.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: nearly-zero post residual is ideal
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 150.0;
        } else if gap <= 5.0 {
            score -= 60.0 - gap * 6.0;
        } else {
            score += gap * 0.5;
        }
        // Penalize leaving space that next item cannot use but is too large to matter
        if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit here; dead space penalty scaled by deadness
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += (10.0 - dead) * 8.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if item is large and lookahead matches well, allow it
        if next_item_size > 0 && (bin_capacity as i64 - item_size as i64 - next_item_size as i64).abs() <= 2 {
            score -= 60.0;
        }
        // Prefer opening new bins for large items late in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 {
            score -= 15.0 * progress;
        }
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post-residual more than linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 {
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 50.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (perfect chain).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 30.0;
        } else if nxt <= post_residual as f64 {
            // Next item fits but wastes some space: mild penalty for waste ratio.
            let waste = (post_residual as f64 - nxt) / cap;
            score += 8.0 * waste;
        } else {
            // Next item cannot fit here: slight reward for keeping residual large.
            score -= 2.0 * (post_residual as f64 / cap);
        }
    } else {
        // Last item: prefer filling bins as fully as possible.
        score -= 20.0 * (1.0 - (post_residual as f64) / cap);
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // open bins are crowded or the fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 15.0;
        // More open bins with low mean residual -> opening new bins is worse.
        score += 2.0 * open_bins_count as f64;
        score -= 10.0 * (mean_residual / cap);
        // If many bins can fit the item, opening a new bin is clearly bad.
        if fitting_bins_count > 1 {
            score += 20.0 * (fitting_bins_count as f64);
        }
    } else {
        // Mild preference for using bins that are already partially filled
        // when many bins are open (reduce bin count fragmentation).
        score += 0.5 * (open_bins_count as f64) * (post_residual as f64 / cap);
    }

    // Time horizon: early in the stream, be conservative (favor new bins for
    // flexibility); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / cap);
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    // Mean-residual coupling: prefer bins whose residual deviates favorably
    // from the mean (below mean residual = this bin is tighter than average).
    score += 3.0 * (mean_residual - bin_residual as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // normalized post residual
    let x = pr / cap;
    // non-linear polynomial in x, modulated by stream progress
    let poly = x * x * (1.0 - x) * (1.0 - x);
    // dead-space penalty: quadratic in post residual, growing with progress
    let mut score = pr * (1.0 + 2.0 * progress) + 40.0 * poly * (1.0 - progress);
    // reward tight fits (small post residual) more strongly late in stream
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 20.0 * progress);
    // last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // prefer bins below mean residual (consolidate space)
    score += (mean_residual - bin_residual as f64) * 0.1;
    // lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 5.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score -= 3.0;
    }
    // slight penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress) - 2.0 * progress;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residual in [0,10) is prime dead space
    let dead = post_residual < 10;
    if dead {
        score += 40.0 * (1.0 - (post_residual as f64) / 10.0);
    }

    // Next item coupling: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 250.0;
        } else if next_item_size <= post_residual {
            // next item fits here too: mild reward scaled by tightness
            score -= 30.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item cannot use this residual: penalize wasted space
            score += 15.0;
        }
    }

    // Integer-division thresholds on post_residual (harmonic classes of capacity)
    let cls = post_residual / 25; // 0..4 quartile class
    score += match cls {
        0 => 60.0,          // tiny residual, nearly unusable
        1 => 10.0,          // small residual
        2 => -5.0,          // quarter capacity left, useful
        3 => -15.0,         // half-ish capacity, very useful
        _ => -20.0,         // mostly empty
    };

    // Modulo logic on post_residual (harmonic mod-10 classes)
    let m = post_residual % 10;
    if m == 0 && post_residual > 0 {
        score -= 12.0; // round residual tends to match item sizes
    } else {
        score += m as f64 * 0.8; // awkward off-round residuals penalized
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: neutral-ish baseline; open new bin only if open bins are crowded
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / (mean_residual / bin_capacity as f64).max(0.01);
        score = 55.0 + 0.3 * mean_residual - 0.2 * crowd.min(50.0);
        // prefer new bin early in stream (more future flexibility)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * (1.0 - progress);
    }

    // Spread-aware penalty: if this bin's residual is far below mean, it's already fragmented
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += 0.15 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Dead space penalty: residuals too small for the smallest plausible item (<= ~10)
    // are unusable dead weight; punish them harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Post-residual that cannot accommodate the lookahead item is partially wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward bins that can also host the next item (chaining).
        score -= 3.0;
    }

    // Last-chance pressure: if this is the only fitting bin, using it avoids a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins
    // over opening new ones; with few bins, new-bin candidate is less penalized.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin = (bin_residual == bin_capacity) as i32;
    if new_bin == 1 {
        // Opening a new bin: penalize more when many bins are open or early stream.
        score += 6.0 + 0.15 * open_bins_count as f64 + 5.0 * (1.0 - progress);
    } else {
        // Existing bin: slight bonus scaled by how far below mean residual it sits
        // (prefer consuming the emptiest bins first to close them out).
        score -= 0.05 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

