    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use
        score += 15.0;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // Penalize opening a new bin when open bins could still serve
    if bin_residual == bin_capacity {
        score += 40.0 + (open_bins_count as f64) * 2.0;
    }

    // Late-stream tightening: as stream progresses, prefer tighter fits more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Primary: reward tight fits (squash post-residual).
    score = (post_residual as f64).powf(1.35);

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 18.0 + 12.0 * (nxt / cap);
        } else {
            // Penalize leaving a residual just barely too small for the next item.
            let miss = nxt - post_residual as f64;
            if miss < 15.0 {
                score += 8.0 * (1.0 - miss / 15.0);
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
    }

    // Penalize dumping small items into large-residual bins when many alternatives fit.
    if fitting_bins_count > 2 {
        score += 0.06 * (post_residual as f64) * (fitting_bins_count as f64).min(10.0);
    }

    // Global coupling: prefer bins whose residual is near the mean residual
    // (keeps the fleet of open bins homogeneous, preserving future pairing options).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (keep residuals large for future items); late, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate: choose it when existing fits are poor or early stream
    // with a big next item needing fresh space.
    if bin_residual == bin_capacity {
        let mut new_bin_score = cap * 0.62;
        // Early stream: new bins are cheaper.
        new_bin_score -= 20.0 * (1.0 - progress);
        // If the next item is large, a fresh bin preserves pairing potential.
        if next_item_size > 0 && (next_item_size as f64) > 0.5 * cap {
            new_bin_score -= 10.0;
        }
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_score += 6.0 * (fitting_bins_count as f64).min(5.0);
        // Late stream: strongly discourage new bins unless nothing fits.
        new_bin_score += 25.0 * progress;
        score = score.min(new_bin_score.max(score * 0.0 + new_bin_score));
        // Blend: new bin competes via its own score.
        return new_bin_score;
    }

    // Late stream: extra pressure to fill bins tightly.
    score += 6.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
