    let dead = (norm_pr - 0.5) * (norm_pr - 0.5);
    score += 30.0 * dead * (1.0 - progress);

    // Reward tight fits: quadratic bonus shrinking with post_residual
    let tight = (1.0 - norm_pr).powi(3);
    score -= 20.0 * tight;

    // Lookahead coupling: penalize if next item can't use post_residual
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score += (1.0 - fits_next) * 8.0 * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mean residual deviation penalty (smooth)
    score += 0.3 * (mean_residual - pr).abs();

    // New-bin candidate: mild penalty so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

