    if post_residual == 0 {
        score -= 1000.0; // perfect fit, best possible
    } else if post_residual <= 10 {
        score += 60.0; // tiny dead space, nearly unusable
    }

    // Harmonic divisibility reward: residual that can be filled by typical items (multiples of 10)
    let harmonic = post_residual % 10 == 0;
    if harmonic {
        score -= 25.0;
    } else {
        score += 10.0;
    }

    // Sub-harmonic classes via integer division thresholds on post_residual
    let class = post_residual / 20; // classes: 0..=5 for capacity 100
    score -= class as f64 * 8.0;

    // Lookahead coupling: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / pr.max(1.0);
            // reward tight follow-up fits
            if frac > 0.8 { score -= 60.0; }
            else if frac > 0.5 { score -= 20.0; }
            else { score += 15.0 * (1.0 - frac); }
        } else {
            // next item cannot use this residual: penalize proportionally to wasted harmonic class
            score += 0.3 * pr;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: empty bin gets baseline penalty unless stream is early
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64 / 10.0;
        score = cap - 55.0 + progress * 30.0 + open_pressure * 5.0;
        // opening a new bin is fine if mean residual is small (open bins nearly full)
        if mean_residual < 20.0 { score -= 25.0; }
        if next_item_size > 0 && next_item_size <= post_residual { score -= 10.0; }
    }

    // Mild preference for bins with below-mean residual (keep big gaps for big items)
    let diff = mean_residual - bin_residual as f64;
    score += 0.1 * diff.max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Dead-space penalty: gaps that are too small to ever be useful ---
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64) / 10.0;
    }

    // --- Perfect fit reward ---
    if post_residual == 0 {
        score -= 25.0;
    }

    // --- Reward when post_residual can still host the lookahead item ---
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap that just barely misses the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // --- Last-chance bin: strongly favor using it before opening a new one ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // --- Open-bin pressure: discourage spreading across many bins ---
    score += 0.6 * open_bins_count as f64;

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is fine when it produces a roomy bin and
        // existing bins are fragmented, but costly when open bins are few.
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 12.0 - 0.35 * fragmentation;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Avoid opening a new bin for a tiny item when bins are plentiful
        if item_size < 30 && open_bins_count > 3 {
            score += 25.0;
        }
    }

    // --- Slight preference for filling fuller bins first ---
    score -= 4.0 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits (small post_residual), but reward residual
    // that exactly matches the next item (2-step lookahead chain).
    let pr = post_residual as f64;
    let n = next_item_size as f64;

    if next_item_size > 0 {
        // Perfect chain: post_residual == next_item_size -> strong reward.
        let diff = (pr - n).abs();
        if diff < 0.5 {
            score -= 25.0;
        } else if pr > n {
            // Residual can host next item but not perfectly: mild reward
            // proportional to how little slack is wasted after that.
            score -= 8.0 * (1.0 - ((pr - n) / 100.0)).max(0.0);
        } else {
            // Residual too small for next item: penalize dead space,
            // unless it's essentially zero (perfect fill).
            if pr > 0.5 {
                score += 6.0 * (1.0 - pr / 30.0).max(0.0);
            } else {
                score -= 20.0; // exact fill is excellent
            }
        }
    } else {
        // Last item: pure tightest fit.
        score -= 10.0;
    }

    // Compare against mean residual: placing in a bin whose residual is far
    // below average preserves the large-residual bins for bigger items.
    if pr < mean_residual {
        score -= 3.0;
    } else {
        score += (pr - mean_residual) * 0.05;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly so we only open a new bin when no
    // open bin offers a decent fit. Scale with stream progression (late in
    // the stream, consolidation matters more).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 8.0 * progress;
    }

    // Mild preference for keeping fewer open bins (reduces fragmentation).
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that cannot plausibly be reused by future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }

    // Lookahead: if the next item fits into this bin's post_residual, reward it.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item won't fit here; slight penalty for wasting post space.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate: prefer keeping it closed early on, allow opening
    // when open bins are fragmented (high mean residual spread).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        let open_pressure = open_bins_count as f64;
        // Open a new bin when existing bins are large-residual (poor fits) or many bins.
        score += 12.0 - 8.0 * progress - 0.15 * open_pressure - 0.05 * mean_residual + 0.1 * fragmentation;
        if item_size > 70 {
            score -= 15.0; // big items deserve a fresh bin
        }
    }

    // Prefer bins whose residual is close to mean (balanced packing) mildly.
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Slight preference for fuller bins as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap; // 0..1
    let mut score = post * (1.0 + 0.5 * progress) + 12.0 * norm_post * norm_post * (1.0 - progress);

    // Reward tight fits: small post_residual relative to item size.
    let item = item_size as f64;
    let tightness = item / (item + post + 1.0);
    score -= 20.0 * tightness * tightness;

    // Penalize creating dead space that no typical next item could use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = if post >= nxt { 1.0 } else { post / (nxt + 1.0) };
        score -= 8.0 * usable * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild pressure when many bins are open: prefer consolidation.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Penalize deviation from mean residual (prefer balanced fills).
    score += 0.1 * (post - mean_residual).abs();

    // New empty bin candidate: penalize opening a new bin, less so late in stream or for large items.
    if bin_residual == bin_capacity {
        score += 25.0 - 10.0 * progress - 0.1 * item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by large powers
    // of small integers are more "reusable" by future items.
    let pr = post_residual;
    let mut harmony: f64 = 0.0;
    if pr > 0 {
        // count divisibility by 2,3,5 (harmonic classes)
        let mut t = pr;
        while t % 2 == 0 { harmony += 1.0; t /= 2; }
        let mut t = pr;
        while t % 3 == 0 { harmony += 0.7; t /= 3; }
        let mut t = pr;
        while t % 5 == 0 { harmony += 0.5; t /= 5; }
    } else {
        // perfect fill: best possible outcome
        harmony = 12.0;
    }

    // Reward harmonious residuals (subtract to favor)
    score -= 1.5 * harmony;

    // Integer-division thresholds: residual buckets by tenths of capacity
    let tenth = bin_capacity / 10;
    let bucket = pr / tenth;
    score -= match bucket {
        0 => 8.0,   // tiny dead space (<10): nearly useless
        1 | 2 => 4.0,
        3 | 4 => 1.0,
        5 | 6 => -1.0,
        _ => -2.0,  // large residual: very reusable
    };

    // Coupling with next item: reward residuals that exactly or closely fit lookahead
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 15.0; // perfect two-item chain
            } else if slack <= 5 {
                score -= 9.0;
            } else if slack <= 15 {
                score -= 4.0;
            }
        } else {
            score += 3.0; // lookahead cannot use this bin's leftover
        }
    } else {
        // last item: strongly prefer perfect fill
        score -= 6.0 * (pr == 0) as i32 as f64;
    }

    // Last-chance bin: if this is the only fitting bin, penalize opening a new bin
    // instead by rewarding this bin.
    if fitting_bins_count == 1 {
        score -= 7.0;
    } else if fitting_bins_count > 3 {
        score += 1.0 * (fitting_bins_count as f64 - 3.0).min(3.0);
    }

    // Prefer tighter-than-average bins early; spread load late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let avg_pull = (bin_residual as f64 - mean_residual) * 0.15;
    score += avg_pull * (1.0 - 0.5 * progress);

    // Modulo-class bonus: residuals in {0, 25, 50, 75} quarters are classic anchors
    if pr % 25 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Slight preference to consolidate into fewer bins
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    let post = post_residual as f64;
    score += post;

    // Strict dead-space avoidance: post_residual in a "dead zone" (small gap
    // that few future items can use) gets a heavy extra penalty.
    let dead_threshold = 20.0;
    if post > 0.0 && post < dead_threshold {
        // The smaller (more unusable) the gap relative to the dead zone, the worse.
        let unusability = 1.0 - (post / dead_threshold);
        score += 30.0 * unusability * unusability;
    }

    // Perfect fill reward.
    if post == 0.0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // Gap can host the next item: reward closeness of gap to next size.
            let slack = (post - nxt) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else if post > 0.0 {
            // Gap cannot host next item: mild penalty proportional to wasted potential.
            score += 6.0 * (1.0 - post / nxt.max(1.0));
        }
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // by rewarding use of existing bins, especially the last-chance bin.
    if bin_residual < bin_capacity {
        score -= 3.0 * open_bins_count as f64;
    }
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has no dead space, but opening
    // one should be penalized unless the fit into existing bins is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with stream progression.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 20.0 * progress;
        // But if existing bins would leave a dead gap anyway, new bin is attractive.
        let post_existing = bin_residual - item_size;
        if post_existing > 0 && post_existing < dead_threshold {
            score -= 35.0;
        }
        // If no other bin fits, new bin is essentially forced.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mean-residual coupling: if this bin's residual deviates badly from the
    // mean (creating an outlier gap), add friction.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match bonus decaying with distance to next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 25.0 / (1.0 + gap * 0.5);
        // Penalize post_residual too small for the next item (dead space risk),
        // but only mildly if it is still a decent residual.
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Reward tight fits: small post_residual is good (already the base term).
    // Penalize leaving awkward mid-range residual (e.g. 20..45) that few items use.
    if post_residual >= 20 && post_residual <= 45 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
        // If the next item is large, a fresh bin is more attractive.
        if next_item_size >= item_size {
            score -= 12.0;
        }
    }

    // Slight preference toward bins below mean residual (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual dominates, but amplify near-perfect fits.
    if post_residual <= 2 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Penalize dead space relative to capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 15.0;

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 25.0 * (1.0 - slack as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting space.
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Among many fitting bins, prefer tighter ones (already via post_residual).
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate: opening a bin is only attractive when open bins are crowded
    // or the item is large relative to mean residual.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let item_ratio = item_size as f64 / bin_capacity as f64;
        // Penalize new bin by default...
        score += 60.0;
        // ...but discount the penalty when bins are full-ish or item is big.
        score -= 60.0 * crowding * crowding;
        score -= 30.0 * item_ratio * item_ratio;
        // Early in the stream, opening bins is cheaper (more future use).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Mild global pressure: many open bins -> favor consolidating into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 1.5;

    // Prefer bins whose residual is close to the item (perfect marriage).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: minimize wasted space, with non-linear (quadratic) waste penalty.
    let mut score = post + 0.012 * post * post / cap;

    // Smooth coupling: waste matters more as the stream progresses.
    score *= 0.75 + 0.5 * progress * progress;

    // Reward tight fits (small post_residual relative to item) with smooth saturation.
    let tightness = 1.0 - post / (item + post).max(1.0);
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if next item can use the post residual, reward leaving it.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = if post >= nx { 1.0 } else { post / nx.max(1.0) };
        score -= 4.0 * usable * (1.0 - progress);
    } else {
        // Last item: only waste matters, penalize any residual.
        score += 0.02 * post;
    }

    // Penalize bins far from mean residual (fragmentation), smooth coupling.
    let dev = (post - mean_residual).abs();
    score += 0.03 * dev * (0.5 + 0.5 * progress);

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = cap + 20.0 - 40.0 * scarcity * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward "useful" residual classes.
    // Classes: perfect fit (0), small usable (1..=20), medium (21..=50), dead (>50).
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual <= 20 {
        score -= 12.0;
    } else if post_residual <= 50 {
        score -= 4.0;
    } else {
        score += 8.0; // large dead space penalized
    }

    // Modulo-10 harmonic coupling: residuals that are multiples of 10 align
    // with common item sizes; slightly favor them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item won't fit here; penalize leaving mid-range residual
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        // open new bin only when item is large or few bins fit
        let penalty = 30.0 - 25.0 * tightness - 15.0 * (fitting_bins_count as f64 == 0.0).then_some(1.0).unwrap_or(0.0);
        score += penalty;
        // early stream: slightly prefer opening bins to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Prefer filling bins with high residual relative to mean (reduce spread).
    score += (mean_residual - post_residual as f64).max(0.0) * 0.2;

    // Mild penalty for very tight fits that strand space < 10 (unusable).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the minimum item (1) are pure waste;
    // gaps below a "usable threshold" (cannot fit a mid-size item) are heavily penalized.
    let dead_threshold: f64 = 12.0; // gaps below this are near-unusable for typical items
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit: strongest reward
    if post_residual == 0 {
        score -= 40.0;
    }
    // Tight fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 15.0 * (fill_ratio - 0.7) / 0.3;
    }

    // --- Lookahead coupling: keep room for the next item if it fits snugly ---
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to snugness
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 * snug;
        } else {
            // next item will NOT fit in the leftover: penalize small leftovers harder
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    }

    // --- Open-bin pressure: discourage scattering across many bins ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.15 + 0.25 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // --- Last-chance bonus: if this is the only fitting bin, strongly prefer it ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current open bins have poor fits
        // or are few; penalize new bins when existing bins are plentiful/tight.
        let mean_gap = mean_residual - post_residual as f64;
        let mut new_bin_score = 55.0 + pressure * 2.0;
        if mean_gap > 0.0 {
            // existing residuals are larger (loose bins): new bin less attractive
            new_bin_score += mean_gap * 0.5;
        } else {
            // existing bins are tight: opening fresh is good
            new_bin_score -= mean_gap.abs() * 0.8;
        }
        if fitting_bins_count == 0 {
            new_bin_score -= 100.0; // no alternative: must open
        }
        score += new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 60.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: post_residual == next_item_size is ideal.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Penalize creating dead space the next item cannot use.
            let dead = (next_item_size - post_residual) as f64;
            score += 12.0 * (dead / 100.0);
        }
    } else {
        // Last item: just close bins as tightly as possible.
        score += 5.0 * post_residual as f64 / 100.0;
    }

    // Relative-to-mean coupling: prefer bins tighter than the average open bin.
    score += 8.0 * ((bin_residual as f64) - mean_residual) / 100.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize spreading across too many open bins early; encourage consolidation.
    score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild stream-progression pressure: later in the stream, tighten packing more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins attractive only when no good fit exists
    // (i.e., when residual waste would be large in existing bins).
    if bin_residual == bin_capacity {
        score += 45.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // new bin can chain the next big item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Normalized post-residual (fraction of capacity left after placement)
    let pr_norm = pr / cap;

    // Base cost: post residual, non-linearly coupled with stream progress.
    // Early on, leaving space is cheap (bins can absorb more items later);
    // late in the stream, dead space is costly.
    let mut score = pr_norm * (1.0 + 2.0 * progress * progress);

    // Polynomial coupling: squared post-residual penalizes large gaps
    // increasingly, but the penalty strength grows with progress.
    score += 1.5 * pr_norm * pr_norm * (0.3 + progress);

    // Reward tight fits: small post-residual relative to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.0 * fit_ratio * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 3.0;
    } else if fitting_bins_count > 1 {
        // Many fitting bins: mild penalty for hoarding space in this one,
        // encouraging spreading across bins.
        score += 0.3 * (fitting_bins_count as f64).ln();
    }

    // Lookahead coupling: if the next item can still fit the post-residual,
    // reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 0.8 * (1.0 - pr_norm) * (1.0 + 0.5 * progress);
        } else {
            score += 0.5 * (pr_norm - nxt / cap).abs();
        }
    }

    // Contextual term: compare this bin's post-residual to mean residual
    // across open bins. Placing into a below-average-residual bin (tight bin)
    // is preferred; coupling with number of open bins controls consolidation.
    let mean_norm = mean_residual / cap;
    score += 0.6 * (pr_norm - mean_norm) * (1.0 + (open_bins_count as f64).ln().max(0.0));

    // Mild preference to keep few open bins early on (consolidation),
    // relaxing as the stream grows.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate handling: empty bin has pr == cap. Its base pr_norm
    // is 1.0 which is naturally high; add a progress-dependent opening cost
    // so early in the stream new bins are discouraged, late they are cheaper.
    if bin_residual == bin_capacity {
        score += 1.0 * (1.0 - progress) + 0.5 * pr_norm * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    if post_residual > 0 {
        score -= 30.0 / post_residual as f64;
    } else {
        score -= 40.0; // perfect fit is ideal
    }

    // Harmonic class of post_residual: residuals divisible by 10 are "clean"
    // (more future items can fill them exactly).
    let clean = post_residual % 10 == 0;
    if clean { score -= 8.0; } else { score += 4.0; }

    // Penalize residuals in awkward dead-space classes (1..=9 mod 10 waste).
    let waste_class = post_residual % 10;
    score += waste_class as f64 * 0.7;

    // Integer-division thresholds: classify residual size.
    let quarter = bin_capacity / 4;
    if post_residual < quarter {
        // small leftover: fine if clean, bad otherwise
        if !clean { score += 6.0; }
    } else if post_residual <= bin_capacity / 2 {
        score += 2.0; // medium leftover is acceptable
    } else {
        // large leftover: keep bins roomy unless item is huge
        score += (post_residual as f64 - bin_capacity as f64 / 2.0) * 0.15;
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // exact pairing bonus (post_residual == next_item_size)
        if next_item_size == post_residual { score -= 10.0; }
        // harmonic class: next item leaves a clean residual too
        if (post_residual - next_item_size) % 10 == 0 { score -= 4.0; }
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; slight penalty if we waste space
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
        // extra reward if this is the only fitting bin and fit is decent
        if post_residual <= quarter { score -= 10.0; }
    }

    // New-bin candidate: only attractive when few bins are open or the
    // stream is early (room to build good pairs later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0;                       // base cost of opening a bin
        score -= progress * 15.0;            // late stream: prefer existing bins
        score -= (open_bins_count as f64).min(10.0) * 1.5; // more open bins -> cheaper to reuse
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // pair a big item with the next big item in a fresh bin
        }
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 10.0; // all bins nearly full: new bin is genuinely needed
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low post residual)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here; mildly reward leaving room for it
            let leftover = post_residual - next_item_size;
            score -= 80.0 - (leftover as f64).min(80.0) * 0.5;
        } else {
            // next item won't fit in this bin after placement; penalize tight leftover space
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 60.0; // dead space too small for anything useful
            } else if gap <= 20.0 {
                score += 15.0;
            }
        }
    }

    // Compare against mean residual: bins tighter than average are better to fill
    let mean_r = mean_residual.max(0.0);
    if (post_residual as f64) < mean_r {
        score -= (mean_r - post_residual as f64) * 0.8;
    } else {
        score += (post_residual as f64 - mean_r) * 0.4;
    }

    // Last-chance bin: if this is the only bin that fits the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate penalty: opening a new bin wastes residual of open bins
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if no open bin fits well (large item, few fitting bins), allow new bin
        if fitting_bins_count == 0 || item_size >= 60 {
            score -= 120.0;
        }
        // Late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Prefer bins with tighter residuals generally (best-fit bias)
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (post_residual small relative to capacity)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize creating dead space too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 {
            score += (post_residual as f64) * 0.15; // stranded space if next item can't use it
        }
        // Bonus if post_residual exactly complements next item to near-full
        if post_residual >= next_item_size && (post_residual - next_item_size) < 5 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive unless
    // the item is large and residuals across open bins are small (fragmented state)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bin more when open bins are roomy; less when fragmented
        score += 18.0 + fragmentation * 25.0 - progress * 5.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0; // large items may justify fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 6.0; // keep pairing room available
        }
    }

    // Prefer filling bins that are already mostly full (large item_size relative to residual)
    let fill_fraction = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_fraction * 15.0;

    // Mild penalty for spreading across many open bins when mean residual is high
    if open_bins_count > 3 && mean_residual > bin_capacity as f64 * 0.5 {
        score += 3.0;
    }

    // Time-horizon modulation: later in the stream, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * fit_ratio * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer tight fits (small post residual), non-linearly
    let mut score = x * x * (1.7 - 0.6 * t) + 0.9 * x;

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (penalize low residual less); later, pack tightly.
    let flex = (1.0 - t) * (1.0 - t);
    score += flex * 6.0 * x * (1.0 - x) * (1.0 - x);
    score -= t * t * 2.5 * x * (1.0 - x);

    // Penalize waste relative to mean residual of open bins (smooth interaction)
    let waste_gap = x - mean_residual / cap;
    score += 0.35 * waste_gap * waste_gap - 0.25 * waste_gap;

    // Last-chance bin bonus: if this is the only fitting bin, reward using it
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * t;
    } else {
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits exactly in post residual, strongly reward
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - ((pr - nx) / cap);
            score -= 2.2 * fit_quality * fit_quality;
        } else {
            score += 0.6 * (nx - pr) / cap;
        }
    }

    // New-bin candidate: empty bin gets a penalty so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 1.8 + 1.5 * (open_bins_count as f64).ln().max(0.0) + 2.0 * t;
    }

    // Mild penalty for proliferating open bins
    score += 0.04 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space
    // modulo common item size classes (small items are 1..100, but common
    // harmonic anchors are 10, 20, 25, 50).
    let anchors: [u32; 5] = [10, 20, 25, 50, 100];
    let mut harmony: f64 = 0.0;
    for (i, &a) in anchors.iter().enumerate() {
        let r = post_residual % a;
        // perfect alignment (r == 0) is highly desirable: future items of that
        // class can exactly fill the remainder.
        if r == 0 {
            harmony += 12.0 + 4.0 * (i as f64);
        } else {
            // penalize misalignment proportional to how close to a full block
            // we miss (dead space at the top of a class)
            let frac = r as f64 / a as f64;
            harmony -= 6.0 * frac;
        }
    }
    score -= harmony;

    // Integer-division thresholds on post_residual: bins whose leftover falls
    // into small "dead" buckets (post_residual < 10) are effectively closed;
    // reward that (packing tight is good).
    if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score += 4.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Harmonic class of the item itself: large items (>= 50, half capacity)
    // should prefer tightest fit, small items can tolerate slack.
    let item_class = item_size / 10;
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * (0.05 + 0.02 * item_class as f64);

    // Lookahead: if next item exactly divides the post residual (harmonic
    // continuation), strongly reward this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 {
                score -= 14.0;
            }
            score += rem as f64 * 0.15;
        } else {
            // next item cannot fit here anyway; slight penalty for hoarding space
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals
    // are all too fragmented (mean residual low relative to item size).
    if bin_residual == bin_capacity {
        score += 10.0;
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
        // late in the stream, consolidation is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
    }

    // Mild pressure against bin proliferation
    score += 0.4 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small to be useful are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual as i32) as f64 * 5.0;
    }

    // Reward tight fits (small positive residual).
    score -= (bin_capacity as f64 - post_residual as f64).sqrt() * 2.0;

    // Pressure: penalize creating many open bins unless necessary.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item could fill this bin's post-residual exactly, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item can't use the leftover: penalize leaving stranded space.
        score += post_residual as f64 * 0.5;
    }

    // Mild time pressure: early in stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (mean_residual / bin_capacity as f64).max(0.0);

    // New-bin candidate: only attractive when open bins have poor fits.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 15.0 + mean_residual * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: minimize wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += waste_ratio * 30.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect match bonus: next item exactly fills the bin afterwards.
        if gap < 0.5 {
            score -= 60.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Post-residual too small for next item: dead space penalty scaled by dead size.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Penalize bins far from the mean residual (prefer balanced residual landscape),
    // unless it's a near-perfect fit where we want to use the outlier.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening fresh bins unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Early in stream, opening bins is cheaper; late, conserve bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for fuller bins overall.
    score += (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else {
        // Penalize large dead space quadratically.
        score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;
    }

    // Lookahead: reward bins whose residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Slight penalty for stranding the lookahead item.
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and mean residual across open bins is low (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let openness = (open_bins_count as f64) / (mean_residual + 1.0);
        let pressure = item_size as f64 / 100.0;
        score += 90.0 - 70.0 * pressure - 20.0 * (1.0 - progress) - 5.0 * openness;
    }

    // Time horizon: later in stream, prefer tighter packing (favor small post_residual more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer bins below mean residual (consolidate emptier space usage).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap;

    // Base: prefer small post-residual, with non-linear shaping (quartic-ish tightness reward)
    let mut score = post;
    score -= 18.0 * (1.0 - pr) * (1.0 - pr) * (1.0 - pr);
    score += 12.0 * pr * pr * pr;

    // Smooth coupling of tightness with stream progress: late in the stream, prize tight fits more
    let tight = 1.0 - pr;
    score -= 10.0 * progress * tight * tight * (1.0 - pr * 0.5);

    // Penalize mid-range dead space (polynomial bump centered at pr ~ 0.3)
    score += 14.0 * pr * (1.0 - pr) * (pr - 0.35) * (pr - 0.35) * 4.0;

    // Lookahead: smooth reward if next item fits the post-residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (post - nxt).max(0.0) / cap;
        let fit_quality = 1.0 - (fits * 2.0).min(1.0);
        let can_fit = if post >= nxt { 1.0 } else { 0.0 };
        score -= 9.0 * can_fit * fit_quality * (0.5 + 0.5 * progress);
        // Penalize leaving a gap that almost-but-not-quite fits the next item
        let near_miss = if post < nxt { 1.0 - (nxt - post) / cap } else { 0.0 };
        score += 6.0 * near_miss * near_miss * near_miss;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    } else {
        // Mild penalty when many bins compete, encouraging consolidation
        score += (fitting_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // Prefer bins below mean residual (consolidate emptiness), smooth quadratic coupling
    score += 0.08 * (bin_residual as f64 - mean_residual) * (bin_residual as f64 - mean_residual) / cap;

    // Mild penalty for opening new bins when many are already open, smoothly scaled by progress
    let is_new = (bin_residual as u32 == bin_capacity) as f64;
    score += is_new * (8.0 + 14.0 * progress + 0.5 * open_bins_count as f64);

    // Slight reward for filling larger items into emptier bins early on
    score -= (1.0 - progress) * 3.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals in "usable" modular bands.
    // Residuals divisible by small common item sizes (10..=20) are reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut best_div = 0u32;
        for d in [10u32, 12, 15, 16, 20, 25, 30, 40, 50].iter() {
            if pr % d == 0 && *d > best_div {
                best_div = *d;
            }
        }
        if best_div > 0 {
            score -= 4.0 + best_div as f64 * 0.15;
        }
        // Penalize dead-space zone: residuals in (0, 10) are nearly unusable
        if pr < 10 {
            score += 30.0;
        }
        // Integer-division threshold bands on post_residual
        let band = pr / 10; // 0..=10
        match band {
            0 => score += 15.0,
            1 => score -= 1.0,
            2 => score -= 2.5,
            3 => score -= 3.0,
            4 => score -= 2.0,
            5 => score -= 3.5,
            6 | 7 => score -= 1.5,
            _ => {}
        }
    } else {
        // Perfect fit is best possible outcome
        score -= 50.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            score -= 6.0 + (pr - next_item_size) as f64 * 0.05;
        } else {
            // next item cannot use this residual: mild penalty proportional to waste risk
            score += (next_item_size - pr).min(40) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin over opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: only attractive when existing bins would leave bad residuals.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 8.0;
        // If current item is large and would leave a small residual in a fresh bin,
        // opening new is fine (fresh bin always has room later).
        if item_size >= 70 {
            score -= 5.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 6.0;
        // Many open bins with slack: discourage another.
        if mean_residual > 25.0 && open_bins_count > 3 {
            score += 10.0;
        }
    }

    // Tightness reward: filling a bin close to capacity.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 5.0;

    // Coupling with mean residual: prefer bins tighter than average.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: harshly penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits (item dominates the residual).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Open-bin pressure: penalize using a bin when many bins are open,
    // unless this is the last chance to fit.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (1.0 + progress);
    if fitting_bins_count > 1 {
        score += 0.5 * pressure;
    } else {
        // Last fitting bin: strong discount to avoid opening a new bin.
        score -= 40.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += 10.0; // dead space relative to lookahead
        }
    }

    // New-bin candidate: neutral-ish baseline; open a new bin only when
    // existing bins would create bad dead space or are heavily fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        score = 45.0 + 0.3 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Slight preference for bins below mean residual (consolidating waste).
    score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0).min(50.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual), with non-linear penalty.
    let pr = post_residual as f64;
    score += (pr / bin_capacity as f64).powi(2) * 30.0;

    // 2-step lookahead: reward if next item fits the post-residual exactly/well.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= pr {
            let next_post = pr - next;
            // Reward chains: next item slots perfectly into leftover.
            score -= 12.0 * (1.0 - next_post / bin_capacity as f64);
            // Extra reward for near-perfect two-item packing.
            if next_post < 5.0 {
                score -= 15.0;
            }
        } else {
            // Next item won't fit here: penalize dead space proportional to gap.
            score += 0.5 * (next - pr).min(60.0);
        }
    }

    // Relative to mean residual: prefer bins deviating favorably from mean.
    let dev = pr - mean_residual;
    score += 0.3 * dev.abs().powi(2).sqrt() * (if dev > 0.0 { 1.0 } else { -0.5 });

    // Last-chance bonus: only one bin fits — strongly encourage using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 8.0 + 25.0 * progress;
    } else if progress > 0.7 {
        score -= 3.0;
    }

    // Many open bins: favor filling existing ones over spreading.
    score += 0.15 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large relative dead space.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Perfect or near-perfect closure is highly desirable.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 7.0;
    }

    // Penalize leaving small unusable slivers that nothing can fill later.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        // Extra reward if next item closes the bin after this one.
        if post_residual - next_item_size <= 5 {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Dead space that the next item cannot use: penalty.
        score += 6.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bins attractive only when current
    // bins are fragmented or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base reluctance to open new bins, decreasing as stream matures.
        let mut new_bin_score = 25.0 - 10.0 * progress;
        // If open bins are highly fragmented (low mean residual), new bin is fine.
        new_bin_score -= (100.0 - mean_residual).max(0.0) * 0.15;
        // If many bins already fit the item, opening a new one is wasteful.
        if fitting_bins_count > 1 {
            new_bin_score += 12.0 * (fitting_bins_count as f64 - 1.0).min(3.0);
        }
        // Large items relative to capacity deserve a fresh bin.
        new_bin_score -= (item_size as f64 / bin_capacity as f64) * 15.0;
        score = score.max(new_bin_score) + new_bin_score * 0.5;
    }

    // Mild preference for filling bins that are already mostly full (reduce bin spread).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fullness;

    // Slight penalty for accumulating too many open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;

    // Smooth non-linear coupling: tight fits rewarded more as stream progresses.
    let tightness = 1.0 - post / cap; // in (0,1], larger = tighter fit
    score -= tightness * tightness * (1.0 + progress) * 12.0;

    // Penalize dead space quadratically, modulated by stream progress.
    score += (post * post) / cap * (0.5 + progress);

    // Lookahead: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = post - nx;
        if slack >= 0.0 {
            score -= 6.0 * (1.0 - (slack / cap).powi(2));
        } else {
            score += (-slack / cap) * 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 15.0 * progress;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += (open_bins_count as f64).ln() * (mean_residual / cap).max(0.0) * 2.0;

    // New-bin candidate: prefer it early or when it would hold more than any open bin.
    if bin_residual == bin_capacity {
        score = post + cap * (1.0 - progress) * 0.3 - item_size as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 as capacity fractions
    let pr = post_residual as i64;
    let cap = bin_capacity as f64;
    let residue = (pr % 10) as f64;
    let quotient = (pr / 10) as f64;

    // Reward post-residuals that sit on "clean" harmonic levels (multiples of 10)
    score -= residue * 0.6;

    // Dead-space penalty: very small post_residual that is nonzero is wasted space
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.5;
    }

    // Perfect fit is excellent
    if pr == 0 {
        score -= 40.0;
    }

    // Next-item coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        let ni = next_item_size as i64;
        if ni <= pr {
            // next item chains nicely; reward proportional to fill of remaining space
            score -= (ni as f64 / pr as f64) * 12.0;
            // extra reward if chained post-residual lands on harmonic level
            let pr2 = pr - ni;
            if pr2 % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit; penalize more if leftover residue is awkward
            score += residue * 0.8;
            if pr < ni && pr > 0 {
                score += 8.0;
            }
        }
    } else {
        // last item: prefer tightest packing
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = mean_residual / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // base cost of opening a bin, discounted when open bins are nearly full
        let cost = 55.0 - crowded * 45.0 - progress * 10.0;
        score += cost.max(0.0);
        // if next item is large and mean residual is small, opening is fine
        if next_item_size as f64 > mean_residual {
            score -= 10.0;
        }
    } else {
        // prefer bins below mean residual (more packed bins absorb items)
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        } else {
            score += 2.0;
        }
    }

    // Integer-division threshold on post_residual: quarters of capacity
    let quarter = (cap / 4.0) as i64;
    if pr >= quarter && pr < 2 * quarter {
        score -= 4.0; // sweet-spot leftover zone
    } else if pr >= 3 * quarter {
        score += 3.0; // too much left = bin was underused
    }

    // Mild exploration term driven by step progression and open bin count
    score -= ((step_index % 7) as f64) * 0.1;
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
