    } else if post_residual < 10 {
        score -= 25.0;
    } else if post_residual < 20 {
        score -= 10.0;
    }

    // Penalize dead space relative to typical item sizes (1..=100 unknown).
    score += (post_residual as f64 / 100.0) * (post_residual as f64 / 100.0) * 20.0;

    // Last chance: this is the only bin that fits; strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item is huge
    // and would leave an awkward remainder in any existing bin.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + 2.0 * open_bins_count as f64;
        if item_size > 60 {
            penalty *= 0.4;
        }
        // Late in the stream, avoid spawning extra bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty *= 1.0 + 1.5 * progress;
        score += penalty;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; slight penalty proportional to gap.
            score += 3.0;
        }
    }

    // Coupling with global mean residual: prefer bins below the mean residual
    // (fill the emptier-feeling bins less aggressively, keep tight bins tight).
    score -= (mean_residual - post_residual as f64) * 0.15;

    // Mild preference for bins that are already substantially filled.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 12.0 * poly;

    // Penalize large dead space more as stream progresses
    score += 8.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post residual) especially with lookahead synergy
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (next_item_size as f64 / cap) * (1.0 - norm_pr);
    } else if next_item_size > 0 {
        score += 2.0 * norm_pr;
    }

    // Last-chance bonus: only one fitting bin -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Slight penalty when bin is far below mean residual (unbalanced bins)
    score += 0.5 * (mean_residual - pr).max(0.0) / cap;

    // Mild new-bin aversion early, more openness late
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.05;

    // Harmonic class of post_residual: residuals in small classes are dead space
    let cls = post_residual / 10; // 0..10 harmonic classes
    score += match cls {
        0 => -8.0,           // near-perfect fit
        1 => -4.0,           // very small dead space, likely reusable by small items
        2 => -1.0,
        3 => 0.5,
        4 => 1.0,
        5 => 2.0,            // ~50 residual: awkward middle zone
        6 => 2.5,
        7 => 3.0,
        8 => 4.0,
        9 => 5.0,
        _ => 6.0,            // nearly empty bin used for one item: wasteful
    };

    // Next-item lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        score -= (10.0 - (gap as f64).sqrt()) * 0.8;
        // Perfect chaining bonus
        if gap == 0 {
            score -= 6.0;
        }
    } else if next_item_size > post_residual {
        // next item can't chain here; penalize mildly if residual becomes dead
        if post_residual < 10 && post_residual > 0 {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // Penalty when many bins fit but this one is a poor fit: encourage consolidation
    if fitting_bins_count > 3 && post_residual > 30 {
        score += 2.0;
    }

    // Progress-aware: early in stream, keep bins balanced (favor bins near mean residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * (0.10 * (1.0 - progress) + 0.02);

    // Late in stream: prefer filling existing bins tightly over opening new ones
    if progress > 0.7 && bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 15.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 4.0;  // last-chance bin exists; prefer it
        } else {
            score += 6.0 + 0.5 * open_bins_count as f64; // keep using open bins
        }
    }

    // Modulo structure: residuals divisible by common item sizes (10/20/25/50) are reusable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 2.0; }
        if post_residual % 25 == 0 { score -= 1.5; }
        if post_residual % 50 == 0 { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        // Marginal zone: usable only by the smallest items.
        score += 12.0;
    }

    // Reward tight fits (perfect or near-perfect packing).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Penalize leaving a gap that exactly matches the next item only mildly (good),
    // but penalize heavily if next item cannot fit the post residual and gap is small.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // lookahead fits, chaining possible
        } else if post_residual > 0 {
            score += 8.0;  // lookahead blocked, gap likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing ones rather than opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.8 * (0.5 + progress);

    // Mean residual coupling: prefer bins with residual below mean (filling tighter bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral-ish baseline; only attractive when it beats
    // a poor fit. Penalize opening new bins when plenty are open.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual < 5 {
        score -= 30.0;
    } else if post_residual < 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // extra reward if next item nearly fills the bin afterwards
        let post2 = post_residual - next_item_size;
        if post2 < 10 {
            score -= 20.0;
        }
    }

    // Penalize leaving dead space the next item cannot use
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        let waste = post_residual as f64 / 20.0;
        score += waste;
        // if next item could have fit in bin_residual but not post_residual, penalize
        if bin_residual >= next_item_size {
            score += 10.0;
        }
    }

    // Penalize large post_residual relative to mean residual (fragmentation)
    if post_residual as f64 > mean_residual + 20.0 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are poor
    if bin_residual == bin_capacity {
        score += 60.0;
        // allow new bin early in stream or when lookahead is huge
        if next_item_size > item_size && next_item_size > 60 {
            score -= 30.0;
        }
    }

    // Late-stream: prefer consolidating into existing bins
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.7 {
        score += post_residual as f64 * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post-residual is already base; amplify non-linearity)
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 30.0;

    // Penalize dead space that cannot fit the smallest plausible item
    if post_residual < item_size {
        score += 12.0; // creating unusable sliver
    }

    // Lookahead: reward if next item fits in post residual (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; penalize more if post_residual is a big wasted chunk
            score += (post_residual as f64 - next_item_size as f64).max(0.0) * 0.3;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Global state: many open bins -> prefer filling existing ones, discourage new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += pressure * 0.5;

    // New-bin candidate handling: empty bin gets a dynamic penalty
    if bin_residual == bin_capacity {
        let early = 1.0 - progress;
        // early in the stream, opening bins is cheap; late, prefer existing bins
        score += 10.0 + 25.0 * progress;
        // but if mean residual across bins is small, opening a bin is reasonable
        score -= mean_residual * 0.1 * early;
    }

    // Prefer bins whose residual is close to item_size (perfect-ish fit)
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.4;

    // Slight time decay: later in stream, be more greedy toward small post residuals
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post-residual with smooth polynomial decay of its usefulness
    let mut score = pr;
    score += 12.0 * pr_norm * pr_norm * cap * (0.5 + progress);

    // Dead-space penalty: residuals too small to be useful later
    let useless = ((0.5 * cap - pr) / cap).max(0.0);
    score += 30.0 * useless * useless;

    // Smooth interaction: post-residual vs. next item lookahead
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).abs();
        let match_bonus = 1.0 - (gap / cap).min(1.0);
        score -= 18.0 * match_bonus * match_bonus * (1.0 - progress);
    } else {
        // Last item: prefer tightest fit strongly
        score -= 20.0 * (1.0 - pr_norm);
    }

    // Last-chance bin: reward using it when few fitting bins remain
    if fitting_bins_count <= 1 {
        score -= 15.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Mild preference against fragmenting bins above mean residual
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev;

    // Crowding: with many open bins, prefer filling existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: penalize slightly unless current bin is a bad fit
    if bin_residual == bin_capacity {
        let poor_fit = ((bin_residual - item_size) as f64 / cap).min(1.0);
        score += 8.0 * (1.0 - poor_fit) * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions.
    let cap = bin_capacity as f64;
    let item_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Dead-space penalty: post_residual below smallest item threshold is waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Harmonic residue classes on post_residual: residues near capacity fractions
    // (25, 50, 75) are reusable by mid-size items, reward them.
    let r = post_residual % (bin_capacity / 4);
    if post_residual >= 25 && post_residual <= 50 {
        score -= (50 - post_residual) as f64 * 0.3; // moderate residual sweet spot
    }
    if r == 0 && post_residual > 0 {
        score -= 5.0; // quarter-aligned residual is harmonically reusable
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only open a new bin when the item is large and
    // no open bin offers a tight fit, or stream is early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tightness = post_frac; // = 0 for new bin minus item; residual = cap-item
        // Penalize new bins generally; discount if current item is big and
        // next item can combine with the leftover space harmonically.
        let mut new_bin_penalty = 45.0;
        if item_frac > 0.5 {
            new_bin_penalty -= 10.0;
        }
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            new_bin_penalty -= 8.0;
        }
        if progress < 0.15 {
            new_bin_penalty += 10.0 * (0.15 - progress) * 10.0; // keep bins open early
        }
        score += new_bin_penalty;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Prefer bins with residual below mean (denser bins first).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Slight preference for fewer open bins late in stream.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps disproportionately.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Reward perfect and near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // If lookahead item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 80.0;
        } else if gap < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Lookahead cannot use the leftover; treat leftover as dead space.
        score += 12.0;
    }

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open bins pressure: more open bins -> prefer filling existing ones over new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // New-bin candidate: make it unattractive unless post_residual of alternatives is hopeless.
    if bin_residual == bin_capacity {
        score += 40.0 + mean_residual * 0.5;
    } else {
        // Slight preference for bins tighter than the mean (better consolidation).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect (or near-perfect) fit
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 15 {
        score -= 40.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0; // chain fit: two items exactly fill the bin
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // prefer small slack after the hypothetical next placement
            score -= 150.0 - slack * 0.8;
            if slack <= 5.0 {
                score -= 60.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.6;
        }
    } else {
        // last item: just minimize post_residual
        score -= 50.0;
    }

    // Compare residual against mean residual across open bins
    let res = post_residual as f64;
    if res < mean_residual - 20.0 {
        score -= 25.0; // tighter than average: good consolidation
    } else if res > mean_residual + 20.0 {
        score += 15.0; // leaving a large hole relative to peers
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large and
    // no open bin offers a decent fit
    if bin_residual == bin_capacity {
        let base = 60.0;
        let lookahead_penalty = if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            0.0 // pairing large items together in a fresh bin can be fine
        } else {
            40.0
        };
        score += base + lookahead_penalty
            + (open_bins_count as f64) * 2.0
            + (item_size as f64) * 0.3;
    }

    // Slight progression term: late in the stream, be more conservative about waste
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: squared dead-space penalty scaled by capacity.
    score += (post_residual as f64 / cap) * (post_residual as f64) * 0.5;

    // Reward bins whose residual is close to the item (best-fit style).
    let waste = (bin_residual as f64 - item_size as f64).abs();
    score += waste * 0.3;

    // Lookahead: if the next item fits into the post residual, reward strongly.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 8.0 + 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize leaving a sliver the next item cannot use.
        score += 4.0 * (1.0 - post_residual as f64 / cap);
    }

    // Last-chance bonus: only one bin fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Early in stream: keep bins flexible (avoid tiny residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.3 {
        score += post_residual as f64 * 0.2;
    }

    // Global mean residual coupling: bins far below mean residual are worth filling.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // New-bin candidate: only attractive if the item is large relative to capacity.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score = cap * 0.6 - big_item * cap * 0.5 + (1.0 - big_item) * 20.0;
        if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = 1.0 - (post_residual as f64 / cap); // how full bin becomes

    // Reward tight fits more strongly as the stream progresses (smooth polynomial coupling)
    let tight_reward = fit_ratio.powi(3) * (20.0 + 30.0 * progress);
    score -= tight_reward;

    // Penalize dead space quadratically, scaled by mean residual context
    let dead = post_residual as f64;
    score += (dead * dead) / cap * (0.5 + 0.5 * (1.0 - progress));

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: if next item fits exactly in the post residual, reward; else mild penalty
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.15;
        } else {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        }
    }

    // New-bin candidate shaping: only attractive when open bins are crowded or residual is large
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / cap).powi(2);
        score = cap - 10.0 * crowding * (0.3 + 0.7 * progress) - 5.0 * progress;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild dispersion penalty: prefer bins far from the mean residual early, near it late
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residues divisible by common
    // item sizes are more reusable than awkward dead space.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        60.0 // perfect fit is ideal
    } else if pr <= 5 {
        40.0
    } else if pr % 10 == 0 {
        25.0 // residue matches the classic item-size grid
    } else if pr % 5 == 0 {
        12.0
    } else if pr % 3 == 0 {
        6.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Lookahead coupling: reward residues that can host the next item exactly
    // or as a harmonic class match.
    if next_item_size > 0 {
        let n = next_item_size;
        if pr >= n {
            let gap = (pr - n) as f64;
            if gap == 0.0 {
                score -= 35.0;
            } else if (pr - n) % 10 == 0 {
                score -= 18.0;
            } else if gap <= 10.0 {
                score -= 10.0 * (1.0 - gap / 10.0);
            } else {
                score -= 4.0;
            }
        } else {
            // next item cannot follow here; slight penalty proportional to waste
            score += 5.0;
        }
    }

    // Penalize creating large unusable dead space (below the minimum item size
    // of 1 but above typical small-item zones) — non-linear waste curve.
    if pr > 0 {
        let frac = pr as f64 / cap;
        if frac < 0.1 {
            score += 8.0 * (1.0 - frac / 0.1); // tiny leftovers are cheap, mild reward instead
        } else if frac > 0.5 {
            score += 6.0 * frac; // leaving more than half a bin empty is wasteful
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding
    // opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when open bins
    // are badly fragmented. Penalize the fresh bin by the mean residual
    // (if open bins still hold lots of space, prefer them), plus a fixed
    // opening cost that decays as the stream matures.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 + 0.3 * mean_residual + 10.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    }

    // Prefer denser bins (small residual relative to mean) to consolidate load.
    score += 0.15 * (mean_residual - bin_residual as f64).max(0.0);

    // Late-stream tightening: as the stream ends, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.25 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward residual that can still host a typical future item.
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage proliferation of bins when many are open.
    score += (open_bins_count as f64) * 0.35;

    // Coupling with mean residual: placing into a bin far above mean wastes spread.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would leave yet another tiny gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size && (post_residual - next_item_size) < 10 && (post_residual - next_item_size) > 0 {
        score += 12.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., when this empty bin is the candidate and residuals are fragmented).
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.8;
        score += 10.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    }
    // Next item fits with a little slack left.
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 50.0;
    }
    // Next item won't fit: dead space risk penalty, worse for tiny residuals.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + (post_residual as f64).min(30.0);
    }

    // Penalize small unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: make it unattractive unless existing bins are all bad fits.
    if bin_residual == bin_capacity {
        score += 250.0;
        // Late in stream, opening new bins is fine.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.9 {
            score -= 100.0;
        }
    }

    // Compare against mean residual: bins far below mean (tight) are good targets.
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Slight preference for tighter bins generally.
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space, more strongly for small post-residuals that become unusable.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 3.0 } else { 0.0 };
        score += dead * (post_residual as f64).sqrt();
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.0 * tightness * tightness * (item_size as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 + (next_item_size as f64) * 0.1;
        } else {
            // Waste of residual if next item cannot use it.
            score += 2.0;
        }
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when current bins are crowded
    // or the fit is very poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let crowded = open_bins_count as f64 / 20.0;
        let poor_fit = (item_size as f64) / (bin_capacity as f64);
        // Prefer new bin when item is large, many bins open, or mean residual low.
        score += 6.0 - 8.0 * poor_fit - crowded - 2.0 * (1.0 - progress);
        if mean_residual < (item_size as f64) + 5.0 {
            score -= 5.0; // existing bins are tight; opening new bin is good
        }
    } else {
        // Favor reusing open bins generally, more when many bins are already open.
        score -= 1.0 + (open_bins_count as f64) * 0.05;
    }

    // Spread-awareness: if bin residual deviates from mean, slight normalization.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if progress > 0.8 {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; late, penalize large residuals strongly.
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * pr * pr * (0.5 + progress);

    // Reward near-perfect fits with a smooth bump.
    let fit_quality = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fit_quality * fit_quality;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // If the next item fits exactly into the post-residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // Smooth penalty if post-residual is slightly too small for the next item (dead space).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap < 0.0 {
            score += 8.0 * (-gap / 50.0).exp() * gap.abs().min(50.0) / 50.0;
        }
    }

    // Prefer bins with residuals deviating from the mean (consolidate slack).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (dev / bin_capacity as f64).sqrt();

    // Mild penalty for opening new bins when many are open.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality tiers.
    // post_residual in [0,100]. Class it by integer division thresholds.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: heavily reward.
        score -= 1000.0;
    } else if pr <= 10 {
        // Near-perfect: still excellent.
        score -= 300.0;
    } else {
        // Harmonic class: how many future items of average size could fill it.
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Dead space penalty grows with how "orphan" the residual is.
        // Classes: (11..=20), (21..=35), (36..=50), (51..=100)
        let class = if pr <= 20 { 1 } else if pr <= 35 { 2 } else if pr <= 50 { 3 } else { 4 };
        score += class as f64 * 40.0;

        // Modulo arithmetic on residual: residuals that align with common
        // item-size fractions of capacity (multiples of 10, 20, 25) are
        // more likely to be filled later.
        let harmonic = (pr % 10 == 0) || (pr % 20 == 0) || (pr % 25 == 0);
        if harmonic {
            score -= 60.0;
        } else {
            score += 25.0;
        }

        // Small residuals that can't hold the smallest plausible item (>=10)
        // are pure dead weight: penalize strongly.
        if pr < 10 {
            score += 500.0;
        }

        // Lookahead coupling: if next item fits exactly into post_residual,
        // this is a golden chain placement.
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 400.0;
            } else if next_item_size < pr {
                score -= (pr - next_item_size) as f64 * 0.5;
            } else {
                // Next item won't fit here: residual becomes a waiting cost.
                score += 30.0;
            }
        }

        // Last-chance bin: if this is the only bin that fits, avoid opening
        // a new bin unless the residual would be terrible.
        if fitting_bins_count == 1 {
            score -= 120.0;
        }

        // Late in the stream, tighten up: prefer compact packing.
        score += progress * 50.0;

        // Prefer bins with residuals below the mean (denser bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 20.0;
        } else {
            score += 10.0;
        }
    }

    // New-bin candidate: only attractive when no open bin gives a decent fit
    // (i.e., all fits leave big residuals). Empty bin residual = 100.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // But if the current best alternative would leave a large residual,
        // opening fresh is competitive: reward when item is large relative
        // to capacity (large items pack cleanly into fresh bins).
        let frac = item_size as f64 / bin_capacity as f64;
        if frac > 0.7 {
            score -= 180.0;
        }
        // With many open bins, opening more is riskier.
        score += open_bins_count as f64 * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to hold even the smallest
    // plausible future item are nearly worthless; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 18.0;
    } else if post_residual == 0 {
        // Perfect fill: strongly reward closing the bin.
        score -= 120.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward heavily; if it cannot fit, mildly penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.4 * slack;
        } else {
            score += 8.0;
        }
    }

    // Pressure term: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += open_bins_count as f64 * 1.5;

    // Mean residual coupling: placing into a bin far below the mean
    // residual leaves other bins' slack stranded; encourage balancing.
    score += 0.5 * (mean_residual - bin_residual as f64).abs();

    // Last-chance bin: if this is the only bin that fits, strongly
    // prefer using it over opening a fresh bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: make the empty bin moderately attractive so it
    // wins only when existing bins have poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
    }

    // Late in the stream, tighten up: less room for sloppy placements.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact matching of post_residual with next_item_size (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is highly desirable.
        if gap == 0.0 {
            score -= 60.0;
        } else {
            score += gap * 0.35;
        }
        // Penalize post_residual that is too small to fit the next item (dead space).
        if (next_item_size as u32) > post_residual {
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    } else {
        // Last item: strongly prefer the tightest fit.
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer bins whose residual is tighter than the mean residual (good consolidation).
    let resid_f = bin_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.25;
    } else {
        score += (resid_f - mean_residual) * 0.15;
    }

    // Penalize large leftover dead space quadratically (small fragments are unusable).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 2.0;
    }

    // Slight preference for keeping the number of open bins bounded as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 10 {
        score += progress * 3.0;
    }

    // Brand-new empty bin candidate: only attractive when residual space is very tight
    // (i.e., item is huge relative to capacity); otherwise discourage opening new bins.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.85 {
            score -= 25.0;
        } else {
            score += 15.0 + (1.0 - fill_ratio) * 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress of the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Is this the brand-new empty bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect fit reward: strongly favor bins that get exactly filled.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize dead space non-linearly: small residuals are hard to reuse.
        let dead = post_residual as f64;
        score += dead * dead / bin_capacity as f64 * 0.5;

        // If next item can fit into post_residual, reward leaving that gap.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 30.0 + 0.5 * next_item_size as f64;
        }
        // If next item cannot fit in this residual but could fit a tighter gap, slight penalty.
        if next_item_size > post_residual && next_item_size > 0 && post_residual < next_item_size {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when the item
    // fits poorly everywhere else. Base cost for opening a new bin grows with
    // the number of open bins and stream progress (consolidation pressure).
    if is_new_bin {
        let open_cost = 40.0 + 8.0 * open_bins_count as f64 * (0.3 + 0.7 * progress);
        score += open_cost;
        // Large items (>= 60% of capacity) are fine to start a fresh bin.
        if item_size * 5 >= bin_capacity * 3 {
            score -= 50.0;
        }
        // Late in the stream, discourage proliferating bins.
        score += 60.0 * progress;
    } else {
        // Reward tight fits relative to mean residual state of the system.
        if (mean_residual - post_residual as f64).abs() < 5.0 {
            score -= 5.0;
        }
        // Slight preference for bins below the mean residual (tighter bins first).
        if (post_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Early stream: be slightly conservative, keep bins balanced for flexibility.
    if progress < 0.2 && !is_new_bin {
        score += 0.05 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    // Normalized post-residual
    let x = pr / cap;
    // Smooth non-linear polynomial coupling with stream progress
    let poly = x * x - 2.0 * x * progress + x * (1.0 - progress);
    let mut score = pr + 10.0 * poly * cap;
    // Penalize tiny dead space that becomes unusable (smooth via cubic)
    let dead = (1.0 - x).min(1.0).max(0.0);
    score += 8.0 * dead * dead * dead * cap * (0.3 + 0.7 * progress);
    // Lookahead: reward leaving room for next item (smooth quadratic mismatch)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (1.0 - gap / cap);
    } else {
        score += 4.0 * x;
    }
    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }
    // Mild penalty when bin diverges from mean residual (encourage balance)
    score += 0.15 * (pr - mean_residual).abs();
    // New-bin candidate: penalize slightly more as stream progresses
    if bin_residual == bin_capacity {
        score += 3.0 + 5.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: perfect fits (0) are ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Dead-space penalty: residuals in the "unusable sliver" class.
    // Residuals 1..10 (below min item size) are dead space -> strong penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 are "harmonic"
    // (likely reusable by future items); reward them.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    // Integer-division tier of post_residual: how many 25-sized chunks fit.
    let chunks = post_residual / 25;
    score -= chunks as f64 * 5.0;

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            // harmonic compatibility: next item leaves harmonic residue
            let nr = post_residual - next_item_size;
            if nr % 10 == 0 {
                score -= 12.0;
            }
            score -= (nr as f64) * 0.15;
        } else {
            // next item cannot use this bin's residue: mild penalty scaled
            // by how badly it misses (integer division gap)
            let gap = next_item_size - post_residual;
            score += gap.min(20) as f64 * 0.5;
        }
    }

    // Capacity-fraction thresholds: reward filling past key fractions.
    let fill_frac = (bin_residual as f64) / cap;
    if fill_frac > 0.75 {
        score -= 10.0;
    } else if fill_frac > 0.5 {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early stream: be generous with bins; late stream: pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress);

    // New-bin candidate (empty bin): penalize unless residual pressure is high.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 * item_size as f64 / cap;
        score += 12.0 - pressure.min(12.0);
        // open new bin early if current item is large and mean residual is fragmented
        if mean_residual < item_size as f64 && item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps below the minimum item size
    // (1..=5 units) are completely wasted -> heavy penalty.
    if post_residual > 0 && post_residual <= 5 {
        score += 40.0;
    }
    // Small unusable-ish gaps (6..=10) are also likely dead space.
    else if post_residual > 0 && post_residual <= 10 {
        score += 15.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer
    // filling existing bins; few open bins -> new bins are cheaper.
    let ob = open_bins_count as f64;
    score += 0.8 * ob;

    // New-bin candidate handling: only attractive when item is large and
    // current bin fits are poor (high mean residual left after placement).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 + 15.0 * progress;

        // If the next item could combine with the leftover of the best
        // existing placement, discourage opening a new bin.
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 25.0;
        }
        // Large items starting fresh bins are fine early on.
        if item_size >= 60 {
            score -= 10.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for blocking.
        score += 3.0;
    }

    // Coupling with mean residual: prefer bins whose post residual stays
    // near the mean (balanced packing) when many bins are open.
    score += 0.3 * (post_residual as f64 - mean_residual).abs() * (ob / (ob + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step match: post_residual equals next item size -> perfect chain.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Near-exact match (small slack) still strongly rewarded.
    else if next_item_size > 0 && post_residual > next_item_size && post_residual - next_item_size <= 5 {
        score -= 400.0 - 50.0 * (post_residual - next_item_size) as f64;
    }

    // Penalize dead space: post_residual too small for next item and below
    // the minimum possible item size => likely wasted capacity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 150.0;
        if post_residual < 10 {
            score += 100.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer bins tighter than the average residual (good fits).
    score += (mean_residual - post_residual as f64) * 0.5;

    // Relative fill quality: reward small post_residual vs capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 30.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline, slightly penalized so we prefer
    // existing bins unless their scores are bad (dead-space penalties above).
    if bin_residual == bin_capacity {
        score += 120.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor small post_residual, superlinear.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect or near-perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Last chance: only bin that fits — avoid opening a new bin unless residual is bad.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post-residual, reward; if it would
    // exactly fill, extra reward; if next item can't fit anywhere else, prefer saving space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
            if next_item_size == post_residual {
                score -= 30.0;
            }
        } else {
            // Next item won't fit here anyway; slight penalty for leaving awkward gaps.
            score += 3.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit
    // (large post_residual) or item is huge relative to residual.
    if bin_residual == bin_capacity {
        let waste_penalty = 40.0 + 0.5 * mean_residual;
        // Opening fresh bin is fine when open bins are fragmented.
        score += waste_penalty;
        if open_bins_count > 0 {
            // If any existing bin fits well (post_residual small), new bin should lose.
            score += 10.0 * (item_size as f64 / bin_capacity as f64);
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    // Penalize bins whose residual is far below the mean (fragmented outlier)
    // unless this placement fixes it.
    let frag = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * frag;

    // Many open bins: encourage consolidation into already-open bins.
    score += 0.15 * open_bins_count as f64;

    // Prefer placing large items into bins with proportionally small residual slack.
    let slack_ratio = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * slack_ratio * (item_size as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit = pr / cap;

    // Base: prefer tight fits, with non-linear (quadratic/cubic) coupling to progress
    let mut score = pr + 30.0 * fit * fit * cap * (1.0 - progress);

    // Penalty for dead space that shrinks as stream progresses (waste less late)
    score += 12.0 * fit * fit * fit * cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 8.0 * (nxt / cap) * (1.0 - fit);
        } else {
            score += 6.0 * fit;
        }
    }

    // Smooth coupling with mean residual: prefer bins near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev * (0.5 + progress);

    // Mild penalty for opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (fitting_bins_count as f64 / (open_bins_count.max(1) as f64 + 1.0));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Harmonic class of the post residual (dead-space classes) ----
    // Class 0: perfect fit (post_residual == 0) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Dead-space quality: residuals that are likely fillable by small items
        // (1..=20 typical small item sizes) are "harmonically useful".
        let pr = post_residual;
        if pr <= 20 {
            score -= 60.0; // usable small residual
        } else if pr <= 50 {
            score -= 20.0; // medium residual
        } else {
            score += 40.0; // large residual: wasteful, could have used a worse bin
        }

        // Modulo arithmetic: residuals that are multiples of common item
        // granularities (10, 25, 50) are more likely to be exactly filled later.
        if pr % 10 == 0 {
            score -= 25.0;
        }
        if pr % 25 == 0 {
            score -= 15.0;
        }
        if pr % 50 == 0 {
            score -= 10.0;
        }

        // Integer-division threshold: how many "average future items" fit in residual
        let avg_item = 55.0_f64.max(1.0); // rough midpoint of 10..100 range
        let fits_k = (pr as f64 / avg_item).floor() as i32;
        score -= 12.0 * fits_k as f64;
    }

    // ---- Lookahead coupling (k=2): does next item fit in post residual? ----
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Chain bonus, stronger for exact or near-exact chain fit
            let slack = post_residual - next_item_size;
            score -= 70.0;
            if slack == 0 {
                score -= 120.0; // perfect two-item packing
            } else if slack <= 15 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: mild penalty, worse if residual is tiny
            let waste = post_residual.min(next_item_size.saturating_sub(1)) as f64;
            score += 0.15 * waste;
        }
    } else {
        // Last item: prefer tightest possible fit
        score += 0.0;
    }

    // ---- Last-chance logic: this is the only bin that fits ----
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 90.0; // avoid opening a new bin unnecessarily
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost so it's only chosen when open bins fit badly.
        score = 150.0 + post_residual as f64 * 0.5;

        // A new bin is attractive if the item is large relative to capacity
        // (few open bins could take it well) or if open bins are very full.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 60.0 * fill_ratio;

        // If mean residual of open bins is small (bins nearly full), new bin is fine.
        if mean_residual < 25.0 {
            score -= 50.0;
        }
        // If many bins fit the item, keep using them instead.
        if fitting_bins_count > 2 {
            score += 80.0;
        }
        // Lookahead: a fresh bin guarantees room for the next item too.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 55.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    // ---- Mild preference for fuller bins among equals ----
    score += 0.05 * (bin_capacity - bin_residual) as f64 * -1.0;

    // ---- Open-bin count pressure: discourage bin proliferation early ----
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps (1..=12) are almost unusable
    // for future items (sizes >= 1, but realistically small fragments waste
    // capacity). Penalize them hard, super-linearly.
    if post_residual > 0 && post_residual <= 12 {
        score += (13 - post_residual) as f64 * 8.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward placements that leave a gap still usable by the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.25 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap too small for lookahead: mild penalty (potential dead space).
        score += 4.0;
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins when
    // residuals are already low; encourage new bins when open bins are full.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (1.0 - progress) * 0.6;
    if bin_residual < bin_capacity {
        score += pressure;
    } else {
        // New-bin candidate: base cost plus pressure scaled by how full the
        // average open bin is. Prefer new bin when mean residual is small.
        score += 5.0 + pressure * 0.5 - mean_residual * 0.15;
    }

    // Mild deviation from mean residual: prefer bins with residual close to
    // item needs, penalize outliers to keep residuals homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: neutral anchor so that only genuinely
    // poor fits among open bins lose to it.
    if bin_residual == bin_capacity {
        return 55.0 + item_size as f64 * 0.15;
    }

    // Aggressive 2-step lookahead: reward exact / near-exact chaining
    // of post_residual with the next item's size.
    if next_item_size > 0 {
        let diff = next_item_size as i64 - post_residual as i64;
        if diff == 0 {
            score -= 45.0; // perfect chain: next item exactly fills this bin
        } else if diff.abs() <= 2 {
            score -= 28.0; // near-perfect chain
        } else if diff > 0 {
            // Next item does NOT fit after this placement: residual is
            // dead space for the lookahead; penalize proportionally.
            if post_residual < 10 {
                score += (10 - post_residual) as f64 * 2.5;
            } else {
                score += diff as f64 * 0.05;
            }
        } else {
            // Next item fits but leaves another residual; mild reward
            // scaled by how much slack remains for the chain.
            score -= (-diff as f64).min(20.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins that are already tighter than the fleet average
    // (best-fit style consolidation).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for consolidation when many bins are open.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize post_residual that is too small to be useful later
    // (dead space): unusable if smaller than the smallest plausible item.
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item can't use leftover: mild penalty scaled by waste
            score += 4.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening
    // a new bin unless fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 + 8.0 * tightness;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well. Penalize new bins mildly so existing good fits win.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If many bins are open already, discourage fragmentation.
        score += 0.5 * open_bins_count as f64;
    }

    // Global state: if mean residual is large, bins are loose; prefer
    // consolidating into fuller bins (small residual).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Prefer bins that are already substantially filled.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: tight fits matter more late in stream
    let tightness = 1.0 - norm_pr; // 1 = perfect fit
    score -= 30.0 * tightness * (0.5 + progress);
    score -= 25.0 * tightness * tightness * (1.0 - progress);

    // Lookahead coupling: reward residuals that can host the next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 15.0 * (n - pr) / cap;
        }
    }

    // Last-chance bin before opening a new one: strong smooth reward scaled by progress
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.4 + 0.6 * progress);
    }

    // Penalize spreading across many open bins relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Mild penalty for opening new bins when many exist (smooth in progress)
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: waste granularity in capacity fractions
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Dead-space penalty grows superlinearly for tiny unusable residuals
    if post_residual > 0 {
        let unusable = (1..=post_residual).count(); // conceptual; avoid loop cost
        let _ = unusable;
        let frac = post_f / cap_f;
        // penalize residuals that no typical item can fill: classes mod 10
        let class = post_residual % 10;
        if class != 0 {
            score += (10 - class) as f64 * 1.5; // distance to next decile boundary
        }
        score += 40.0 * frac * frac; // quadratic waste penalty
    }

    // Perfect fit is a jackpot
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class match: does next_item_size exactly fit the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward leaving residuals in friendly classes (multiples of 10 / 5)
            if nxt_post % 10 == 0 {
                score -= 40.0;
            } else if nxt_post % 5 == 0 {
                score -= 15.0;
            }
            // penalize if next item would leave a tiny orphan
            if nxt_post > 0 && nxt_post < 10 {
                score += 25.0;
            }
        } else {
            // next item cannot fit here: mild penalty since bin strands
            score += 10.0;
        }
    } else {
        // last item: only perfect fit matters
        if post_residual > 0 {
            score += 20.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Prefer tighter bins relative to the mean residual
    score += (mean_residual - post_f) * 0.5;

    // Early stream: be more liberal opening bins; late stream: consolidate
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: attractive early, discouraged late
        score += 30.0 * progress - 10.0 * (1.0 - progress);
        if open_bins_count > 0 && post_residual > 0 {
            score += 5.0;
        }
    }

    // Slight preference for bins already below mean (compactness)
    if (post_f as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty on small unusable dead space (post_residual < 10 is a waste).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: big reward.
        score -= 60.0;
    }

    // Reward tight fits generally: small post_residual relative to item size.
    score -= 30.0 * (item_size as f64 / bin_residual.max(1) as f64);

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // over opening new bins; penalize the new-bin candidate.
    if bin_residual == bin_capacity {
        score += 20.0 + 5.0 * open_bins_count as f64;
        // But if next item is large and this bin would be a good host, soften slightly.
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0;
        }
    }

    // If mean residual is high, bins are fragmented; favor bins with residual
    // below the mean (consolidating waste) and penalize large-residual bins.
    if bin_residual as f64 > mean_residual {
        score += 8.0;
    } else {
        score -= 4.0;
    }

    // Lookahead: if the next item exactly fits this bin's post_residual,
    // strongly favor this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving awkward gap.
        score += 5.0;
    }

    // Late in the stream, tighten up: prefer minimal post_residual even more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward if next item exactly matches post_residual
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Penalize leaving residual that is too small for next item (dead space)
        if (post_residual as u32) < next_item_size {
            score += 8.0 + 0.2 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer fullest packing
        score -= 20.0;
    }

    // Compare against mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Penalize opening new bins as stream progresses
    if bin_residual == bin_capacity {
        score += 15.0 + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // But a new bin is fine if no tight fit exists anywhere
        if fit_ratio < 0.5 {
            score -= 10.0;
        }
    }

    // Mild penalty for very small unusable residuals
    if post_residual < 10 && post_residual > 0 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize (subtract) when post_residual is small but nonzero.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Strongly reward perfect fill.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space penalty: leftover space too small for typical future items
    // (below the minimum plausible item size is fine, otherwise penalize small slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 0.2 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to wasted lookahead potential.
        score += 3.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
    }

    // Compare against mean residual: placing into a bin with residual far above the mean
    // is efficient (uses the "fattest" bin); placing into a below-mean bin wastes tight bins.
    let res_f = bin_residual as f64;
    if res_f > mean_residual {
        score -= 0.15 * (res_f - mean_residual);
    } else {
        score += 0.15 * (mean_residual - res_f);
    }

    // Time horizon: late in the stream, avoid opening new bins (encourage consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost grows with progress and with many open bins.
        score += 5.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        // Open bins get a discount late in the stream.
        score -= 4.0 * progress;
    }

    // Prefer bins whose residual is close to item_size (minimal waste fit).
    let waste = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 6.0 * waste * waste;

    // Slight preference for bins among many fitting candidates with large residual
    // (best-fit-like behavior is already captured, but add tie-breaking).
    score -= 0.05 * fitting_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual
    let mut score = pr as f64;
    // Smooth polynomial coupling: penalize large leftover space quadratically, modulated by progress
    score += 12.0 * x * x * (1.0 + progress);
    score -= 6.0 * x * (1.0 - progress);
    // Tight fits reward
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fit_ratio * fit_ratio;
    // Dead-space penalty for unusable residue relative to smallest plausible item
    if pr > 0.0 && pr < 10.0 {
        score += 5.0 * (10.0 - pr as f64) / 10.0;
    }
    // Lookahead: reward leaving room for next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 4.0 * (nx / cap);
        } else {
            score += 3.0 * (1.0 - pr / nx.max(1.0));
        }
    }
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }
    // Discourage proliferation of open bins late in stream
    score += 0.15 * open_bins_count as f64 * (0.5 + progress);
    // Prefer bins near mean residual (balance)
    score += 0.05 * (pr - mean_residual).abs();
    // New-bin candidate: penalize mildly so we prefer reusing decent fits
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals divisible into small
    // denominations (10, 20, 25, 50) are more likely reusable by future items.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit: best possible outcome
    } else if pr % 50 == 0 {
        -25.0
    } else if pr % 25 == 0 {
        -15.0
    } else if pr % 10 == 0 {
        -10.0
    } else if pr % 5 == 0 {
        -4.0
    } else {
        6.0 // awkward residual
    };
    score += harmonic_bonus;

    // Dead-space penalty: residual too small for the minimum item size.
    if pr < 10 && pr > 0 {
        score += 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // strongly favor this bin; if next item cannot fit, penalize mildly.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            if (post_residual as u32) % next_item_size.max(1) == 0 {
                score -= 20.0; // next item would close this bin perfectly
            } else {
                score -= 8.0;
            }
        } else {
            score += 5.0;
        }
        // Harmonic class of next item vs residual granularity
        if next_item_size % 10 == 0 && pr % 10 == 0 {
            score -= 5.0;
        }
        let _ = nx;
    }

    // Last-chance bin: only one open bin can fit the item -> avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize so we only open when fits are truly poor.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.15 * open_bins_count as f64;
        // But if current item leaves a harmonic residual class in a fresh bin
        // (i.e. item size itself is harmonic), soften the penalty.
        if item_size % 25 == 0 || item_size % 50 == 0 {
            score -= 12.0;
        }
    }

    // Prefer tighter bins overall: compare residual to mean residual.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Late-stream tightening: as stream progresses, prefer near-closed bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10) are pure waste.
    if post_residual < 10 {
        score -= 500.0; // perfect or near-perfect fill is excellent
    } else if post_residual < 20 {
        score -= 150.0; // likely unusable gap -> but it means tight fit; still reward
    } else if post_residual < 30 {
        score -= 30.0;
    }

    // Reward relative tightness (fraction of bin consumed).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving a gap that no realistic item (10..80) can use well:
    // a residual in (30, 50) is hard to pair with typical items.
    if post_residual > 30 && post_residual < 50 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += (open_bins_count as f64) * 2.0;

    // Prefer bins with low residual relative to the mean (already committed bins).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack < 10 {
            score -= 120.0;
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        score += 40.0; // next item cannot use this gap at all
    }

    // New-bin candidate: neutral-ish baseline; only chosen if no open bin scores well.
    if bin_residual == bin_capacity {
        score += 80.0;
        // Opening a new bin is more acceptable early in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Core dead-space penalty (non-linear: small residuals are very costly)
    if post > 0.0 {
        score += 40.0 / post.sqrt();
    }

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        score -= 25.0 * (-gap / 8.0).exp(); // perfect chain bonus
        // Penalize leaving residual that is too small for the next item (dead space)
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt.max(1.0));
        }
        // Slight reward if post_residual leaves room for next item
        if post >= nxt {
            score -= 6.0;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual
    score += 0.6 * (post - mean_residual);

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Early stream: be pickier (favor opening bins to build structure)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * (post / cap);

    // New-bin candidate: neutral-ish; penalize slightly so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but punish leaving dead space that nothing small can use.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize residuals that are too small to hold anything (dead space).
        if post_residual < 10 {
            score += 25.0;
        } else {
            // Reward residuals that are likely reusable: smooth decay of usefulness.
            let usable = (post_residual as f64 / 40.0).min(1.0);
            score -= 10.0 * usable;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, big bonus.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 45.0;
        } else if post_residual as u32 >= next_item_size {
            score -= 15.0;
        } else {
            // Next item won't fit here; penalize wasting this bin's future.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // Prefer the bin where this item is a relatively better fit among options.
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Global state: many open bins with small mean residual -> consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let consolidation = (mean_residual - post_residual as f64) / bin_capacity as f64;
    score -= 20.0 * consolidation * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));

    // Time horizon: early on, be picky about fits; late, prioritize just using bins.
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let poor_fits = (post_residual as f64 / bin_capacity as f64) > 0.7 && fitting_bins_count <= 2;
        if poor_fits {
            score -= 30.0;
        } else {
            score += 40.0 + 10.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on (progress ~ 0): prefer tight fits mildly (linear in pr).
    // Late (progress ~ 1): strongly prefer minimal post_residual (quadratic).
    let mut score = pr * (1.0 + progress * pr_norm);

    // Smooth non-linear interaction: dead-space penalty grows with fill fraction
    // of the bin already used, coupled with progress.
    let used_norm = (bin_residual as f64) / cap;
    score += 4.0 * progress * (pr_norm * pr_norm) * (0.5 + used_norm);

    // Lookahead term: reward leaving room exactly for the next item
    // (smooth gaussian-like coupling rather than hard equality).
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        let gap_norm = gap / cap;
        score -= 6.0 * (-(gap_norm * gap_norm) * 400.0).exp();
    }

    // Last-chance bonus: if this is the only fitting bin, penalize opening
    // a new bin by discounting this bin's score smoothly.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0 + 2.0 * progress;
    }

    // New-bin candidate handling: make empty-bin score depend on mean
    // residual and open-bin count, so new bins are opened only when
    // existing residuals are fragmented or plentiful.
    if bin_residual == bin_capacity {
        let mean_norm = mean_residual / cap;
        score = cap * (0.9 - 0.25 * progress)
            + 8.0 * mean_norm
            + (open_bins_count as f64).sqrt() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit)
    score += (post_residual as f64).powf(1.5) * 0.05;

    // Harmonic class of post_residual: residues mod 10 — dead space classes
    let residue_class = post_residual % 10;
    let class_penalty = match residue_class {
        0 => -6.0, // perfectly reusable class
        1 | 2 | 3 => 4.0, // awkward slivers
        4 | 5 | 6 => 1.0,
        7 | 8 | 9 => 2.5,
        _ => 0.0,
    };
    score += class_penalty;

    // Integer-division threshold: post_residual bucket by 20s
    let bucket = post_residual / 20;
    score += match bucket {
        0 => -3.0,      // nearly full bin: great
        1 => 0.0,
        2 => 2.0,
        _ => 5.0,       // lots left: wasteful unless new bin
        _ => 0.0,
    };

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin: attractive if open bins are crowded or fit is poor
        let scarcity = if fitting_bins_count <= 1 { 12.0 } else { 0.0 };
        let crowded = (open_bins_count as f64) * 0.8;
        score = 55.0 - scarcity - crowded + mean_residual * 0.3;
        // Late in stream, prefer filling existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // next item won't fit here: penalize leaving moderate dead space
            if post_residual >= 10 && post_residual < next_item_size {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Reward packing into bins with below-average residual (consolidation)
    if bin_residual != bin_capacity {
        score += ((bin_residual as f64) - mean_residual) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals that are too small to hold
    // even the smallest plausible item (<= 10) are wasted space.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward exact fit for the lookahead item (k=2 chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones;
    // with few open bins, opening a new bin is less costly.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate handling: an empty bin has high raw post_residual,
    // which is naturally unattractive; add extra penalty unless open-bin
    // pressure is low or the item would leave big dead space everywhere.
    if bin_residual == bin_capacity {
        score += 35.0 - (open_bins_count as f64) * 3.0;
        // If next item is large, a fresh bin may be strategically good.
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit),
    // measured relative to mean residual of open bins.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    // Early in the stream, be more willing to open bins (less pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 3 {
        score -= 400.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this bin is a perfect two-item chain -> huge reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (nxt - post_residual as f64).abs() < 0.5 {
            score -= 600.0;
        } else if nxt <= post_residual as f64 {
            // next item fits: reward proportional to how tight it is
            score -= 150.0 * (1.0 - (post_residual as f64 - nxt) / cap);
        } else {
            // next item cannot use this residual: penalize dead space
            score += 80.0 * (post_residual as f64 / cap);
        }
    }

    // Compare post_residual against mean residual: leaving this bin below
    // average residual creates fragmented small holes -> penalize.
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: keep it attractive only when the item fits poorly
    // everywhere else (large post_residual elsewhere, or no good lookahead).
    if bin_residual == bin_capacity {
        let base = 0.55 * cap; // neutral threshold for residual after placement
        let mut new_bin_score = base;
        if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
            // placing here wastes a fresh bin that could serve the next item well
            new_bin_score += 60.0;
        }
        if open_bins_count == 0 {
            new_bin_score -= 500.0; // must open a bin
        }
        // As stream progresses, mildly prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score += 50.0 * progress;
        score = score.max(new_bin_score.min(score + 1.0)) * 0.0 + new_bin_score.max(score - 0.0) * 0.0 + if score > new_bin_score { score } else { new_bin_score };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack_after_next = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving medium dead space.
            if post_residual >= next_item_size - 5 && post_residual < next_item_size {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize wasting a nearly-empty bin when many bins are open (fragmentation control).
    let residual_frac = bin_residual as f64 / bin_capacity as f64;
    if open_bins_count > 4 && residual_frac > 0.9 && item_size < 40 {
        score += 6.0;
    }

    // Global state coupling: if mean residual is high, encourage filling bins down.
    score += 0.15 * (mean_residual - post_residual as f64).abs();

    // Time horizon: early in stream, mildly prefer new bins (keep options open);
    // late in stream, prefer packing into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty so it's chosen only when fits are bad.
        score += 20.0;
        score -= 10.0 * (1.0 - progress);
        // If next item is large and this bin is fresh, opening early is fine.
        if next_item_size >= 60 { score -= 8.0; }
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let size_n = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post-residual with stream progress:
    // early on, waste matters less; late in the stream, penalize dead space super-linearly.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * 40.0 * norm_pr * norm_pr;

    // Smooth reward for tight fits (small post_residual relative to capacity)
    score -= 30.0 * (1.0 - norm_pr).powi(3) * size_n;

    // Interaction: large items prefer bins leaving moderate residual for the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_gap = (pr - nxt).abs();
        score -= 15.0 * (-fit_gap / 20.0) * (1.0 - progress);
    }

    // Penalize opening a new bin more as stream progresses (smooth pressure to reuse bins)
    if bin_residual == bin_capacity {
        score += 20.0 + 60.0 * progress;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Mild coupling with mean residual: prefer bins below the mean (tighter bins)
    score += 5.0 * (mean_residual - pr as f64) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this item.
    let fill_frac = item_size as f64 / cap;
    score -= 40.0 * fill_frac;

    // Penalize unusable dead space: post_residual that is small but nonzero
    // (harmonic classes: residuals in low modulo classes are hard to fill).
    let pr = post_residual;
    if pr > 0 {
        if pr < 10 {
            score += 60.0; // tiny sliver, nearly dead space
        } else {
            // Dead-space severity grows as residual shrinks relative to typical item range.
            score += 30.0 * (1.0 - pr as f64 / 80.0).max(0.0);
        }
    } else {
        score -= 50.0; // perfect closure
    }

    // Lookahead: if the next item fits exactly or well into post_residual, reward.
    if next_item_size > 0 && pr > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            score -= 20.0 * (next_item_size as f64 / pr as f64);
        } else {
            score += 10.0; // next item won't fit here; residual likely wasted
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: neutral-to-slightly-high baseline; only open a new bin
    // when no open bin offers a decent fit (score here beats bad fits only).
    if bin_residual == bin_capacity {
        score = 55.0 + 0.05 * open_bins_count as f64;
        // Encourage opening a new bin early in the stream or when open bins are crowded.
        if open_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 10.0; // big item coming; fresh bin useful
        }
    }

    // Mild preference to consolidate when many bins are open.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize gaps too small for typical next items relative to lookahead
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open bins pressure: discourage spreading across many bins
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin bonus: only fitting bin, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: mild penalty so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.4;

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), but not exact-zero waste that
    // could have served a bigger future item — mild bonus for small leftover.
    score += 0.35 * (post_residual as f64).powf(1.25);

    // Aggressive 2-step lookahead: reward when post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 22.0 * (-gap / 12.0).exp(); // strong reward for exact 2-step match
        // Penalize leftover that is smaller than next item (dead space for lookahead)
        if post_residual < next_item_size {
            score += 0.9 * (next_item_size - post_residual) as f64;
        }
        // Reward leftover that comfortably holds the next item
        else if post_residual >= next_item_size {
            score -= 4.0;
        }
    }

    // Relative-to-mean-residual coupling: bins with residual far below mean are
    // "almost full" — placing here consolidates waste; encourage that.
    let res = post_residual as f64;
    if res < mean_residual {
        score -= 1.5 * (mean_residual - res);
    } else {
        score += 0.6 * (res - mean_residual);
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
        // but still penalize very poor fits so new bin can win
        if post_residual < 10 {
            score += 14.0;
        }
    }

    // New-bin candidate handling: brand-new empty bin should only win when the
    // item is huge relative to capacity (poor fit anywhere) or stream is early
    // with few bins (future items benefit from a fresh bin).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fill = item_size as f64 / bin_capacity as f64;
        score = 100.0 - 30.0 * fill - 25.0 * (1.0 - progress) * (open_bins_count as f64 / 10.0);
        // If lookahead item is large, fresh bin is more attractive
        if next_item_size > 40 {
            score -= 10.0;
        }
    }

    // Slight penalty for proliferating bins when many are already open.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Penalize dead space relative to smallest plausible item (1..100 interface).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            let leftover = post_residual - next_item_size;
            score -= 15.0 - (leftover as f64).min(15.0);
        } else {
            // next item won't fit here; slight penalty for wasting space it could use
            score += 5.0;
        }
    }

    // Time horizon: early in stream, prefer keeping residuals large / flexible;
    // late in stream, exploit tight fits more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Global pressure: many open bins with high mean residual -> discourage spreading.
    if open_bins_count > 3 && mean_residual > item_size as f64 {
        score += 0.05 * (open_bins_count as f64).ln() * (mean_residual - item_size as f64);
    }

    // New-bin candidate: penalize mildly so it only wins when fits are terrible.
    if bin_residual == bin_capacity {
        score += 35.0;
        // But if no existing bin fits well, new bin becomes attractive.
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps sequence large items
        }
    }

    // Slight preference for fuller bins (small residual before placement).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1)

    // Base: prefer tight fits (low post residual), with quadratic smoothing.
    let mut score = x * x * cap + post;

    // Non-linear coupling with stream progress: early on, waste matters less
    // (bins may still be filled later); late in the stream, waste is permanent.
    let progress_coupling = 2.5 * x * (1.0 - x) * (0.5 - progress).abs() * cap;
    score += progress_coupling;

    // Cubic interaction: high progress + large residual => strong penalty.
    score += 1.8 * x.powi(3) * cap * progress;

    // Mean residual deviation: penalize bins far from the fleet mean (fragmentation).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 1.2 * dev * dev * cap;

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let gap = (post - nx) / cap;
            score -= (1.0 - gap) * 6.0 * (1.0 - progress);
        } else {
            score += 3.0 * (nx - post) / cap * cap * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 4.0 * progress;
    }

    // Mild penalty for proliferation of open bins when residual is large.
    score += 0.15 * open_bins_count as f64 * x;

    // New-bin candidate: neutral-ish baseline, slightly discouraged unless
    // current item is large relative to capacity.
    if bin_residual == bin_capacity {
        score = cap * (1.0 - item_size as f64 / cap) + 2.0 - 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= (bin_capacity as f64 - post_residual as f64) * 0.1;

    // Harmonic class of post_residual: reward residuals that are highly
    // divisible (many common divisors => more likely reusable by future items)
    let pr = post_residual;
    let mut div_count = 0u32;
    if pr > 0 {
        let lim = (pr as f64).sqrt() as u32;
        let mut d = 1u32;
        while d <= lim {
            if pr % d == 0 {
                div_count += 2;
                if d * d == pr { div_count -= 1; }
            }
            d += 1;
        }
    }
    score -= div_count as f64 * 0.5;

    // Modulo classes: penalize residuals that waste capacity in awkward bands
    let band = pr % 10;
    if band == 0 {
        score -= 3.0; // round residuals are highly reusable
    } else if band <= 3 {
        score += 1.0; // slivers
    } else if band >= 8 {
        score -= 1.0;
    }

    // Exact fit is excellent
    if pr == 0 {
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits post_residual exactly, big reward
    if next_item_size > 0 {
        if pr >= next_item_size {
            if pr == next_item_size {
                score -= 15.0;
            } else if pr % next_item_size == 0 {
                score -= 6.0;
            } else {
                score -= (pr - next_item_size) as f64 * 0.05;
            }
        } else {
            // next item won't fit here; penalize proportionally to wasted potential
            score += (next_item_size - pr) as f64 * 0.08;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented (high mean residual dispersion)
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // penalty grows if open bins are already tight (low mean residual)
        score += 8.0 + mean_residual * 0.15 - progress * 2.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
    } else {
        // Mild reward for keeping number of open bins low when tight
        score += open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but tiny unusable gaps are bad.
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual < 10 {
        score += 30.0; // dead space: gap too small for any item
    } else if post_residual <= 20 {
        score += 8.0; // mostly unusable gap
    } else {
        score -= 10.0; // usable residual
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size > post_residual {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            // penalize new bin when decent fits exist
            score += 15.0 + mean_residual * 0.5;
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            // Next item fits: strong bonus scaled by tightness of the fit.
            score -= 8.0 * (1.0 - gap / (post + 1.0));
            if gap < 1.0 {
                score -= 12.0; // perfect follow-up fill
            }
        } else {
            // Next item does not fit here: mild penalty proportional to overshoot.
            score += 0.05 * (nxt - post);
        }
    }

    // Penalize large dead space relative to capacity (unusable slivers).
    let post = post_residual as f64;
    if post > 0.0 && post < 10.0 {
        score += 6.0; // tiny sliver is nearly dead space
    }

    // Compare residual against mean residual across open bins:
    // prefer bins that are already fuller than average (best-fit tendency).
    score -= 0.5 * (mean_residual - post) / (bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Late in the stream, tighten packing (favor fuller bins more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * post * 0.1;

    // New-bin candidate: neutral-ish baseline, penalize slightly so we prefer
    // existing bins unless they are genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.2 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness * (item_size as f64 / 100.0);

    // Penalize dead space that is too small for typical items.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 15.0 * (10.0 - dead) / 10.0;
        }
        // Penalize residuals that cannot fit the lookahead item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 4.0;
        }
    }

    // Lookahead coupling: reward if post_residual exactly accommodates next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a bin unless it offers a very tight fit
    // or all open bins are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_penalty = 2.0 * (open_bins_count as f64).ln().max(0.0);
        score += 5.0 + open_penalty * (1.0 - progress);
        // If item nearly fills a fresh bin, opening is attractive.
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 6.0;
        }
    }

    // Mild preference for bins with residual close to the mean (balanced packing).
    score += 0.05 * ((bin_residual as f64 - mean_residual).abs());

    // Late in the stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (bin_residual == bin_capacity) as i32 as f64 * -1.0;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (penalize large post_residual more);
    // later, tolerate residual since bins are already sunk cost.
    let tightness = post / cap;
    let coupling = tightness * (1.0 + progress) * (1.0 - 0.5 * progress);
    score += 40.0 * coupling * coupling;

    // Reward near-perfect fits smoothly (quadratic decay of wasted space).
    let waste = post * post;
    score -= 0.35 * (cap - waste / cap);

    // Penalize leaving residual that fails to fit the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += 12.0 * (1.0 - post / nxt.max(1.0));
        } else {
            score -= 6.0 * (1.0 - (post - nxt) / cap).abs();
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // mild competition pressure: prefer bins with less residual among many options
        score += 0.05 * (open_bins_count as f64).ln().max(0.0);
    }

    // Mean-residual drift: discourage opening bins far from fleet mean residual early.
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev * dev * (1.0 - progress);

    // New-bin candidate: make empty bin attractive only when it is genuinely better
    // (i.e., when post_residual of empty bin is large and progress is low it should lose;
    //  when progress is high, allow it since open bins are scarce value).
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress) * (1.0 - progress);
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the item: coarse capacity fractions
    let item_class = item_size / 10; // 1..=10
    let next_class = next_item_size / 10;

    // Reward tight fits strongly
    score -= 30.0 * (1.0 - (post_residual as f64) / cap);

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for any plausible item (1..100)
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Harmonic pairing: does post_residual's class match next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits exactly-ish in the leftover: harmonic complement
            let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
            score -= 25.0 * (1.0 - diff as f64 / cap);
            if post_residual == next_item_size {
                score -= 40.0; // exact complement
            }
        } else {
            // leftover cannot host the next item: penalize proportionally
            score += 12.0 * (1.0 - (post_residual as f64) / cap);
        }
        // modulo-class coupling: same decade class pairs harmonically
        let pr_class = post_residual / 10;
        if pr_class == next_class {
            score -= 8.0;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening fresh bins unless residual is unusable
    if bin_residual == bin_capacity {
        score += 55.0;
        // but if the item is huge (>= 70% capacity), a fresh bin is fine
        if (item_size as f64) / cap >= 0.7 {
            score -= 70.0;
        }
    }

    // Prefer fuller bins when many bins are open (consolidation pressure)
    score -= 5.0 * (1.0 - (bin_residual as f64) / cap) * (open_bins_count as f64).ln().max(1.0);

    // Early stream: be slightly greedy on fills; late stream: consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Mean residual coupling: bins far below mean residual are worth filling
    score -= 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // (items are >= 1, but typical items are much larger), so penalize
    // post_residual in the "dead zone" heavily.
    let dead_threshold = 30.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Prefer bins whose residual was already fragmented (high residual means
    // we are consolidating space into fewer bins).
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    } else {
        score += (mean_residual - bin_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 3.0;
        // But a new bin is fine if nothing fits well anywhere.
        if fitting_bins_count <= 1 && (post_residual as f64) < dead_threshold {
            score -= 15.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, use it rather
    // than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as f64) < dead_threshold {
        score += 5.0;
    }

    // Early in the stream, tolerate more open bins (future flexibility).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }

    // Near-match lookahead: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize creating dead space below the smallest plausible item.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0;
    }

    // Compare against mean residual: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 8.0 * tightness;

    // Deviation from mean residual: prefer filling below-average-residual bins.
    score += 0.5 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins can fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // Early stream: opening bins is cheaper; late stream: consolidation preferred.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize small dead space that nothing can use later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this residual; penalize proportionally
            score += 6.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Time horizon: later in stream, prefer closing bins tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * tightness;

    // Global state: many open bins with slack -> prefer filling existing ones
    if open_bins_count > 2 {
        score += 3.0 * (post_residual as f64 - mean_residual).tanh();
    }

    // New-bin candidate: only attractive when current fit is bad or no real alternative
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > bin_capacity as f64 * 0.55;
        if bad_fit && (fitting_bins_count <= 1 || next_item_size > post_residual) {
            score -= 12.0;
        } else {
            score += 15.0;
        }
    }

    // Mild penalty for very low fill ratio of this placement
    score += 0.05 * (item_size as f64 / bin_capacity as f64).recip() * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (0.5 + 0.5 * progress) - pr_norm * (1.0 - progress);

    let mut score = pr;

    // Non-linear interaction: waste grows superlinearly with residual as stream progresses
    score += 40.0 * poly * cap * 0.01;

    // Penalize dead space that cannot fit the lookahead item (smooth quadratic falloff)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += 15.0 * (gap / cap) * (gap / cap) * cap;
    }

    // Reward tight fits smoothly
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * pr_norm;

    // New-bin candidate: penalize slightly so we prefer good existing fits
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space that is a small
    // remainder (mod small integers) is more likely reusable by future items.
    let pr = post_residual;
    if pr > 0 {
        // Penalize residuals that fall into "awkward" harmonic classes.
        // A residual divisible by 10 (or 5) is friendly to typical item sizes.
        let friendly = (pr % 10 == 0) as i32 + (pr % 5 == 0) as i32 + (pr % 20 == 0) as i32;
        score -= 6.0 * friendly as f64;

        // Very small dead space (< 10) is nearly worthless: penalize hard.
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Integer-division threshold: residual in [10, 30] can host a small item.
        if pr / 10 >= 1 && pr / 10 <= 3 {
            score -= 5.0;
        }
    } else {
        // Perfect fill: strongly reward.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 18.0 - 0.15 * slack;
        // Harmonic bonus: next item leaves a friendly remainder too.
        if (pr - next_item_size) % 10 == 0 {
            score -= 6.0;
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item cannot use this bin's leftover: mild penalty scaled by gap.
        score += 0.08 * ((next_item_size - pr) as f64).min(40.0);
    }

    // Last-chance bin: strongly prefer using it over opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current residuals
    // are large (item is a poor fit everywhere).
    if bin_residual == bin_capacity {
        // Neutral baseline; slight penalty so we prefer reusing decent fits.
        score += 12.0;
        // But if the item is huge relative to mean residual, opening is good.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 20.0;
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer tighter bins: compare residual to mean residual of open bins.
    score += 0.10 * (bin_residual as f64 - mean_residual).max(-30.0);

    // Prefer bins with small absolute waste fraction (capacity fractions).
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= 8.0 * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize "dead space": small unusable gaps (post_residual < 10) are wasted.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 {
        score += 18.0;
    } else if post_residual <= 25 {
        score += 6.0;
    }

    // Reward exact / near-perfect fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones,
    // discourage opening new bins unless residual is large and useful.
    let open_pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when item is large and stream is early.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + open_pressure + progress * 25.0;
        if item_size >= 50 {
            score -= 15.0;
        }
    } else {
        score -= open_pressure * 0.5;
    }

    // Prefer bins whose residual is already below the mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(-30.0).min(30.0) * 0.3;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if next_item_size > post_residual && next_item_size - post_residual < 10 {
            // next item would leave dead space here; slight penalty
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits here too: good chaining, reward proportional to tightness
            let tight = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 200.0 * tight;
        } else {
            // next item cannot use the leftover: penalize dead space relative to next size
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare post_residual against mean residual: avoid leaving more than average slack
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 300.0;
    }

    // New-bin candidate handling: neutral baseline, only attractive when open bins are poor fits
    if bin_residual == bin_capacity {
        // new bin slightly penalized so tight fits in existing bins win
        score += 50.0;
        // but if the item is large relative to capacity, a fresh bin is good
        score -= (item_size as f64 / bin_capacity as f64) * 120.0;
        // if next item is also large, fresh bin keeps flexibility
        if next_item_size >= 50 {
            score -= 40.0;
        }
    }

    // Early in the stream, encourage consolidation; late, allow more bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0;

    // Mild penalty for many open bins to discourage sprawl
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0 + 10.0 * (10 - post_residual) as f64;
    } else {
        // Penalize dead space that is too small for typical future items.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead_threshold = 10.0 + 20.0 * progress;
        if (post_residual as f64) < dead_threshold {
            score += 8.0 * (dead_threshold - post_residual as f64) / dead_threshold;
        }
    }

    // Lookahead: reward bins whose leftover could host the next item.
    if next_item_size > 0 && (post_residual as i64) >= (next_item_size as i64) {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Slight penalty if leftover nearly fits next item but not quite.
        if next_item_size as i64 - post_residual as i64 <= 5 {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual * 0.3;
        let fit_quality = if fitting_bins_count > 0 {
            (bin_residual - item_size) as f64
        } else {
            0.0
        };
        // Opening a new bin is penalized more early on and when good fits exist.
        score += 45.0 + pressure - (fit_quality - post_residual as f64).max(0.0);
        if fitting_bins_count <= 1 {
            score -= 20.0; // allow new bin when alternatives are scarce
        }
    }

    // Prefer filling bins with larger residuals among comparable fits.
    score -= 0.05 * bin_residual as f64;

    // Mild preference for keeping the number of open bins low.
    score += 0.5 * open_bins_count as f64;

    // Slight tilt toward bins deviating from mean residual (consolidation).
    score += 0.1 * ((bin_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.6 * x * x);

    // Smooth interaction: as stream progresses, tighten residual preference quadratically
    let tighten = 1.0 + 1.5 * progress * progress;
    score *= tighten;

    // Reward tight fits (post_residual near zero) with smooth cubic bonus
    let tight_bonus = (1.0 - x).powi(3) * item_size as f64 * 0.4;
    score -= tight_bonus;

    // Penalize residuals that cannot fit the next item (smooth hinge-free form)
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += (1.0 - fits_next) * (10.0 + 40.0 * gap * gap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - x + 0.5);
    }

    // Mild penalty when bin residual deviates from mean residual (diversity control)
    score += 0.05 * (mean_residual - bin_residual as f64).abs();

    // New-bin candidate: baseline score so it loses only against genuinely good fits
    if bin_residual == bin_capacity {
        score += 60.0 + 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity-fraction bands
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Perfect fit reward: post_residual exactly divisible into common harmonic classes
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward post_residuals that are "usable" harmonic sizes (multiples of 10, or small)
        if post_residual % 10 == 0 {
            score -= 5.0;
        }
        if post_residual <= 10 {
            score -= 8.0;
        } else if frac < 0.2 {
            score -= 4.0;
        } else if frac > 0.6 {
            // large dead space: penalize unless bin was fresh
            score += 6.0 * (frac - 0.6);
        }
    }

    // Integer-division thresholds: leftover chunks of size classes
    let chunk = post_residual / 20; // 0..5 harmonic chunk index
    score -= (chunk as f64) * 1.5;

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // next item fits: reward proportional to how snugly
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here: mild penalty proportional to gap
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let pressure = fitting_bins_count as f64;
        if pressure == 0.0 {
            score -= 5.0;
        } else {
            // discourage opening new bin when existing bins can take the item
            score += 15.0 + 5.0 * pressure.sqrt();
            // but allow new bin late in stream if mean residual is tiny
            if mean_residual < item_size as f64 {
                score -= 20.0;
            }
        }
    }

    // Mean residual alignment: prefer bins whose residual is near mean (balanced packing)
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Progress modulation: early on, be pickier about tight fits; late, just fill
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 3.0 * (1.0 - frac);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps in (0,10) are unusable for any item
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Exact fit is ideal
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins tighter than the average residual
    score -= (bin_residual as f64 - mean_residual) * 0.4;

    // Lookahead coupling: if next item fits into the post residual, reward it
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If post residual is small but nonzero and cannot fit the next item, penalize
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when no good existing fit exists
    if bin_residual == bin_capacity {
        score += 45.0 - (fitting_bins_count as f64) * 12.0;
    }

    // Mild late-stream consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}
